# AppUpdater - Copyright (c) 2026 Lyvvy-xyz. Licensed under the Business Source License 1.1.

param(
  [string]$Wv2AssemblyDir = (Join-Path $PSScriptRoot 'wv2')
)
$__UiHtml = @'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>AppUpdater</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700&family=Geist+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
:root{
  --void:#0D0E10; --panel:#131417; --panel-2:#191B1F;
  --edge:#24262B; --edge-hi:#31343A;
  --ink:#ECEAE4; --dim:#A3A19A; --faint:#8A8881; --rule:#1B1D21;
  --brand:#FF7A1A; --signal:#5468FF; --signal-2:#8FA0FF; --select:#1F2440;
  --ok:#4CC38A; --warn:#E5A93A; --bad:#EF5A5A;
  --code-str:#D6C49A;
  /* Channel values of the accent and status colours, for their translucent tints. */
  --signal-rgb:84,104,255; --signal-2-rgb:143,160,255; --ok-rgb:76,195,138; --warn-rgb:229,169,58; --bad-rgb:239,90,90;
  --on-accent:#FFFFFF;
  --ok-tint-bd:rgba(var(--ok-rgb),.3); --ok-tint-bg:rgba(var(--ok-rgb),.07);
  --warn-tint-bd:rgba(var(--warn-rgb),.3); --warn-tint-bg:rgba(var(--warn-rgb),.07);
  --grad:var(--signal);
  --r:8px; --r-sm:6px;
  --ease:cubic-bezier(.2,.8,.2,1);
  --font-d:'Geist','Segoe UI',system-ui,sans-serif; --font-b:'Geist','Segoe UI',system-ui,sans-serif; --font-m:'Geist Mono','Cascadia Mono',Consolas,monospace;
}
*{margin:0;padding:0;box-sizing:border-box}
[hidden]{display:none!important}
html,body{height:100%}
body{background:var(--void);color:var(--ink);font-family:var(--font-b);font-size:13.5px;line-height:1.5;overflow:hidden}
body::before{content:'';position:fixed;inset:0;pointer-events:none;
  background:radial-gradient(600px 400px at 12% -8%, rgba(var(--signal-rgb),.055), transparent 60%),
             radial-gradient(700px 500px at 105% 110%, rgba(var(--signal-2-rgb),.05), transparent 60%)}
::selection{background:rgba(var(--signal-rgb),.28)}
button{font:inherit;color:inherit;background:none;border:none;cursor:pointer}
input,textarea,select{font:inherit;color:inherit}

.app{display:grid;grid-template-columns:64px 1fr;grid-template-rows:100vh;height:100vh}
.rail{border-right:1px solid var(--edge);background:rgba(13,14,26,.6);display:flex;flex-direction:column;align-items:center;padding:14px 0 20px;gap:6px;z-index:5}
.logo{width:36px;height:36px;border-radius:9px;background:var(--grad);display:grid;place-items:center;margin-bottom:14px;box-shadow:0 0 24px rgba(var(--signal-rgb),.35);cursor:pointer}
.logo svg{transition:none}
.logo.spin svg{animation:logospin .6s cubic-bezier(.3,.1,.3,1)}
@keyframes logospin{to{transform:rotate(360deg)}}
.nav-btn{width:40px;height:40px;border-radius:9px;display:grid;place-items:center;color:var(--dim);
  transition:background .18s var(--ease),color .18s var(--ease),transform .18s var(--ease);position:relative}
.nav-btn:hover{background:var(--panel-2);color:var(--ink);transform:translateY(-1px)}
  #win-minimize:hover{background:var(--panel-2);color:var(--ink)}
  #win-close:hover{background:#e5484d;color:#fff}
.nav-btn.on{background:var(--panel-2);color:var(--signal)}
.nav-btn.on::before{content:'';position:absolute;left:-13px;top:9px;bottom:9px;width:2.5px;border-radius:2px;background:var(--grad)}
.nav-btn svg{width:19px;height:19px}
.rail .spacer{flex:1}
.nav-tip{position:absolute;left:52px;top:50%;translate:0 -50%;background:var(--panel-2);border:1px solid var(--edge);
  padding:4px 10px;border-radius:6px;font-size:11.5px;white-space:nowrap;opacity:0;pointer-events:none;
  transition:opacity .15s var(--ease),translate .15s var(--ease);z-index:50}
.nav-btn:hover .nav-tip{opacity:1;translate:4px -50%}

.stage{display:flex;flex-direction:column;min-width:0;height:100vh;min-height:0}
.rail{height:calc(100vh - 6px)}
.topbar{height:64px;border-bottom:1px solid var(--edge);display:flex;align-items:center;gap:22px;padding:0 26px;flex-shrink:0}
.crumb{font-family:var(--font-d);font-weight:600;font-size:15px;letter-spacing:.01em}

.pipe{display:flex;align-items:center;gap:0;margin-left:auto}
.pnode{display:flex;align-items:center}
.pnode[data-pipe-step]{cursor:pointer}
.card.pulse{animation:pulse 1s var(--ease)}
@keyframes pulse{0%{box-shadow:0 0 0 0 rgba(var(--signal-rgb),.55)}100%{box-shadow:0 0 0 14px rgba(var(--signal-rgb),0)}}
@media (prefers-reduced-motion:reduce){.card.pulse{animation:none}}
.pdot{width:26px;height:26px;border-radius:50%;border:1.5px solid var(--edge-hi);display:grid;place-items:center;
  font-family:var(--font-m);font-size:10px;color:var(--faint);position:relative;background:var(--panel);
  transition:border-color .4s var(--ease),color .4s var(--ease),box-shadow .4s var(--ease)}
.pdot .tick{position:absolute;inset:0;display:grid;place-items:center;opacity:0;transform:scale(.4);transition:opacity .3s var(--ease),transform .35s var(--ease)}
.pdot .tick svg{width:11px;height:11px;stroke:var(--on-accent);stroke-width:3;fill:none}
.pnode.done .pdot{background:var(--grad);border-color:transparent;color:transparent;box-shadow:0 0 14px rgba(var(--signal-rgb),.35)}
.pnode.done .pdot .tick{opacity:1;transform:scale(1)}
.pnode.live .pdot{border-color:var(--signal);color:var(--signal);animation:livepulse 1.6s var(--ease) infinite}
@keyframes livepulse{0%,100%{box-shadow:0 0 0 0 rgba(var(--signal-rgb),.35)}50%{box-shadow:0 0 0 6px rgba(var(--signal-rgb),0)}}
.plabel{font-size:10px;color:var(--faint);letter-spacing:.1em;text-transform:uppercase;margin-left:7px;transition:color .4s var(--ease)}
.pnode.done .plabel,.pnode.live .plabel{color:var(--dim)}
.pnode.live .plabel{color:var(--signal)}
.pline{width:34px;height:1.5px;background:var(--edge-hi);margin:0 10px;position:relative;overflow:hidden}
.pline i{position:absolute;inset:0;background:var(--grad);transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}
.pnode.done + .pline i{transform:scaleX(1)}
.pline.flow::after{content:'';position:absolute;top:-1.5px;width:10px;height:4.5px;border-radius:3px;background:var(--signal);
  filter:blur(.5px);box-shadow:0 0 8px var(--signal);animation:packet 1.1s linear infinite}
@keyframes packet{from{left:-12px}to{left:100%}}

#tour-overlay{position:fixed;inset:0;z-index:200;display:none}
#tour-spot{position:absolute;border-radius:10px;box-shadow:0 0 0 9999px rgba(4,4,10,.82);
  border:1.5px solid var(--signal);transition:top .35s var(--ease),left .35s var(--ease),width .35s var(--ease),height .35s var(--ease);pointer-events:none}
#tour-card{position:absolute;width:300px;background:var(--panel);border:1px solid var(--edge-hi);border-radius:12px;
  padding:18px;box-shadow:0 12px 40px rgba(0,0,0,.6);transition:top .35s var(--ease),left .35s var(--ease)}

body.reduce-motion *, body.reduce-motion *::before, body.reduce-motion *::after{
  animation-duration:.001ms!important;animation-delay:0s!important;animation-iteration-count:1!important;
  transition-duration:.001ms!important;transition-delay:0s!important;scroll-behavior:auto!important}

body.high-contrast{
  --ink:#FFFFFF; --dim:#C7C9DC; --faint:#8A8DB0;
  --edge:#4A4D70; --edge-hi:#7276A8; --panel:#0A0A14; --panel-2:#14152A}
body.high-contrast .card, body.high-contrast .field, body.high-contrast .btn{border-width:1.5px}

body.colorblind-safe{
  --ok:#0072B2; --warn:#E69F00; --bad:#D55E00;
  --ok-tint-bd:rgba(0,114,178,.3); --ok-tint-bg:rgba(0,114,178,.07);
  --warn-tint-bd:rgba(230,159,0,.3); --warn-tint-bg:rgba(230,159,0,.07);
}
body.colorblind-safe .badge.ok i, body.colorblind-safe .chip.g i{border-radius:50%}
body.colorblind-safe .badge.wn i, body.colorblind-safe .chip.w i{border-radius:1px;clip-path:polygon(50% 0,100% 50%,50% 100%,0 50%)}
body.colorblind-safe .toast.err b i{border-radius:1px}

:focus-visible{outline:2px solid var(--signal)!important;outline-offset:2px}

.screens{flex:1;position:relative;overflow:hidden}
.screen{position:absolute;inset:0;padding:26px 28px 32px;overflow-y:auto;
  opacity:0;pointer-events:none;transform:translateY(10px);transition:opacity .28s var(--ease),transform .28s var(--ease)}
.screen.on{opacity:1;pointer-events:auto;transform:none}
.screen::-webkit-scrollbar{width:9px}
.screen::-webkit-scrollbar-thumb{background:var(--edge);border-radius:5px;border:2px solid var(--void)}
.screen.on .rise{animation:rise .5s var(--ease) both}
.screen.on .rise:nth-child(2){animation-delay:.05s}
.screen.on .rise:nth-child(3){animation-delay:.1s}
.screen.on .rise:nth-child(4){animation-delay:.15s}
@keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}

.card{background:var(--panel);border:1px solid var(--edge);border-radius:var(--r);transition:border-color .2s var(--ease)}
.card:hover{border-color:var(--edge-hi)}
.build-cta{position:relative;border-color:rgba(var(--signal-rgb),.35);background:linear-gradient(180deg,rgba(var(--signal-rgb),.06),rgba(var(--signal-2-rgb),.03));
  transition:transform .18s var(--ease),border-color .18s var(--ease),box-shadow .18s var(--ease)}
.build-cta:hover{border-color:var(--signal);transform:translateY(-2px);box-shadow:0 10px 30px rgba(var(--signal-rgb),.18)}
.build-cta:hover .build-cta-arrow{transform:translateX(3px)}
.build-cta-arrow{transition:transform .18s var(--ease)}
.card-h{padding:14px 18px 0}
.eyebrow{font-family:var(--font-m);font-size:9.5px;letter-spacing:.16em;color:var(--faint);text-transform:uppercase}
.card-t{font-family:var(--font-d);font-weight:600;font-size:15px;margin-top:3px}
.card-b{padding:16px 18px 18px}
.lbl{font-size:11.5px;color:var(--dim);margin:0 0 5px;display:block}
.field{width:100%;background:var(--panel-2);border:1px solid var(--edge);border-radius:var(--r-sm);
  padding:9px 12px;font-size:12.5px;outline:none;transition:border-color .18s var(--ease),box-shadow .18s var(--ease)}
.field:hover{border-color:var(--edge-hi)}
.field:focus{border-color:var(--signal);box-shadow:0 0 0 3px rgba(var(--signal-rgb),.16),0 0 18px rgba(var(--signal-rgb),.10)}
.field.mono{font-family:var(--font-m);font-size:11.5px}
.hint{font-size:10.5px;color:var(--faint);margin-top:5px}
.row{display:grid;gap:14px}
.row.c2{grid-template-columns:1fr 1fr}
.mt{margin-top:14px}

.btn{display:inline-flex;align-items:center;gap:8px;padding:9px 16px;border-radius:var(--r-sm);
  background:var(--panel-2);border:1px solid var(--edge);color:var(--dim);font-size:12.5px;font-weight:500;transition:all .16s var(--ease)}
.btn:hover{color:var(--ink);border-color:var(--edge-hi);transform:translateY(-1px)}
.btn:active{transform:translateY(0) scale(.98)}
.btn.primary{background:var(--grad);border:none;color:var(--on-accent);font-weight:600;box-shadow:0 2px 14px rgba(var(--signal-rgb),.25)}
.btn.primary:hover{box-shadow:0 4px 22px rgba(var(--signal-rgb),.4);filter:brightness(1.06)}
.btn.big{padding:12px 26px;font-size:13.5px;border-radius:9px}
.btn.ghost{background:transparent}
.btn.danger{background:transparent;border-color:#4a1a1a;color:#cc6666}
.btn.sm{padding:6px 13px;font-size:11.5px}
.btn:disabled{opacity:.4;cursor:default;pointer-events:none}

.seg{position:relative;display:inline-flex;background:var(--panel-2);border:1px solid var(--edge);border-radius:9px;padding:3px;gap:2px}
.seg button{position:relative;z-index:1;padding:7px 16px;border-radius:6px;font-size:12px;font-weight:500;color:var(--dim);transition:color .2s var(--ease);white-space:nowrap}
.seg button.on{color:var(--ink)}
.seg .thumb{position:absolute;top:3px;bottom:3px;border-radius:6px;background:var(--void);border:1px solid var(--edge-hi);
  box-shadow:0 1px 6px rgba(0,0,0,.4);transition:left .22s var(--ease),width .22s var(--ease)}
.seg.accent .thumb{background:linear-gradient(135deg,rgba(var(--signal-rgb),.16),rgba(var(--signal-2-rgb),.16));border-color:rgba(var(--signal-rgb),.4)}
.seg.accent button.on{color:var(--signal)}

.drop{border:1.5px dashed var(--edge-hi);border-radius:var(--r);padding:30px 20px;text-align:center;transition:all .2s var(--ease);cursor:pointer;position:relative;overflow:hidden}
.drop:hover{border-color:var(--signal);background:rgba(var(--signal-rgb),.035)}
.drop:hover .drop-ico{transform:translateY(-3px);color:var(--signal)}
.drop-ico{color:var(--faint);transition:all .25s var(--ease);margin-bottom:8px}
.drop-ico svg{width:30px;height:30px}
.drop b{display:block;font-family:var(--font-d);font-weight:600;font-size:14px}
.drop span{font-size:11.5px;color:var(--dim)}

.chips{display:flex;flex-wrap:wrap;gap:7px;margin-top:12px}
.chip{display:inline-flex;align-items:center;gap:6px;background:var(--panel-2);border:1px solid var(--edge);
  border-radius:20px;padding:4px 11px;font-family:var(--font-m);font-size:10.5px;color:var(--dim);animation:chipin .4s var(--ease) both}
.chip:nth-child(2){animation-delay:.06s}.chip:nth-child(3){animation-delay:.12s}.chip:nth-child(4){animation-delay:.18s}
@keyframes chipin{from{opacity:0;transform:scale(.85)}to{opacity:1;transform:none}}
.chip i{width:6px;height:6px;border-radius:50%;background:var(--signal)}
.chip.g i{background:var(--ok)} .chip.w i{background:var(--warn)}
.chip.has-detail{cursor:pointer} .chip.has-detail:hover,.chip.has-detail:focus-visible{border-color:var(--signal);color:var(--ink);outline:none}
.chip-pop{position:fixed;z-index:60;max-width:330px;padding:10px 12px;border-radius:var(--r-sm);background:var(--panel);border:1px solid var(--edge);
  box-shadow:0 10px 30px rgba(0,0,0,.45);font-size:12px;line-height:1.5;color:var(--ink)}
.chip-pop .btn{margin-top:8px}

.tgl{position:relative;width:36px;height:20px;border-radius:20px;background:var(--panel-2);border:1px solid var(--edge);transition:all .2s var(--ease);flex-shrink:0}
.tgl::after{content:'';position:absolute;top:2px;left:2px;width:14px;height:14px;border-radius:50%;background:var(--dim);transition:all .22s var(--ease)}
.tgl.on{background:rgba(var(--signal-rgb),.2);border-color:rgba(var(--signal-rgb),.5)}
.tgl.on::after{left:18px;background:var(--signal);box-shadow:0 0 8px rgba(var(--signal-rgb),.6)}
.tgl:disabled{opacity:.4;cursor:not-allowed}
.tglrow{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 0}
.tglrow + .tglrow{border-top:1px solid var(--edge)}
.tglrow b{font-weight:500;font-size:12.5px;display:block}
.tglrow small{color:var(--faint);font-size:10.5px}

.buildbar{border-top:1px solid var(--edge);background:rgba(13,14,26,.85);backdrop-filter:blur(10px);padding:14px 28px;display:flex;align-items:center;gap:18px;flex-shrink:0}
.summary{font-family:var(--font-m);font-size:11px;color:var(--dim);flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.summary b{color:var(--signal);font-weight:500}
.summary .sep{color:var(--faint);margin:0 7px}

.fleet{width:100%;border-collapse:collapse}
.fleet th{font-family:var(--font-m);font-size:9.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--faint);text-align:left;padding:0 14px 10px;font-weight:400}
.fleet td{padding:13px 14px;border-top:1px solid var(--edge);font-size:12.5px}
.fleet tr.r{transition:background .15s var(--ease)}
.fleet tr.r:hover{background:rgba(var(--signal-rgb),.04)}
.fleet .mono{font-family:var(--font-m);font-size:11px;color:var(--dim)}
.badge{display:inline-flex;align-items:center;gap:6px;white-space:nowrap;font-size:10.5px;font-family:var(--font-m);padding:3px 10px;border-radius:20px;border:1px solid}
.badge.ok{color:var(--ok);border-color:var(--ok-tint-bd);background:var(--ok-tint-bg)}
.badge.wn{color:var(--warn);border-color:var(--warn-tint-bd);background:var(--warn-tint-bg)}
.badge i{width:5px;height:5px;border-radius:50%;background:currentColor}

.phase{display:flex;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid var(--edge);color:var(--faint);transition:color .3s var(--ease)}
.phase:last-child{border-bottom:none}
.phase .pi{width:20px;height:20px;border-radius:50%;border:1.5px solid var(--edge-hi);display:grid;place-items:center;flex-shrink:0;transition:all .3s var(--ease)}
.phase .pi svg{width:9px;height:9px;stroke:var(--on-accent);stroke-width:3.5;fill:none;opacity:0;transform:scale(.4);transition:all .25s var(--ease)}
.phase.doing{color:var(--ink)}
.phase.doing .pi{border-color:var(--signal)}
.phase.doing .pi::after{content:'';width:8px;height:8px;border-radius:50%;background:var(--signal);animation:livepulse 1.4s infinite}
.phase.did{color:var(--dim)}
.phase.did .pi{background:var(--grad);border-color:transparent}
.phase.did .pi svg{opacity:1;transform:scale(1)}
.log{background:#05050B;border:1px solid var(--edge);border-radius:var(--r-sm);font-family:var(--font-m);font-size:11px;line-height:1.75;padding:14px 16px;height:260px;overflow-y:auto}
.log div{opacity:0;animation:logline .3s var(--ease) forwards}
@keyframes logline{from{opacity:0;transform:translateX(-6px)}to{opacity:1;transform:none}}
.log .t{color:var(--faint);margin-right:10px}
.log .ok{color:var(--ok)} .log .in{color:var(--dim)} .log .ac{color:var(--signal)} .log .wr{color:var(--warn)}
.log::-webkit-scrollbar{width:8px}.log::-webkit-scrollbar-thumb{background:var(--edge);border-radius:4px}

.pbar{height:5px;border-radius:3px;background:var(--panel-2);overflow:hidden;position:relative}
.pbar i{display:block;height:100%;width:0;border-radius:3px;background:var(--grad);transition:width .5s var(--ease);position:relative;overflow:hidden}
.pbar i::after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent,rgba(255,255,255,.35),transparent);animation:shimmer 1.4s linear infinite}
@keyframes shimmer{from{transform:translateX(-100%)}to{transform:translateX(100%)}}

.done-ring{width:76px;height:76px;margin:0 auto 18px;position:relative}
.done-ring svg{width:100%;height:100%;transform:rotate(-90deg)}
.done-ring .rg{fill:none;stroke:var(--edge);stroke-width:3}
.done-ring .rp{fill:none;stroke:url(#gradstroke);stroke-width:3;stroke-linecap:round;stroke-dasharray:213;stroke-dashoffset:213;animation:ring .8s var(--ease) .1s forwards}
@keyframes ring{to{stroke-dashoffset:0}}
.done-ring .chk{position:absolute;inset:0;display:grid;place-items:center}
.done-ring .chk svg{width:30px;height:30px;transform:none;stroke:var(--ok);stroke-width:2.5;fill:none;stroke-dasharray:30;stroke-dashoffset:30;animation:ring .45s var(--ease) .75s forwards}
.sheet{background:var(--panel-2);border:1px solid var(--edge);border-radius:var(--r-sm);font-family:var(--font-m);font-size:11px}
.sheet .srow{display:flex;align-items:center;gap:12px;padding:10px 14px;border-bottom:1px solid var(--edge)}
.sheet .srow:last-child{border-bottom:none}
.sheet .sk{color:var(--faint);width:110px;flex-shrink:0;font-size:10px;letter-spacing:.08em;text-transform:uppercase}
.sheet .sv{color:var(--ink);flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sheet .sv.wrap{white-space:normal;line-height:1.45}
.copybtn{color:var(--faint);padding:4px;border-radius:5px;transition:all .15s var(--ease);flex-shrink:0}
.copybtn:hover{color:var(--signal);background:rgba(var(--signal-rgb),.1)}
.copybtn svg{width:13px;height:13px;display:block}

.toasts{position:fixed;bottom:22px;right:22px;display:flex;flex-direction:column;gap:10px;z-index:100}
.toast{background:var(--panel-2);border:1px solid var(--edge-hi);border-radius:9px;padding:12px 16px;min-width:280px;
  box-shadow:0 8px 32px rgba(0,0,0,.5);position:relative;overflow:hidden;animation:toastin .38s var(--ease)}
.toast.out{animation:toastout .3s var(--ease) forwards}
@keyframes toastin{from{opacity:0;transform:translateX(30px) scale(.96)}to{opacity:1;transform:none}}
@keyframes toastout{to{opacity:0;transform:translateX(30px) scale(.96)}}
.toast b{font-size:12.5px;font-weight:600;display:flex;align-items:center;gap:8px}
.toast b i{width:7px;height:7px;border-radius:50%;background:var(--ok);box-shadow:0 0 8px var(--ok)}
.toast.err b i{background:var(--bad);box-shadow:0 0 8px var(--bad)}
.toast p{font-size:11.5px;color:var(--dim);margin-top:3px}
.toast .life{position:absolute;bottom:0;left:0;height:2px;background:var(--grad);animation:life 4s linear forwards}
@keyframes life{from{width:100%}to{width:0}}
@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important}}
#screen-build{padding-top:16px;padding-bottom:16px}
#screen-build .card-h{padding:8px 18px 0}
#screen-build .card-b{padding:9px 18px 11px}
#screen-build .hint{margin-top:4px}
#screen-build .tglrow{padding:7px 0}
#bp-disclosure{display:flex;align-items:center;gap:6px;margin-top:8px;padding-top:8px;border-top:1px solid var(--edge);cursor:pointer;user-select:none;background:none;border-left:none;border-right:none;border-bottom:none;width:100%;text-align:left;color:var(--ink);font:inherit}
#bp-disclosure svg{width:12px;height:12px;transition:transform .15s var(--ease);flex-shrink:0}
#bp-disclosure.open svg{transform:rotate(90deg)}
#bp-disclosure.tour-click-sim{animation:tourClickSim .42s var(--ease)}
@keyframes tourClickSim{0%{box-shadow:0 0 0 0 rgba(var(--signal-rgb),.55)}30%{transform:scale(.96);box-shadow:0 0 0 6px rgba(var(--signal-rgb),.28)}100%{transform:scale(1);box-shadow:0 0 0 0 rgba(var(--signal-rgb),0)}}

/* Graphite with one ultramarine accent: actions and the current item only; amber, green and red mean status. */
body{font-size:13px}
body::before{display:none}
.rail{background:var(--panel)}
.logo{background:var(--brand);box-shadow:none;border-radius:7px}
.logo svg{stroke:#1A0D05 !important}
.nav-btn{border-radius:7px;position:relative}
.nav-btn:hover{transform:none}
.nav-btn.on{background:var(--select);color:var(--ink)}
.nav-btn.on::before{left:-11px;top:8px;bottom:8px;width:2px;border-radius:0;background:var(--signal)}
.nav-num{position:absolute;right:3px;bottom:1px;font:500 9px var(--font-m);color:var(--faint)}
.topbar{height:52px;gap:20px;padding:0 20px}
.crumb{font-size:13.5px;letter-spacing:-.01em}
.pdot{width:18px;height:18px;font:500 10px var(--font-m);border-width:1px}
.plabel{font:11.5px var(--font-m);letter-spacing:0;text-transform:none;color:var(--faint)}
.pnode.done .plabel,.pnode.live .plabel{color:var(--ink)}
.pline{width:22px;height:1px}
.card{box-shadow:none}
.eyebrow{letter-spacing:.06em}
.btn{border-radius:6px}
.btn.primary{background:var(--signal);color:var(--on-accent);box-shadow:none}
.btn.primary:hover{box-shadow:none;filter:brightness(1.08)}
.chip,.badge{border-radius:4px}
.tgl.on{background:var(--signal);border-color:var(--signal)}
.tgl.on::after{background:#fff}
.seg .thumb{background:var(--select);border-color:var(--signal)}
.buildbar{background:var(--panel);backdrop-filter:none;padding:12px 24px}
kbd{display:inline-flex;align-items:center;font:500 10.5px var(--font-m);color:var(--dim);padding:0 5px;border:1px solid var(--edge-hi);border-bottom-width:2px;border-radius:4px;background:var(--panel-2)}
.btn.primary kbd{color:#fff;border-color:rgba(0,0,0,.25);background:rgba(0,0,0,.2);margin-left:8px}
.statusbar{height:28px;flex-shrink:0;border-top:1px solid var(--edge);display:flex;align-items:center;gap:18px;padding:0 20px;font:11px var(--font-m);color:var(--faint)}
.statusbar .dot{color:var(--ok)} .statusbar .dot.off{color:var(--faint)} .statusbar .grow{flex:1}
/* Builder: a dense settings sheet on the left, the live manifest on the right. */
#screen-build{padding:0}
.builder{display:grid;grid-template-columns:minmax(560px,700px) minmax(0,1fr);min-height:100%}
.sheet-col{border-right:1px solid var(--edge);padding:18px 24px 24px;display:flex;flex-direction:column;gap:18px}
.bsec{display:flex;flex-direction:column}
.bsec-h{display:flex;align-items:center;gap:10px;margin-bottom:8px;min-height:28px}
.bsec-n{font:500 11px var(--font-m);color:var(--signal-2)}
.bsec-t{font-weight:600}
.bsec-rule{flex:1;height:1px;background:var(--edge)}
.brow{display:grid;grid-template-columns:150px minmax(0,1fr) 96px;align-items:center;gap:12px;min-height:40px;border-bottom:1px solid var(--rule)}
.brow:last-child{border-bottom:0}
.brow>label,.brow>.blbl{color:var(--dim)}
.brow .field{height:30px;padding:0 10px;font-size:12.5px}
.bsrc{font:11px var(--font-m);color:var(--faint);text-align:right;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bnote{font-size:12px;color:var(--faint)}
#screen-build.printer .app-only{display:none}
.seg-sm button{padding:5px 12px;font-size:12px}
.linkbtn{background:none;border:0;padding:0;color:var(--signal-2);font:12px var(--font-b);cursor:pointer}
.linkbtn:hover{text-decoration:underline}
.filecard{display:flex;align-items:center;gap:14px;padding:12px 14px;border:1px solid var(--edge);border-radius:8px;background:var(--panel)}
.filecard-ext{width:38px;height:38px;border-radius:6px;border:1px solid var(--edge-hi);display:grid;place-items:center;font:500 10px var(--font-m);color:var(--dim)}
.filecard-name{font-weight:600}
.filecard-sub{font-size:11.5px;color:var(--dim)}
.drop{padding:22px 16px}
.detect{display:flex;align-items:center;border:1px solid var(--edge-hi);border-radius:6px;overflow:hidden;width:max-content}
.detect button{height:28px;padding:0 12px;border:0;background:transparent;color:var(--dim);font:12px var(--font-b);cursor:pointer}
.detect button.on{background:var(--select);color:var(--ink)}
.detect-ge{padding:0 4px 0 10px;border-left:1px solid var(--edge-hi);color:var(--dim);font-family:var(--font-m)}
.detect .field{border:0;border-radius:0;background:transparent;height:28px;width:130px;padding:0 8px}
.detect .field:focus{box-shadow:none}
.detect:focus-within{border-color:var(--signal)}
.detect.min .detect-ge,.detect.min .field{background:var(--select);color:var(--ink)}
.procs{font:12px var(--font-m);display:flex;gap:6px;flex-wrap:wrap}
.procs .proc{padding:2px 8px;border-radius:4px;background:var(--panel-2);border:1px solid var(--edge)}
.extras-sum{display:flex;gap:16px;font-size:12px;color:var(--dim)} .extras-sum b{color:var(--ink);font-weight:500}
.extras{padding:6px 0 10px 162px;border-bottom:1px solid var(--rule)}
.scripts{display:grid;grid-template-columns:110px minmax(0,1fr) auto;gap:6px 8px;align-items:center;margin-top:8px}
.scripts label{color:var(--dim);font-size:12px} .scripts .field{height:28px;font-size:12px}
.wrap-profile{padding-top:6px}
.manifest-col{padding:18px 24px 24px;display:flex;flex-direction:column;gap:10px;min-width:0}
.mhead{display:flex;align-items:baseline;gap:10px} .mhead span{font-size:11.5px;color:var(--faint)}
.manifest{border:1px solid var(--edge);border-radius:8px;background:var(--panel);padding:12px 0;font-size:12.5px;line-height:1.75;overflow-x:auto}
.mline{display:grid;grid-template-columns:44px 112px minmax(0,1fr);padding-right:16px}
.mline .n{color:#4A4C52;text-align:right;padding-right:16px} .mline .k{color:var(--dim)} .mline .v{color:var(--ink);overflow-wrap:anywhere}
.mline .v.str{color:var(--code-str)} .mline .v.num{color:var(--signal-2)} .mline .v.dim{color:var(--faint)}
.check{display:grid;grid-template-columns:16px minmax(0,1fr);gap:8px;padding:9px 12px;border:1px solid var(--edge);border-radius:7px;background:var(--panel);margin-bottom:6px;font-size:12.5px}
.check .g{font-size:11px;line-height:1.7} .check.red .g{color:var(--bad)} .check.amber .g{color:var(--warn)} .check.ok .g{color:var(--ok)}
.check b{font-weight:600} .check span.t{color:var(--dim)}
#cmdk{position:fixed;inset:0;z-index:400;background:rgba(0,0,0,.55);display:flex;align-items:flex-start;justify-content:center;padding-top:14vh}
#cmdk[hidden]{display:none}
#cmdk .box{width:min(620px,92vw);background:var(--panel);border:1px solid var(--edge-hi);border-radius:10px;box-shadow:0 24px 60px rgba(0,0,0,.6);overflow:hidden}
#cmdk input{width:100%;border:0;border-bottom:1px solid var(--edge);background:transparent;color:var(--ink);font:14px var(--font-b);padding:14px 16px;outline:none}
#cmdk ul{list-style:none;margin:0;padding:6px;max-height:50vh;overflow:auto}
#cmdk li{display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:6px;cursor:pointer;color:var(--dim)}
#cmdk li .grp{font:10.5px var(--font-m);color:var(--faint);width:64px}
#cmdk li b{font-weight:500;color:var(--ink);flex:1}
#cmdk li.sel{background:var(--select)}
#cmdk .foot{display:flex;gap:14px;padding:8px 14px;border-top:1px solid var(--edge);font:11px var(--font-m);color:var(--faint)}
.cmd-btn{display:flex;align-items:center;gap:8px;height:30px;padding:0 10px;border-radius:6px;border:1px solid var(--edge);background:var(--panel);color:var(--dim);font:12px var(--font-b);cursor:pointer;margin-left:auto}

/* Shared page frame: a one-line header, then content that fills the window. */
.screen.page-flush{padding:0}
.page{padding:16px 24px 24px;display:flex;flex-direction:column;gap:12px;min-height:100%}
.phead{display:flex;align-items:center;gap:12px;min-height:32px}
.phead h1,.phead h2{margin:0;font:600 15px var(--font-b);letter-spacing:-.01em}
.phead .grow,.side-h .grow{flex:1}
.pmeta{font:11.5px var(--font-m);color:var(--faint)}
.pill{font:11px var(--font-m);padding:2px 8px;border-radius:4px;border:1px solid var(--edge-hi);color:var(--dim)}
.pill.warn{color:var(--warn);border-color:rgba(var(--warn-rgb),.4)}
.dim{color:var(--dim)} .linkbtn.dim{color:var(--faint)}
.split{display:grid;grid-template-columns:minmax(0,1fr) minmax(320px,400px);min-height:100%}
.split-main{padding:16px 24px 24px;display:flex;flex-direction:column;gap:12px;min-width:0;border-right:1px solid var(--edge)}
.split-side{padding:16px 20px 24px;display:flex;flex-direction:column;gap:12px;min-width:0;background:var(--panel)}
.side-h{display:flex;align-items:center;gap:10px;min-height:28px}
.side-h b{font-weight:600}
.side-card{border:1px solid var(--edge);border-radius:8px;padding:10px 12px;background:var(--void)}
.side-p{font-size:12px;color:var(--dim);margin:2px 0 10px}
.side-card .tglrow{padding:6px 0;font-size:12.5px}
.notice{display:flex;align-items:center;gap:10px;padding:8px 12px;border:1px solid rgba(var(--signal-rgb),.4);border-radius:8px;font:12px var(--font-m);color:var(--signal-2)}
.notice span{flex:1}
.demo-log{font:11.5px/1.9 var(--font-m)} .demo-log .ok{color:var(--ok)} .demo-log .warn{color:var(--warn)}
/* Home queue */
.queue{list-style:none;margin:0;padding:0;border:1px solid var(--edge);border-radius:8px;background:var(--panel);overflow:hidden}
.queue:empty{display:none}
.qrow{display:grid;grid-template-columns:22px minmax(0,1fr) auto;align-items:center;gap:12px;padding:11px 14px;border-bottom:1px solid var(--rule);cursor:default}
.qrow:last-child{border-bottom:0}
.qrow.sel{background:var(--select);box-shadow:inset 2px 0 0 var(--signal)}
.qg{text-align:center;font-size:12px} .qg.bad{color:var(--bad)} .qg.warn{color:var(--warn)} .qg.sig{color:var(--signal-2)} .qg.ok{color:var(--ok)}
.qrow b{font-weight:600} .qd{color:var(--dim)} .qm{font:11.5px var(--font-m);color:var(--faint);margin-top:1px}
.qa{display:flex;gap:6px}
.newrow{display:flex;align-items:center;gap:12px;padding:11px 14px;border:1px dashed var(--edge-hi);border-radius:8px;cursor:pointer;color:var(--ink)}
.newrow:hover,.newrow:focus-visible{border-color:var(--signal);background:var(--select)}
.newrow b{font-weight:600} .newrow kbd{margin-left:auto}
.newrow-plus{width:22px;text-align:center;color:var(--signal-2);font:500 16px var(--font-m)}
.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid var(--edge);border-radius:8px;overflow:hidden;margin-top:auto}
.stats>div{padding:12px 14px;border-right:1px solid var(--edge);display:flex;flex-direction:column;gap:2px}
.stats>div:last-child{border-right:0}
.stats b{font:500 20px var(--font-m);letter-spacing:-.02em} .stats span{font-size:12px;color:var(--dim)}
.actlog{font:12px/1.85 var(--font-m);display:flex;flex-direction:column}
.actlog .al{display:grid;grid-template-columns:46px 14px minmax(0,1fr);gap:8px}
.actlog .al .t{color:var(--faint)} .actlog .al .x{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--dim)}
.actlog .al .ok{color:var(--ok)} .actlog .al .warn{color:var(--warn)} .actlog .al .sig{color:var(--signal-2)}
.actlog .none{font-family:var(--font-b);color:var(--faint)}
/* Data grid used by Fleet and History */
.fchips{display:flex;gap:6px;flex-wrap:wrap}
.fchip{height:28px;padding:0 10px;border-radius:6px;border:1px solid var(--edge);background:transparent;color:var(--dim);font:12px var(--font-b);cursor:pointer;display:flex;align-items:center;gap:6px}
.fchip span{font:11px var(--font-m);color:var(--faint)}
.fchip.on{border-color:var(--signal);background:var(--select);color:var(--ink)}
.bulkbar{display:flex;align-items:center;gap:10px;padding:6px 10px;border:1px solid var(--signal);border-radius:8px;background:var(--select);font-size:12.5px}
.grid-wrap{border:1px solid var(--edge);border-radius:8px;background:var(--panel);overflow:visible}
table.grid{width:100%;border-collapse:collapse;table-layout:fixed}
.grid th{height:34px;padding:0 12px;text-align:left;font:500 10.5px var(--font-m);letter-spacing:.05em;text-transform:uppercase;color:var(--faint);border-bottom:1px solid var(--edge)}
.grid td{height:50px;padding:0 12px;border-bottom:1px solid var(--rule);vertical-align:middle}
.grid tr:last-child td{border-bottom:0}
.grid tr.r:hover td{background:rgba(255,255,255,.015)}
.grid .nm{font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.grid .id{font:11.5px var(--font-m);color:var(--faint);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.grid .mono{font:12px var(--font-m)} .grid .newer{color:var(--signal-2)}
.grid .st{font-size:12.5px;white-space:nowrap} .st.bad{color:var(--bad)} .st.warn{color:var(--warn)} .st.sig{color:var(--signal-2)} .st.ok{color:var(--ok)} .st.dim{color:var(--faint)}
.grid .next{display:flex;gap:6px;justify-content:flex-end;align-items:center}
.grid td.empty-cell{height:auto;padding:28px 16px;color:var(--faint)}
.ledger{display:flex;gap:10px}
.ledger .lv{display:flex;flex-direction:column;align-items:center;gap:3px}
.ledger .sq{display:flex;gap:2px} .ledger .sq i{width:7px;height:7px;border-radius:1.5px;background:#2A2C31}
.ledger .sq i.b{background:var(--faint)} .ledger .sq i.t{background:var(--signal-2)} .ledger .sq i.d{background:var(--ink)} .ledger .sq i.o{background:var(--ok)} .ledger .sq i.x{background:var(--bad)}
.ledger .lv span{font:9.5px var(--font-m);color:var(--faint)}
.legend{font:10px var(--font-m);color:var(--faint);text-transform:none;letter-spacing:0}
.rowmenu{position:relative}
.rowmenu summary{list-style:none;width:28px;height:28px;border-radius:6px;border:1px solid var(--edge-hi);display:grid;place-items:center;cursor:pointer;color:var(--dim)}
.rowmenu summary::-webkit-details-marker{display:none}
.rowmenu[open] summary{background:var(--select);color:var(--ink)}
.rowmenu>div{position:absolute;right:0;top:32px;z-index:30;min-width:180px;padding:4px;border:1px solid var(--edge-hi);border-radius:8px;background:var(--panel-2);box-shadow:0 12px 30px rgba(0,0,0,.5);display:flex;flex-direction:column}
.rowmenu>div button{text-align:left;border:0;background:transparent;color:var(--ink);font:12.5px var(--font-b);padding:7px 10px;border-radius:5px;cursor:pointer}
.rowmenu>div button:hover{background:var(--select)} .rowmenu>div button.danger{color:var(--bad)}
.empty{padding:40px 20px;text-align:center;border:1px dashed var(--edge-hi);border-radius:8px}
.empty b{font-weight:600} .empty p{color:var(--dim);font-size:12.5px;margin:6px 0 14px}
/* Progress and done */
.pbar{height:3px;border-radius:2px;background:var(--edge);overflow:hidden} .pbar i{display:block;height:100%;width:0;background:var(--signal);transition:width .3s}
.log-tall{flex:1;min-height:320px;margin:0}
#step-list .phase{padding:8px 0;border-bottom:1px solid var(--rule);font:12px var(--font-m)}
.okmark{color:var(--ok);font-size:15px}
#done-path{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.steps{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;border:1px solid var(--edge);border-radius:8px;background:var(--void)}
.steps li{display:grid;grid-template-columns:24px minmax(0,1fr);gap:10px;padding:12px 14px;border-bottom:1px solid var(--rule)}
.steps li:last-child{border-bottom:0}
.steps .sn{width:22px;height:22px;border-radius:50%;border:1px solid var(--edge-hi);display:grid;place-items:center;font:500 11px var(--font-m);color:var(--dim)}
.steps li.did .sn{border-color:var(--ok);color:var(--ok)} .steps li.now .sn{border-color:var(--signal);color:var(--signal-2)}
.steps li.did b{color:var(--dim)}
.steps p{margin:2px 0 8px;font-size:12px;color:var(--dim)}
.steps li:not(.now) .btn.primary{background:transparent;color:var(--ink);border:1px solid var(--edge-hi)}
/* Settings */
.cols2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 40px}
.cols2>div{display:flex;flex-direction:column;gap:18px}
.srow2{display:grid;grid-template-columns:120px minmax(0,1fr);gap:12px;align-items:center;min-height:40px;border-bottom:1px solid var(--rule)}
.srow2 .k{color:var(--dim)}
#screen-worker .tglrow{padding:10px 0;border-top:0;border-bottom:1px solid var(--rule)}
#screen-worker .tglrow small{display:block;color:var(--faint);font-size:12px;margin-top:2px;max-width:520px}
#screen-worker .tglrow b{font-weight:500}
.grid td.dayrow{height:30px;font:500 11px var(--font-m);color:var(--dim);background:var(--panel-2);letter-spacing:.02em}
.phead .field,.srow2 .field,.pf-ctx .field{padding-top:0;padding-bottom:0;line-height:28px}
.dlg{width:min(760px,92vw);max-height:86vh;display:flex;flex-direction:column;background:var(--panel);border:1px solid var(--edge-hi);border-radius:10px;box-shadow:0 24px 60px rgba(0,0,0,.6)}
.dlg-h{display:flex;align-items:center;gap:12px;padding:14px 18px;border-bottom:1px solid var(--edge)}
.dlg-h h2{margin:0;font:600 14px var(--font-b)}
.dlg-b{padding:12px 18px 6px}
.dlg-opt{display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--dim);cursor:pointer;padding:3px 0}
.dlg-opt input{accent-color:var(--signal)}
.dlg #test-log{margin:6px 18px 0;flex:1;min-height:240px;max-height:52vh}
.dlg-f{display:flex;justify-content:flex-end;gap:8px;padding:12px 18px;border-top:1px solid var(--edge);margin-top:12px}
.badge.bad{color:var(--bad);border-color:var(--bad)}
.epm-row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:10px;align-items:center;padding:8px 0;border-bottom:1px solid var(--rule)}
.epm-row small{display:block;color:var(--faint);font-size:11px;overflow-wrap:anywhere}
.cov{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1.6fr) auto;gap:12px;align-items:center;padding:9px 0;border-bottom:1px solid var(--rule)}
.cov b{display:block;font-size:12.5px} .cov small{display:block;color:var(--faint);font-size:11.5px;overflow-wrap:anywhere}
.cov .st{font-size:12px} .cov .st.ok{color:var(--ok)} .cov .st.warn{color:var(--warn)} .cov .st.dim{color:var(--faint)}
.pol{border:1px solid var(--edge);border-radius:var(--r-sm);padding:10px 12px;margin:0 0 10px}
.pol h3{margin:0;font:600 13px var(--font-b)} .pol .meta{color:var(--faint);font-size:11.5px;margin:2px 0 6px}
.rule{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(0,1fr) auto;gap:10px;align-items:center;padding:5px 0;border-top:1px solid var(--rule);font-size:12px}
.rule .mono{font-family:var(--font-m);font-size:11px;color:var(--dim);overflow-wrap:anywhere}
.wz-dots{display:flex;gap:6px;margin:0 0 12px} .wz-dots i{flex:1;height:3px;border-radius:2px;background:var(--edge)} .wz-dots i.on{background:var(--signal)}
.wz-lead{margin:0 0 10px;font-size:13px;color:var(--ink)}
.wz-rows{display:grid;gap:8px;margin:0 0 6px}
.wz-row{display:grid;grid-template-columns:30px minmax(0,1fr) auto;gap:10px;align-items:center;padding:9px 11px;border:1px solid var(--edge);border-radius:var(--r-sm);background:var(--panel-2)}
.wz-ic{width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:rgba(var(--signal-rgb),.14);color:var(--signal);font:600 12px var(--font-m)}
.wz-row.ok .wz-ic{background:rgba(var(--ok-rgb),.14);color:var(--ok)} .wz-row.warn .wz-ic{background:rgba(var(--warn-rgb),.14);color:var(--warn)}
.wz-row b{display:block;font-size:12.5px} .wz-row small{display:block;color:var(--faint);font-size:11.5px;overflow-wrap:anywhere}
.wz-row code{font:11px var(--font-m);color:var(--dim)}
.wz-note{margin:8px 0 0;font-size:11.5px;color:var(--faint)}
#ui-dlg.wide .dlg{width:min(980px,94vw)!important}
#ui-dlg.wide .ui-choice{grid-template-columns:repeat(auto-fit,minmax(260px,1fr))}
.runs{display:grid;gap:6px;margin:8px 0 0}.run{border:1px solid var(--edge);border-radius:var(--r-sm);padding:8px 10px}
.run b{font-size:12.5px}.run .ri{display:grid;grid-template-columns:16px minmax(0,1fr);gap:6px;font-size:11.5px;color:var(--dim);padding:2px 0}
.run .ri.ok i{color:var(--ok)}.run .ri.bad i{color:var(--bad)}.run .ri.warn i{color:var(--warn)}.run .ri i{font-style:normal}
.sw{position:relative;overflow:hidden;margin-top:6px;border-top:1px solid var(--edge)}
.sw-in{position:absolute;left:0;top:0;width:948px;height:280px;transform-origin:0 0;--sw-gh:#4ade9b;--sw-az:#f0a35e}
.sw-line{position:absolute;border-radius:3px;background:var(--signal)}.sw-line.gh{background:var(--sw-gh)}.sw-line.az{background:var(--sw-az)}
.sw-line.off,.sw-tag.off,.sw-stop.off{opacity:.32}.sw-line.dim,.sw-stop.dim{opacity:.3}
.sw-dash{position:absolute;height:0;border-top:3px dashed var(--edge-hi)}.sw-note{position:absolute;font-size:10.5px;color:var(--faint)}
.sw-tag{position:absolute;font:10.5px var(--font-m)}.sw-tag.gh{color:var(--sw-gh)}.sw-tag.az{color:var(--sw-az)}
.sw-stop{position:absolute;width:20px;display:flex;flex-direction:column;align-items:center}
.sw-stop i{display:block;width:14px;height:14px;border-radius:50%;background:var(--void);border:3px solid var(--c,var(--signal));transition:background .3s,box-shadow .3s}
.sw-stop.big i{width:18px;height:18px;border-width:4px;--c:var(--signal)}
.sw-stop.on i{background:var(--c,var(--signal));box-shadow:0 0 0 5px rgba(var(--signal-rgb),.2)}.sw-stop.bad i{background:var(--bad);border-color:var(--bad)}
.sw-stop span{position:absolute;top:24px;width:96px;text-align:center;font-size:10.5px;line-height:1.25;color:var(--ink)}.sw-stop.big span{width:116px;font-size:12px;font-weight:600}
.sw-stop span.up{top:auto;bottom:22px}.sw-stop.big span.up{bottom:28px}.sw-stop em{font-style:normal;color:var(--warn)}.sw-stop small{font-size:10.5px;font-weight:400;color:var(--dim)}
.sw-train{position:absolute;width:14px;height:14px;border-radius:50%;background:#fff;box-shadow:0 0 14px 5px rgba(74,222,155,.85);transition:left .85s ease-in-out,top .85s ease-in-out;z-index:3}
.sw-train.az{box-shadow:0 0 14px 5px rgba(240,163,94,.85)}.sw-train.bad{box-shadow:0 0 14px 5px rgba(255,107,107,.9)}
.sw-bubble{position:absolute;width:230px;padding:6px 10px;border-radius:8px;background:var(--panel);border:1px solid var(--edge-hi);box-shadow:0 8px 24px rgba(0,0,0,.45);z-index:2;transition:left .85s ease-in-out,top .85s ease-in-out}
.sw-bubble b{display:block;font:10px var(--font-m);color:var(--signal)}.sw-bubble span{font-size:11.5px;line-height:1.35}
.sw-bubble.ok{border-color:var(--ok)}.sw-bubble.ok b{color:var(--ok)}.sw-bubble.bad{border-color:var(--bad)}.sw-bubble.bad b{color:var(--bad)}.sw-bubble.warn{border-color:var(--warn)}.sw-bubble.warn b{color:var(--warn)}
@media (prefers-reduced-motion:reduce){.sw-train,.sw-bubble,.sw-stop i{transition:none}}
#ui-dlg.wide .wz-rows{grid-template-columns:repeat(3,minmax(0,1fr))}
.modal{position:fixed;inset:0;background:rgba(5,5,10,.65);z-index:95;display:flex;align-items:center;justify-content:center}
.ui-text{margin:0 0 10px;white-space:pre-line}
.ui-field{margin:0 0 10px} .ui-field .field{height:32px;padding:0 10px} .ui-field small{display:block;color:var(--faint);font-size:11.5px;margin-top:3px}
.ui-choice{border:0;margin:0 0 10px;padding:0;display:grid;gap:6px}
.ui-opt{display:flex;gap:10px;align-items:flex-start;padding:9px 11px;border:1px solid var(--edge);border-radius:var(--r-sm);cursor:pointer}
.ui-opt:has(input:checked){border-color:var(--signal);background:rgba(var(--signal-rgb),.06)}
.ui-opt.danger:has(input:checked){border-color:var(--bad);background:rgba(var(--bad-rgb),.06)}
.ui-opt input{margin-top:3px;accent-color:var(--signal)} .ui-opt b{display:block;font-size:12.5px} .ui-opt small{display:block;color:var(--faint);font-size:11.5px;white-space:pre-line}
.ui-err{margin:8px 18px 0;color:var(--bad);font-size:12px}
#ui-dlg-log{margin:6px 18px 0;height:auto;min-height:120px;max-height:46vh}
#ui-dlg-log .ok{color:var(--ok)} #ui-dlg-log .warn{color:var(--warn)} #ui-dlg-log .bad{color:var(--bad)} #ui-dlg-log .step{color:var(--ink)} #ui-dlg-log .info{color:var(--faint)}
.btn.danger-solid{background:var(--bad);border-color:var(--bad);color:#fff}
.wk-value{margin:6px 0 8px 18px;font-size:12.5px;color:var(--dim)} .wk-value li{padding:1px 0}
.wk-act{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center;padding:9px 0;border-bottom:1px solid var(--rule)}
.wk-act b{display:block;font-size:12.5px} .wk-act small{display:block;color:var(--faint);font-size:11.5px}
.wk-act.warn b{color:var(--warn)}
.wiz-steps{display:flex;gap:6px;list-style:none;margin:0;padding:10px 18px 0;counter-reset:w}
.wiz-steps li{flex:1;counter-increment:w;font:500 11px var(--font-m);color:var(--faint);border-top:2px solid var(--edge);padding-top:6px}
.wiz-steps li::before{content:counter(w) ' '}
.wiz-steps li.on{color:var(--ink);border-color:var(--signal)} .wiz-steps li.done{color:var(--dim);border-color:var(--ok)}
.wiz-pick{align-items:flex-start;padding:8px 0} .wiz-pick small{display:block;color:var(--faint);font-size:11.5px}
.wiz-list{margin:6px 0 8px 18px;font-size:12.5px;color:var(--dim)} .wiz-list li{padding:2px 0}
.wiz-progress{list-style:none;margin-left:0} .wiz-progress li::before{display:inline-block;width:18px;content:'\25CB';color:var(--faint)}
.wiz-progress li.done::before{content:'\2713';color:var(--ok)} .wiz-progress li.now::before{content:'\25D0';color:var(--signal)} .wiz-progress li.bad::before{content:'\2715';color:var(--bad)}
.wiz-warn{color:var(--warn)}
.epm-code{font:600 18px var(--font-m);letter-spacing:.12em;color:var(--signal)}
#epm-add .field{margin-bottom:8px}
/* Builder: the three choices that shape the rest of the form */
.choices{display:grid;gap:10px;padding:14px 16px;margin-bottom:14px;border:1px solid var(--edge);border-radius:10px;background:var(--panel)}
.choice{display:grid;grid-template-columns:210px auto minmax(0,1fr);gap:12px;align-items:center}
.choice-q{font-size:13px;color:var(--ink)}
.choice-q b{display:inline-grid;place-items:center;width:20px;height:20px;margin-right:6px;border-radius:50%;background:var(--brand);color:#1A0D05;font:600 11px var(--font-m)}
.choice-hint{font-size:11.5px;color:var(--faint)}
.seg button[disabled]{opacity:.35;cursor:not-allowed}
@media (max-width:1100px){.choice{grid-template-columns:1fr}}
#screen-build.epm #sec-configure,#screen-build.epm #sec-wrap,#screen-build.epm #choice-delivery,#screen-build.printer #choice-delivery{display:none}
#sec-epm{display:none}
#screen-build.epm #sec-epm{display:block}
#screen-build.simple #runtime-url-row{display:none}
#done-sheet .dgroup{border-bottom:1px solid var(--edge);padding-bottom:6px}
#done-sheet .dgroup h3{display:flex;align-items:center;gap:8px;margin:0;padding:12px 14px 2px;font:600 13px var(--font-b);color:var(--ink)}
#done-sheet .dgroup h3 span{display:inline-grid;place-items:center;width:18px;height:18px;border-radius:50%;background:var(--brand);color:#1A0D05;font:600 10.5px var(--font-m)}
#done-sheet .dgroup p{margin:2px 14px 4px 40px;font-size:12px;color:var(--faint)}
#done-sheet .dgroup .srow{border-bottom:0;padding:6px 14px 6px 40px}
/* Profiles */
.pf-layout{display:grid;grid-template-columns:260px 340px minmax(0,1fr);min-height:100%}
.pf-list{padding:16px 16px 24px;border-right:1px solid var(--edge);background:var(--panel)}
#profiles-strip{display:flex;flex-direction:column;gap:4px}
.pf-item{display:flex;flex-direction:column;gap:1px;text-align:left;padding:9px 10px;border-radius:6px;border:1px solid transparent;background:transparent;color:var(--ink);font:13px var(--font-b);cursor:pointer}
.pf-item span{font-size:11.5px;color:var(--faint)} .pf-item b{font-weight:500}
.pf-item:hover{background:var(--panel-2)} .pf-item.on{background:var(--select);border-color:var(--signal)}
.pf-item.new b{color:var(--signal-2)}
.pf-form{padding:16px 20px 24px;border-right:1px solid var(--edge)}
.pf-preview{padding:16px 24px 24px;min-width:0}
.pf-ctx{display:flex;align-items:center;gap:10px;margin-bottom:10px;font-size:12px;color:var(--dim)}
.pf-ctx .field{width:220px;height:30px;font-size:12.5px}
.pf-ctx label+.seg{margin-left:-2px}
@media (max-width:1100px){.split{grid-template-columns:1fr}.cols2{grid-template-columns:1fr}
  .pf-layout{grid-template-columns:220px minmax(0,1fr)}.pf-list{grid-row:span 2}.pf-form{border-right:0;border-bottom:1px solid var(--edge)}}
.crumb,.cmd-btn{white-space:nowrap}
/* Below this the manifest column is too narrow to read, and five step labels push the window buttons off. */
@media (max-width:1240px){.builder{grid-template-columns:minmax(0,1fr)}.plabel{display:none}.pnode.live .plabel{display:inline}
  #fleet-table col:nth-child(5){display:none}#fleet-table tr>:nth-child(5){display:none}#fleet-table col:nth-child(3){width:130px!important}#fleet-table col:nth-child(7){width:170px!important}}
</style>
</head>
<body>
<svg width="0" height="0"><defs><linearGradient id="gradstroke" x1="0" y1="0" x2="1" y2="1">
<stop offset="0" stop-color="#5EA2FF"/><stop offset="1" stop-color="#8B7CFF"/></linearGradient></defs></svg>

<div class="app">
  <nav class="rail">
    <div class="logo" title="AppUpdater"><svg viewBox="0 0 24 24" width="19" height="19" fill="none" style="stroke:var(--on-accent)" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12a8 8 0 0 1 14-5.2M20 12a8 8 0 0 1-14 5.2"/><path d="M17.5 4.5v3h-3M6.5 19.5v-3h3"/></svg></div>
    <button class="nav-btn on" data-go="home"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 12l9-8 9 8M5 10v10h5v-6h4v6h5V10"/></svg><span class="nav-tip">Home</span></button>
    <button class="nav-btn" data-go="build"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/><path d="M3.3 7l8.7 5 8.7-5M12 22V12"/></svg><span class="nav-tip">Package builder</span></button>
    <button class="nav-btn" data-go="fleet"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="4" width="7" height="7" rx="1.3"/><path d="M13 5h8M13 8.5h8M3 15h18M3 18.5h12"/></svg><span class="nav-tip">App fleet</span></button>
    <button class="nav-btn" data-go="profiles"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="4" width="7" height="7" rx="1.5"/><rect x="14" y="4" width="7" height="7" rx="1.5"/><rect x="3" y="15" width="7" height="7" rx="1.5"/><rect x="14" y="15" width="7" height="7" rx="1.5"/></svg><span class="nav-tip">Client profiles</span></button>
    <button class="nav-btn" data-go="history"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 3v5h5"/><path d="M3.05 13a9 9 0 1 0 2.13-7.83L3 8"/><path d="M12 7v5l4 2"/></svg><span class="nav-tip">History</span></button>
    <button class="nav-btn" data-go="worker"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg><span class="nav-tip">Worker &amp; settings</span></button>
    <div class="spacer"></div>

    <button class="nav-btn" data-go="docs" title="Docs &amp; help"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 0c0 1.5-2.5 1.8-2.5 3.5"/><circle cx="12" cy="17" r=".6" fill="currentColor" stroke="none"/></svg><span class="nav-tip">Docs &amp; help</span></button>
  </nav>

  <div class="stage">
    <div class="topbar" id="drag-region" style="cursor:move">
      <div class="crumb" id="crumb">AppUpdater</div>
      <div class="pipe" id="pipe" style="display:none"></div>
      <button type="button" class="cmd-btn" id="cmd-open">Search or run a command <kbd>Ctrl K</kbd></button>
      <div style="display:flex;align-items:center;gap:4px;margin-left:12px">
        <button id="win-minimize" title="Minimize" style="width:30px;height:26px;border-radius:6px;display:grid;place-items:center;color:var(--dim);background:none;border:none;cursor:pointer">
          <svg viewBox="0 0 12 12" width="11" height="11"><rect x="1" y="5.5" width="10" height="1.2" fill="currentColor"/></svg>
        </button>
        <button id="win-close" title="Close" style="width:30px;height:26px;border-radius:6px;display:grid;place-items:center;color:var(--dim);background:none;border:none;cursor:pointer">
          <svg viewBox="0 0 12 12" width="11" height="11" stroke="currentColor" stroke-width="1.3"><path d="M1.5 1.5l9 9M10.5 1.5l-9 9"/></svg>
        </button>
      </div>
    </div>

    <div class="screens" id="screens">

      <!-- ========== HOME ========== -->
      <section class="screen on page-flush" data-screen="home" id="screen-home">
        <div class="split">
          <div class="split-main">
            <div class="phead"><h1 id="queue-title">Nothing needs you</h1><span class="pmeta" id="fleet-summary">Loading&hellip;</span><span class="grow"></span><span class="pmeta" id="queue-keys">J / K move &middot; Enter acts</span></div>
            <ol class="queue" id="home-queue"></ol>
            <div class="newrow" id="home-build-cta" data-go="build" role="button" tabindex="0">
              <span class="newrow-plus" aria-hidden="true">+</span>
              <span><b>New package</b> <span class="dim">drop an installer, check what was read from it, build</span></span>
              <kbd>Ctrl O</kbd>
            </div>
            <div class="stats" id="home-stats">
              <div><b id="stat-total">0</b><span>apps tracked</span></div>
              <div><b id="stat-deployed">0</b><span>deployed</span></div>
              <div><b id="stat-updates">0</b><span>newer in winget</span></div>
              <div><b id="stat-pending">0</b><span>not deployed yet</span></div>
            </div>
          </div>

          <aside class="split-side">
            <div class="notice" id="release-banner" style="display:none">
              <span id="release-banner-text"></span>
              <button class="linkbtn" id="release-banner-github">View</button>
              <button class="linkbtn dim" id="release-banner-dismiss">Dismiss</button>
            </div>

            <div class="side-card" id="getting-started-card" style="display:none">
              <div class="side-h"><b>Getting started</b><span class="grow"></span>
                <button class="linkbtn" id="getting-started-tour">Tour</button><button class="linkbtn dim" id="getting-started-dismiss">Dismiss</button></div>
              <div id="getting-started-list"></div>
            </div>

            <!-- Building works fully standalone, so this is an invitation, not a gate. -->
            <div class="side-card" id="connect-card" style="display:none">
              <div class="side-h"><b>Live fleet view</b><span class="grow"></span><button class="linkbtn dim" id="connect-card-dismiss" title="Bring it back from Settings">Dismiss</button></div>
              <p class="side-p">Connect a Cloudflare worker and the devices you deploy to report back:</p>
              <ul class="wk-value">
                <li>See which version each device has, and which installs failed</li>
                <li>Self-updating apps check it for new versions</li>
                <li>A password-protected status page you can open from anywhere</li>
                <li>Vendor release checks for EPM report their results through it</li>
              </ul>
              <p class="side-p">Building works without it.</p>
              <div style="display:flex;gap:8px"><button class="btn primary sm" id="connect-btn">Connect</button><button class="btn sm" id="connect-preview-btn">See an example</button></div>
              <div id="connect-demo" style="display:none;margin-top:10px" class="demo-log">
                <div><span class="ok">&#9679;</span> VLC media player <span class="dim">3.0.20 &rarr; 3.0.21 on 41 devices</span></div>
                <div><span class="ok">&#9679;</span> 7-Zip <span class="dim">up to date</span></div>
                <div><span class="warn">&#9679;</span> Notepad++ <span class="dim">last seen 4 min ago</span></div>
              </div>
            </div>

            <div class="side-h"><b>Activity</b><span class="grow"></span><button class="linkbtn" data-go="history">History</button></div>
            <div class="actlog" id="home-recent-activity"></div>
          </aside>
        </div>
      </section>

      <!-- ========== BUILDER ========== -->
      <section class="screen" data-screen="build" id="screen-build">
        <div class="builder">
          <div class="sheet-col">
            <div class="choices" id="build-choices">
              <div class="choice"><span class="choice-q"><b>1</b> What are you packaging?</span>
                <div class="seg accent" id="segKind"><div class="thumb"></div><button class="on" data-val="app">An app</button><button data-val="printer">A printer</button></div>
                <span class="choice-hint" id="kindHint"></span></div>
              <div class="choice" id="choice-output"><span class="choice-q"><b>2</b> What do you need?</span>
                <div class="seg accent" id="segTarget"><div class="thumb"></div><button class="on" data-val="intunewin">Intune app</button><button data-val="epm">EPM rule</button><button data-val="psadt">PSADT app</button></div>
                <span class="choice-hint" id="targetHint"></span></div>
              <div class="choice" id="choice-delivery"><span class="choice-q"><b>3</b> How does it stay up to date?</span>
                <div class="seg accent" id="segMode"><div class="thumb"></div><button class="on" data-val="runtime">Updates itself</button><button data-val="simple">You push updates</button></div>
                <span class="choice-hint" id="modeHint"></span></div>
            </div>
            <div class="bsec" id="sec-source">
              <div class="bsec-h"><span class="bsec-n">01</span><span class="bsec-t">Source</span><span class="bsec-rule"></span></div>
              <div id="app-source-card">
                <div class="drop" id="drop">
                  <div class="drop-ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M17 8l-5-5-5 5M12 3v12"/></svg></div>
                  <b>Drop an installer here</b>
                  <span>or click to browse &middot; exe, msi, msix, appx, zip &middot; <kbd>Ctrl O</kbd></span>
                </div>
                <div id="inspect" style="display:none">
                  <div class="filecard">
                    <div class="filecard-ext" id="inspect-ext">EXE</div>
                    <div style="flex:1;min-width:0">
                      <div class="filecard-name" id="inspect-name">&nbsp;</div>
                      <div class="filecard-sub mono" id="inspect-sub">&nbsp;</div>
                    </div>
                    <button class="btn sm" id="reDrop">Change</button>
                  </div>
                  <div class="chips" id="inspect-chips"></div>
                </div>
              </div>
              <div id="printer-source-card" style="display:none">

                  <label class="lbl">Printer name</label>
                  <input class="field" id="f-printername" placeholder="Finance-3F-HP4200">
                  <label class="lbl" style="margin-top:10px">Driver</label>
                  <select class="field" id="f-driverid"><option value="">&mdash; none, use path below &mdash;</option></select>
                  <div style="margin-top:8px;display:none" id="driver-model-row">
                    <label class="lbl">Model</label>
                    <select class="field" id="f-drivermodel"></select>
                    <div class="hint">This driver package covers multiple printer models — pick the one being deployed.</div>
                  </div>
                  <label class="lbl" style="margin-top:10px">Driver name</label>
                  <input class="field" id="f-drivername" placeholder="HP Universal Printing PCL6 (auto-filled from library, or type it for a one-off path-based driver)">
                  <div style="display:flex;align-items:center;gap:6px;margin:10px 0 6px;flex-wrap:wrap">
                    <button type="button" class="btn ghost sm" id="driver-lib-add-toggle" style="padding-left:0">+ Add driver to library</button>
                    <button type="button" class="btn ghost sm" id="driver-lib-import-builtin">Import built-in driver families</button>
                  </div>
                  <div class="hint" id="builtin-import-status" style="margin-bottom:6px"></div>
                  <div id="driver-lib-add-panel" style="display:none;margin-bottom:10px;padding:10px;border:1px solid var(--edge);border-radius:var(--r-sm)">
                    <div class="row c2">
                      <div><label class="lbl">Driver ID</label><input class="field mono" id="dl-id" placeholder="hp-universal-pcl6-x64"></div>
                      <div><label class="lbl">Display name</label><input class="field" id="dl-displayname" placeholder="HP Universal Printing PCL6"></div>
                    </div>
                    <div class="row c2" style="margin-top:8px">
                      <div><label class="lbl">Manufacturer</label><input class="field" id="dl-manufacturer" placeholder="HP Inc."></div>
                      <div><label class="lbl">Driver type</label><input class="field" id="dl-drivertype" placeholder="PCL6"></div>
                    </div>
                    <div class="row c2" style="margin-top:8px">
                      <div><label class="lbl">Architecture</label><input class="field" id="dl-arch" placeholder="x64"></div>
                      <div><label class="lbl">Version</label><input class="field" id="dl-version" placeholder="61.270.0.0"></div>
                    </div>
                    <label class="lbl" style="margin-top:8px">Source (https:// URL, .zip, or folder path)</label>
                    <input class="field mono" id="dl-source" placeholder="https://... or C:\Drivers\hp-pcl6.zip">
                    <div class="row c2" style="margin-top:8px">
                      <div><label class="lbl">INF relative path</label><input class="field mono" id="dl-inf" placeholder="hpcu270u.inf"></div>
                      <div><label class="lbl">Expected publisher</label><input class="field" id="dl-publisher" placeholder="HP Inc."></div>
                    </div>
                    <label class="lbl" style="margin-top:8px">Models (one per line, optional)</label>
                    <textarea class="field mono" id="dl-models" rows="3" placeholder="Brother HL-2290&#10;Brother HL-L2350DW&#10;Brother HL-L2385DW" style="resize:vertical"></textarea>
                    <div class="hint">Leave blank for a single-model driver. Fill in when one INF/driver package covers a whole product family.</div>
                    <div style="display:flex;gap:8px;margin-top:10px">
                      <button class="btn primary sm" id="dl-save">Add to library</button>
                      <button class="btn ghost sm" id="dl-cancel">Cancel</button>
                    </div>
                    <div class="hint" id="dl-status" style="margin-top:6px"></div>
                  </div>
                  <div class="hint" id="driver-source-hint">Pick a driver from the library above, or fill in a local driver path/INF below for a one-off build not worth importing.</div>
                  <div class="row c2" style="margin-top:10px">
                    <div><label class="lbl">Driver source path</label><input class="field mono" id="f-driversourcepath" placeholder="C:\Drivers\hp-pcl6 or .zip"></div>
                    <div><label class="lbl">Driver INF (relative)</label><input class="field mono" id="f-driverinf" placeholder="hpcu270u.inf"></div>
                  </div>
                  <div><label class="lbl">Expected driver publisher</label><input class="field" id="f-driverpublisher" placeholder="HP Inc. (optional but recommended)"></div>
                  <div class="row c2" style="margin-top:10px">
                    <div><label class="lbl">Port host address</label><input class="field mono" id="f-porthost" placeholder="10.20.4.55"></div>
                    <div><label class="lbl">Port number</label><input class="field mono" id="f-portnumber" placeholder="9100"></div>
                  </div>
                  <div><label class="lbl">Location</label><input class="field" id="f-printerlocation" placeholder="3rd Floor - Finance"></div>
                  <div class="hint">Detection checks the printer actually exists with this driver and port, not just that it once ran.</div>
                
              </div>
            </div>

            <div class="bsec" id="sec-identity">
              <div class="bsec-h"><span class="bsec-n">02</span><span class="bsec-t">Identity</span><span class="bsec-rule"></span></div>
              <div class="brow"><label for="f-displayname">Display name</label><input class="field" id="f-displayname"><span class="bsrc" id="src-displayname"></span></div>
              <div class="brow"><label for="f-appid">App ID</label><input class="field mono" id="f-appid"><span class="bsrc" id="src-appid"></span></div>
              <div class="brow app-only"><label for="f-registryname">Registry name</label><input class="field mono" id="f-registryname" title="Must match Add/Remove Programs exactly; a local test suggests the right name"><span class="bsrc" id="src-registry"></span></div>
              <div class="brow app-only" id="silent-row"><label for="f-silentargs">Silent switch</label><input class="field mono" id="f-silentargs" placeholder="e.g. /S or /quiet /norestart" title="{pkg} stands for the installer's folder, e.g. /s /f1&quot;{pkg}\setup.iss&quot;"><span class="bsrc" id="src-silent"></span></div>
              <div class="brow" id="detectversion-wrap"><span class="blbl">Detection</span>
                <div class="detect"><button type="button" id="detect-any">Any version</button><span class="detect-ge">&ge;</span><input class="field mono" id="f-detectversion" placeholder="minimum version" aria-label="Minimum version for detection"></div>
                <span class="bsrc" id="src-detect"></span></div>
            </div>

            <div class="bsec" id="sec-configure">
              <div class="bsec-h"><span class="bsec-n">03</span><span class="bsec-t">Configure</span><span class="bsec-rule"></span>
              </div>
              <div class="brow app-only" id="runtime-url-row"><label for="f-download-url">Download URL</label><input class="field mono" id="f-download-url" type="url" placeholder="filled from winget when it knows this installer"><span class="bsrc" id="src-download">devices fetch updates</span></div>
              <div class="brow app-only" id="close-apps-row"><span class="blbl">Close before install</span>
                <div class="procs" id="close-apps-hint">Detected process to close on install</div>
                <button class="tgl on" data-val="closeAppsOn" aria-label="Close blocking apps"></button></div>
              <div class="brow app-only" id="defer-row"><span class="blbl">Let users postpone</span>
                <span class="bnote">Up to 3 times; turn off when another app depends on this one</span>
                <button class="tgl on" data-val="allowDefer" aria-label="Allow deferral"></button></div>
              <div class="brow app-only"><span class="blbl">Extras</span>
                <div class="extras-sum" id="extras-summary"></div>
                <button type="button" class="linkbtn" id="extras-toggle">Edit</button></div>
              <div class="extras" id="extras-panel" hidden>
                <div class="tglrow"><div><b>Bundle the whole folder</b><small id="bundle-hint">Copies everything in the installer's folder into the package, not just the installer. Turn on when setup needs files beside it, such as a config, a licence or an .mst. Off for You push updates only.</small></div><button class="tgl" data-val="BundleFolder"></button></div>
                <div id="scripts-wrap">
                  <div class="tglrow"><div><b>Remove older versions first</b><small>For apps that install side by side, such as Java. Needs a minimum version.</small></div><button class="tgl" data-val="RemoveOlderVersions"></button></div>
                  <div class="scripts">
                    <label for="f-prehook">Before install</label><input class="field mono" id="f-prehook" placeholder="script.ps1"><button class="btn sm" data-browse-script="f-prehook">Browse</button>
                    <label for="f-posthook">After install</label><input class="field mono" id="f-posthook" placeholder="script.ps1"><button class="btn sm" data-browse-script="f-posthook">Browse</button>
                    <label for="f-postuninstallhook">After uninstall</label><input class="field mono" id="f-postuninstallhook" placeholder="script.ps1"><button class="btn sm" data-browse-script="f-postuninstallhook">Browse</button>
                  </div>
                </div>
              </div>
            </div>

            <div class="bsec" id="sec-epm">
              <div class="bsec-h"><span class="bsec-n">03</span><span class="bsec-t">EPM rule</span><span class="bsec-rule"></span></div>
              <div class="brow"><span class="blbl">Rule</span><span class="bnote" id="epm-rule-desc">Publisher certificate and file name when the installer is signed, so it keeps matching after updates. Otherwise the file's SHA-256.</span></div>
              <div class="brow" id="epm-policy-row" hidden><span class="blbl">Policy</span><span class="bnote" id="epm-policy-desc"></span></div>
              <div class="brow" id="epm-watch-row" hidden><span class="blbl">New versions</span><span class="bnote">Watch the vendor and get the next version's hash without downloading it here.</span><button type="button" class="btn sm" id="epm-watch-btn">Watch&hellip;</button></div>
            </div>

            <div class="bsec" id="sec-wrap">
              <div class="bsec-h"><span class="bsec-n">04</span><span class="bsec-t">Wrap</span><span class="bsec-rule"></span></div>
              <div class="brow" id="psadt-row" hidden><span class="blbl">PSADT</span>
                <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
                  <div style="display:none" id="psadt-version-row">
                    <label class="lbl">PSADT version</label>
                    <div class="seg" id="segPsadtVersion">
                      <div class="thumb"></div>
                      <button class="on" data-val="v3">v3</button>
                      <button data-val="v4">v4</button>
                      <button data-val="both">Both</button>
                    </div>
                    <div class="hint">v4 uses the module-based PSAppDeployToolkit with Fluent dialogs; v3 is the classic frontend. "Both" exports each.</div>
                  </div>
                </div>
              </div>
              <div class="wrap-profile">
                <label class="lbl" style="margin-top:10px">Client profile</label>
                  <select class="field" id="f-profile"><option value="">Default (uses Settings organisation name)</option></select>
                  <div class="hint" id="profile-hint" style="margin-bottom:6px">Determines the branding used for this build - manage profiles from the nav rail.</div>
                  <div style="display:flex;align-items:center;gap:6px;margin-bottom:6px">
                    <button type="button" class="btn ghost sm" id="build-new-profile" style="padding-left:0">+ New profile</button>
                    <button type="button" class="btn ghost sm" id="build-override-toggle" style="display:none">Override for this build &#9662;</button>
                  </div>
                  <div id="build-override-panel" style="display:none;margin-bottom:10px;padding:10px;border:1px solid var(--edge);border-radius:var(--r-sm)">
                    <label class="lbl">Organisation name</label>
                    <input class="field" id="ov-orgname" style="margin-bottom:8px">
                    <label class="lbl">Logo image</label>
                    <div style="display:flex;gap:8px;margin-bottom:8px">
                      <input class="field mono" id="ov-logo" readonly style="flex:1;font-size:10.5px">
                      <button class="btn sm" id="ov-logo-browse">Browse&hellip;</button>
                    </div>
                    <label class="lbl">Banner image</label>
                    <div style="display:flex;gap:8px">
                      <input class="field mono" id="ov-banner" readonly style="flex:1;font-size:10.5px">
                      <button class="btn sm" id="ov-banner-browse">Browse&hellip;</button>
                    </div>
                    <div class="hint" style="margin-top:8px">Applies to this build only - you'll be asked whether to save it back to the profile afterward.</div>
                  </div>
              </div>
            </div>
          </div>

          <aside class="manifest-col" aria-label="Package manifest">
            <div class="mhead"><b>Manifest</b><span class="mono">what ships to Intune &middot; updates as you type</span></div>
            <div class="manifest mono" id="manifest"></div>
            <div class="mhead" style="margin-top:6px"><b>Checks</b><span class="mono" id="checks-state">pick an installer</span></div>
            <div id="checks-list"></div>
            <div style="display:none;align-items:center;gap:6px;margin-top:10px" id="bp-header">
                    <button type="button" id="bp-disclosure"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 6l6 6-6 6"/></svg><span class="lbl" style="margin:0" data-version-label>Preview branding</span></button>
                    <div class="seg" id="segBpSwap" style="display:none;transform:scale(.82);transform-origin:left center;margin-left:-6px">
                      <div class="thumb"></div>
                      <button class="on" data-val="v3">v3</button>
                      <button data-val="v4">v4</button>
                    </div>
                  </div>
            <div id="bp-panel" style="display:none;margin-top:8px;padding-top:12px;border-top:1px solid var(--edge)">
                    <div class="hint" style="margin-bottom:8px">This is what the real install dialog looks like - logo goes on Fluent (v4) dialogs, banner on Classic (v3) dialogs.</div>

                    <!-- v3 Classic: real proportions from the actual PSADT banner (900x125) - white
                         WinForms dialog, banner full-width at top, Segoe UI body text below. -->
                    <div id="bp-preview-v3" style="border-radius:6px;overflow:hidden;background:#F0F0F0;border:1px solid #ACACAC;box-shadow:0 6px 20px rgba(0,0,0,.35);font-family:'Segoe UI',var(--font-b)">
                      <div id="bp-v3-banner-wrap" style="width:100%;aspect-ratio:900/125;background:#fff;display:flex;align-items:center;justify-content:center;overflow:hidden;border-bottom:1px solid #ACACAC">
                        <img id="bp-v3-banner" style="width:100%;height:100%;object-fit:cover">
                      </div>
                      <div style="padding:12px 14px;background:#F0F0F0">
                        <div style="font-weight:600;font-size:12.5px;color:#1a1a1a" id="bp-v3-title">Welcome to the this app Setup</div>
                        <div style="font-size:10.5px;color:#444;margin-top:4px">Please close the following programs before continuing:</div>
                        <div style="background:#fff;border:1px solid #ACACAC;border-radius:2px;margin-top:6px;padding:5px 8px;font-size:10px;color:#333">Microsoft Word</div>
                        <div style="display:flex;gap:6px;margin-top:10px;justify-content:flex-end">
                          <div style="background:#E1E1E1;border:1px solid #ADADAD;border-radius:2px;padding:4px 12px;font-size:10.5px;color:#1a1a1a">Close &amp; Continue</div>
                        </div>
                      </div>
                    </div>

                    <!-- v4 Fluent: iNKORE.UI.WPF.Modern - rounded card, accent button (default
                         Windows accent #0078D7 unless FluentAccentColor is set), Title+SubTitle. -->
                    <div id="bp-preview-v4" style="display:none;border-radius:12px;overflow:hidden;background:#202020;border:1px solid #3a3a3a;box-shadow:0 6px 24px rgba(0,0,0,.4);font-family:var(--font-b)">
                      <div style="padding:20px 20px 16px;display:flex;gap:14px;align-items:flex-start">
                        <div id="bp-v4-icon-wrap" style="width:44px;height:44px;border-radius:10px;overflow:hidden;flex-shrink:0;background:#2d2d2d;display:grid;place-items:center">
                          <img id="bp-v4-icon" style="width:100%;height:100%;object-fit:cover">
                        </div>
                        <div style="min-width:0">
                          <div style="font-weight:600;font-size:14px;color:#fff" id="bp-v4-title">this app</div>
                          <div style="font-size:11px;color:#a0a0a0;margin-top:2px" id="bp-v4-subtitle">Please close the following applications to continue.</div>
                        </div>
                      </div>
                      <div style="padding:0 20px 18px">
                        <div style="background:#2d2d2d;border-radius:6px;padding:8px 12px;font-size:11px;color:#ddd">Microsoft Word</div>
                        <div style="display:flex;gap:8px;margin-top:14px;justify-content:flex-end">
                          <div id="bp-v4-accent-btn" style="background:#0078D7;border-radius:5px;padding:6px 16px;font-size:11.5px;color:#fff;font-weight:600">Close apps &amp; install</div>
                        </div>
                      </div>
                    </div>

                    <div class="hint" id="bp-no-assets-hint" style="display:none;margin-top:8px">Real PSADT assets aren't cached on this machine yet - build a PSADT package once and this preview will use the actual banner/icon.</div>
                  </div>
          </aside>
        </div>
      </section>

      <!-- ========== PROGRESS ========== -->
      <section class="screen page-flush" data-screen="progress" id="screen-progress">
        <div class="split">
          <div class="split-main">
            <div class="phead"><h2 id="progress-title">Package</h2><span class="pmeta">building</span></div>
            <div class="pbar"><i id="progress-bar"></i></div>
            <div id="progress-error" style="display:none" class="check red">
              <span class="g">&#10005;</span>
              <div><b id="progress-error-title">Build failed</b><div class="t" id="progress-error-msg"></div>
                <button class="btn sm" id="progress-error-back" style="margin-top:10px">Back to the builder</button></div>
            </div>
            <div class="log log-tall" id="log"></div>
          </div>
          <aside class="split-side"><div class="side-h"><b>Steps</b></div><div id="step-list"></div></aside>
        </div>
      </section>

      <!-- ========== DONE ========== -->
      <section class="screen page-flush" data-screen="done" id="screen-done">
        <div class="split">
          <div class="split-main">
            <div class="phead"><span class="okmark" aria-hidden="true">&#10003;</span><h2 id="done-title">Package ready</h2><span class="pmeta" id="done-path">&nbsp;</span>
              <button class="btn sm primary" id="done-open" style="margin-left:auto">Open folder</button></div>
            <div class="sheet" id="done-sheet"></div>
          </div>
          <aside class="split-side">
            <div class="side-h"><b>Next</b><span class="pmeta">each step unlocks the next</span></div>
            <ol class="steps">
              <li id="done-step-test"><span class="sn">1</span><div><b>Test it here</b><p>Runs the real package on this machine as Intune would, then checks detection.</p>
                <button class="btn primary sm" id="done-test">Test on this machine</button></div></li>
              <li id="done-step-intune"><span class="sn">2</span><div><b>Add it to Intune</b><p>Upload the package with the install, uninstall and detection values on the left. Each has a copy button.</p></div></li>
              <li id="done-step-deploy"><span class="sn">3</span><div><b>Mark it deployed</b><p>Once it is assigned. Home asks on a later launch whether it installed on devices.</p>
                <button class="btn sm" id="done-deployed">Mark deployed</button></div></li>
            </ol>
            <div style="display:flex;gap:8px;margin-top:6px"><button class="btn sm" data-go="build">New package</button><button class="btn ghost sm" data-go="fleet">App fleet</button></div>
          </aside>
        </div>
      </section>

      <!-- ========== FLEET ========== -->
      <section class="screen page-flush" data-screen="fleet" id="screen-fleet">
        <div class="page">
          <div class="phead"><h2>App fleet</h2><span class="pmeta" id="fleet-meta"></span>
            <span id="fleet-demo-badge" class="pill warn" style="display:none">example data</span>
            <span class="grow"></span>
            <input class="field" id="fleet-filter" placeholder="Filter by name or ID" aria-label="Filter apps" style="width:260px;height:30px">
            <button class="btn primary sm" data-go="build">New package</button>
          </div>
          <div class="fchips" id="fleet-chips" role="group" aria-label="Show"></div>
          <div id="fleet-bulk-bar" class="bulkbar" style="display:none">
            <span id="fleet-bulk-count"></span>
            <button class="btn sm primary" id="fleet-bulk-mark-deployed">Mark deployed</button>
            <button class="btn sm ghost" id="fleet-bulk-clear">Clear selection</button>
          </div>
          <div class="grid-wrap" id="fleet-grid"><table class="grid" id="fleet-table"></table></div>
          <div id="fleet-epm" hidden>
            <div id="epm-empty" hidden style="padding:8px 0">
              <p class="wz-lead">EPM rules let standard users run specific installers elevated, through Intune Endpoint Privilege Management.</p>
              <div style="display:flex;gap:8px;margin:0 0 8px"><button class="btn primary sm" id="epm-empty-setup">Set up&hellip;</button><button class="btn sm ghost" id="epm-empty-guide">How EPM rules work</button></div>
              <p class="bnote">You can build an EPM rule without any setup: pick an installer in the builder and choose EPM rule.</p>
            </div>
            <div id="epm-main">
            <div class="tglrow" style="margin:0 0 6px"><div><b id="intune-status-t">Intune not connected</b><small id="intune-status">Connect your Intune tenant to see which versions your EPM policies already allow, and to add new ones once adding rules is on in Settings &rsaquo; 09.</small></div>
              <div style="display:flex;gap:8px"><button class="btn sm" id="intune-refresh" hidden>Refresh</button><button class="btn sm" id="intune-signout" hidden>Sign out</button>
                <button class="btn sm primary" id="intune-signin">Connect Intune&hellip;</button><button class="btn sm" id="epm-screen-watch">Watch an app&hellip;</button><button class="btn sm" id="epm-fleet-setup">Set up&hellip;</button><button class="btn sm ghost" id="epm-guide">How EPM rules work</button></div></div>
            <div id="epm-cover"></div>
            <div class="bsec" id="epm-runs-sec" hidden><div class="bsec-h"><span class="bsec-t">Runs</span><span class="bsec-rule"></span><span class="pmeta" id="epm-runs-meta"></span></div>
              <div class="runs" id="epm-runs"></div></div>
            <div class="bsec" id="intune-pol-sec"><div class="bsec-h"><span class="bsec-t">EPM policies in Intune</span><span class="bsec-rule"></span></div>
              <div id="intune-policies"></div></div>
            </div>
          </div>
        </div>

        <!-- Local sanity check - runs the REAL detect/install/uninstall
             scripts (or PSADT's own test invocation) on this machine, no
             Intune needed. Separate from "Preview". -->
        <div id="test-modal" style="display:none;position:fixed;inset:0;background:rgba(5,5,10,.65);z-index:90;align-items:center;justify-content:center">
          <div class="dlg">
            <div class="dlg-h"><h2 id="test-modal-title">Test locally</h2><span class="pmeta">installs on this machine</span></div>
            <div class="dlg-b">
              <p class="bnote" style="margin:0 0 8px">Unpacks the real package and runs its install, detection and optional uninstall here, the way Intune would. No Intune needed.</p>
              <label class="dlg-opt"><input type="checkbox" id="test-simulate-system" checked> Run as SYSTEM, silently, like an Intune deployment</label>
              <label class="dlg-opt"><input type="checkbox" id="test-also-uninstall"> Test uninstall afterwards</label>
            </div>
            <div class="log" id="test-log"></div>
            <div class="dlg-f">
              <button class="btn" id="test-modal-close">Close</button>
              <button class="btn primary" id="test-modal-start">Start test</button>
            </div>
          </div>
        </div>
      </section>

      <!-- ========== WORKER & SETTINGS ========== -->
      <section class="screen page-flush" data-screen="worker" id="screen-worker">
        <div class="page">
          <div class="phead"><h2>Settings</h2><span class="pmeta">changes save as you make them</span><span id="settings-saved-flash" class="pmeta" style="color:var(--ok);opacity:0;transition:opacity .3s">Saved</span>
            <span class="grow"></span><span class="pmeta" id="settings-version">&nbsp;</span></div>
          <div class="cols2">
            <div>
              <div class="bsec" id="worker-connect-card">
                <div class="bsec-h"><span class="bsec-n">01</span><span class="bsec-t">Cloudflare worker</span><span class="bsec-rule"></span></div>
                <div class="srow2"><span class="k">Status</span><span id="worker-status">Loading&hellip;</span></div>
                <div id="worker-off">
                  <p class="bnote" style="margin:6px 0 2px">A Cloudflare worker (the free plan is enough) is how the devices you deploy to report back:</p>
                <ul class="wk-value">
                  <li>See which version each device has, and which installs failed</li>
                  <li>Self-updating apps check it for new versions</li>
                  <li>A password-protected status page you can open from anywhere</li>
                  <li>Vendor release checks for EPM report their results through it</li>
                </ul>
                  <p class="bnote" style="margin:0 0 8px">Building and testing packages works without it.</p>
                  <button class="btn primary sm" id="btn-worker-connect">Connect to Cloudflare&hellip;</button>
                </div>
                <div id="worker-on" hidden>
                  <div class="srow2"><span class="k"></span><button class="btn sm" id="btn-open-status">Open status page</button></div>
                  <div id="worker-acts"></div>
                </div>
              </div>
              <div class="bsec">
                <div class="bsec-h"><span class="bsec-n">02</span><span class="bsec-t">Online lookups</span><span class="bsec-rule"></span></div>
                <div class="tglrow"><div><b>Online lookups</b><small>New releases on GitHub, installer switches from Microsoft's winget catalogue and CISA's list of actively exploited vulnerabilities. Off = no outbound call is ever made. Recommended off for air-gapped machines.</small></div><button class="tgl on" id="tgl-release-check"></button></div>
                <div class="tglrow"><div><b>NIST vulnerability check</b><small>Before each build, asks NIST's National Vulnerability Database which CVEs affect the exact version being packaged. Sends the app's name and version to NIST. Warnings only; needs online lookups.</small></div><button class="tgl" id="tgl-nvd"></button></div>
              </div>
              <div class="bsec">
                <div class="bsec-h"><span class="bsec-n">03</span><span class="bsec-t">Defaults</span><span class="bsec-rule"></span></div>
                <div class="srow2"><label class="k" for="f-orgname-settings">Organisation</label>
                  <div><select class="field" id="f-orgname-settings" style="max-width:320px;height:30px"><option value="">Not set</option></select>
                    <div id="f-orgname-not-set-hint" style="display:none;margin-top:6px"><span class="bnote">Used when a build has no client profile. </span><button type="button" class="linkbtn" id="f-orgname-guide-btn">Set up a client profile</button></div></div></div>
              </div>
              <div class="bsec">
                <div class="bsec-h"><span class="bsec-n">04</span><span class="bsec-t">Display</span><span class="bsec-rule"></span></div>
                <div class="tglrow"><div><b>Reduce motion</b><small>Disables window/page animations and transitions app-wide. Off by default.</small></div><button class="tgl" id="tgl-reduce-motion"></button></div>
                <div class="tglrow"><div><b>High contrast</b><small>Stronger edges and text contrast throughout the app. Off by default.</small></div><button class="tgl" id="tgl-high-contrast"></button></div>
                <div class="tglrow"><div><b>Colour-blind safe palette</b><small>Swaps status colours (green/amber/red) for a palette distinguishable across all common colour vision types, plus icon shapes so status is never colour-only. Off by default.</small></div><button class="tgl" id="tgl-colorblind"></button></div>
              </div>
            </div>
            <div>
              <div class="bsec">
                <div class="bsec-h"><span class="bsec-n">05</span><span class="bsec-t">Home screen &amp; guide</span><span class="bsec-rule"></span></div>
                <div class="tglrow"><div><b>Show Cloudflare connection promo</b><small>The "Not connected to Cloudflare" card on Home and the fleet empty-state tip. Off if you dismissed it, or if you're offline-only by design.</small></div><button class="tgl on" id="tgl-cf-advert"></button></div>
                <div class="tglrow"><div><b>Show getting-started checklist</b><small>The "A few things to try" card on Home. Off if you dismissed it or it's not needed anymore.</small></div><button class="tgl on" id="tgl-getting-started"></button></div>
                <div class="tglrow"><div><b>Show Fleet and Settings in the sidebar</b><small>Brings them back if they were hidden during the tour.</small></div><button class="tgl on" id="tgl-cf-nav"></button></div>
                <div class="tglrow"><div><b>Guided tour</b><small>Walks through each screen and what it does.</small></div><button class="btn sm" id="settings-replay-tour">Replay</button></div>
                <div class="tglrow"><div><b>Reset for first launch</b><small>Clears the first-launch flags. Reopen AppUpdater to see the guide as a new install would.</small></div><button class="btn danger sm" id="docs-reset-onboarding">Reset</button></div>
              </div>
              <div class="bsec">
                <div class="bsec-h"><span class="bsec-n">06</span><span class="bsec-t">Folders &amp; log</span><span class="bsec-rule"></span></div>
                <div style="display:flex;gap:8px;flex-wrap:wrap;padding:6px 0">
                  <button class="btn sm" id="btn-open-output">Output</button>
                  <button class="btn sm" id="btn-open-cache">Toolkit cache</button>
                  <button class="btn sm" id="btn-open-log">Log</button>
                  <button class="btn sm ghost" id="btn-open-github" style="margin-left:auto">GitHub releases</button>
                </div>
                <div id="settings-release" class="bnote">&nbsp;</div>
              </div>
              <div class="bsec">
                <div class="bsec-h"><span class="bsec-n">07</span><span class="bsec-t">Recovery</span><span class="bsec-rule"></span></div>
                <p class="bnote" style="margin:4px 0 10px">A passphrase-protected backup of the config, token, client profiles and manifest. It restores only on this machine; a new machine reconnects to the worker instead.</p>
                <div style="display:flex;gap:8px"><button class="btn sm" id="btn-export-recovery">Export bundle&hellip;</button><button class="btn sm" id="btn-import-recovery">Import bundle&hellip;</button></div>
              </div>
              <div class="bsec" id="epm-section">
                <div class="bsec-h"><span class="bsec-n">08</span><span class="bsec-t">Vendor release checks</span><span class="bsec-rule"></span></div>
                <p class="bnote" style="margin:4px 0 6px">Watches each vendor for a new installer, then downloads it on a throwaway hosted machine (GitHub Actions or Azure Automation), checks who signed it and takes its SHA-256 for EPM rules. Nothing is downloaded to this PC; only the version, hash and signer come back.</p>
                <div class="tglrow"><div><b id="epm-status-t">Not set up</b><small id="epm-status">&nbsp;</small><small id="epm-cost" hidden></small></div><div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end"><button class="btn sm" id="epm-azure-pricing" hidden>Azure pricing</button><button class="btn sm danger" id="epm-azure-remove" hidden>Remove from Azure&hellip;</button><button class="btn sm primary" id="epm-setup">Set up…</button></div></div>
                <div id="epm-code-box" class="tglrow" hidden><div><b>Enter this code on GitHub</b><small>The sign-in page has opened in your browser. The sign-in is used once to set up the repo and is not kept.</small></div><span class="epm-code" id="epm-code"></span></div>
                <div id="epm-apps"></div>
                <details id="epm-add" style="padding:8px 0">
                  <summary class="linkbtn">Watch an app</summary>
                  <div style="padding-top:8px">
                    <p class="bnote" style="margin:0 0 8px">Tell the check where this app's new versions are published and who must have signed the installer. A download signed by anyone else is reported as blocked.</p>
                    <label class="lbl" for="epm-name">Name</label><input class="field" id="epm-name" placeholder="PowerToys">
                    <label class="lbl" for="epm-source">Where releases come from</label><input class="field mono" id="epm-source" placeholder="microsoft/PowerToys, or a download link that always points to the latest">
                    <label class="lbl" for="epm-publisher">Approved publisher (the installer's signer)</label><input class="field" id="epm-publisher" placeholder="Microsoft Corporation">
                    <label class="lbl" for="epm-winget">winget ID, to compare hashes</label><input class="field mono" id="epm-winget" placeholder="Microsoft.PowerToys">
                    <details style="margin-bottom:8px"><summary class="linkbtn">Version from a web page, or a specific release file</summary>
                      <div style="padding-top:8px">
                        <label class="lbl" for="epm-asset">Release file pattern (GitHub)</label><input class="field mono" id="epm-asset" placeholder="x64\.exe$">
                        <label class="lbl" for="epm-vregex">Version pattern, with the version in brackets</label><input class="field mono" id="epm-vregex" placeholder="Download 7-Zip (\d+\.\d+)">
                        <label class="lbl" for="epm-download">Download link, using {version} or {nodots}</label><input class="field mono" id="epm-download" placeholder="https://www.7-zip.org/a/7z{nodots}-x64.exe">
                      </div>
                    </details>
                    <button class="btn sm" id="epm-add-btn">Add</button> <span class="bnote" id="epm-add-msg"></span>
                  </div>
                </details>
              </div>
              <div class="bsec" id="intune-section">
                <div class="bsec-h"><span class="bsec-n">09</span><span class="bsec-t">Intune for EPM</span><span class="bsec-rule"></span></div>
                <p class="bnote" style="margin:4px 0 6px">Connect your own Intune tenant to see your Endpoint Privilege Management policies next to the versions the vendor checks find. Any Intune administrator can connect; nothing is installed in the tenant.</p>
                <div class="tglrow"><div><b id="intune-set-t">Not connected</b><small id="intune-set-s">Needs EPM licensed in the tenant and an Intune Administrator or Endpoint Security Manager account.</small></div>
                  <div style="display:flex;gap:8px"><button class="btn sm" id="intune-set-open" hidden>Open EPM</button><button class="btn sm" id="intune-set-out" hidden>Sign out</button><button class="btn sm primary" id="intune-set-connect">Connect Intune&hellip;</button></div></div>
                <div class="tglrow"><div><b>Let AppUpdater add rules to Intune</b><small>Adds each verified version to the app&rsquo;s EPM policy when you choose Add to Intune, and checks it by reading the policy back. Sign-in then also asks to change device configuration policies.</small></div><button class="tgl" id="tgl-intune-write" aria-label="Let AppUpdater add rules to Intune"></button></div>
              </div>
            </div>
          </div>
        </div>
      </section>

      <!-- ========== CLIENT PROFILES ========== -->
      <section class="screen page-flush" data-screen="profiles" id="screen-profiles">
        <div class="pf-layout">
          <nav class="pf-list" aria-label="Profiles">
            <div class="phead"><h2>Client profiles</h2></div>
            <p class="bnote" style="margin:0 0 10px">Branding and defaults applied to every build for a client.</p>
            <div id="profiles-strip"></div>
          </nav>
          <div id="profile-editor" style="display:contents">
          <div style="display:contents">
            <div class="pf-form">
              <div class="eyebrow" style="margin-bottom:10px" id="pf-editing-label">new profile</div>
              <label class="lbl">Name</label>
              <input class="field" id="pf-name" style="margin-bottom:10px">
              <label class="lbl">Organisation override</label>
              <input class="field" id="pf-orgname" style="margin-bottom:10px">
              <label class="lbl">Default output target</label>
              <div class="seg" id="pf-target-seg" style="margin-bottom:10px">
                <div class="thumb"></div>
                <button class="on" data-val="intunewin">.intunewin</button>
                <button data-val="psadt">PSADT</button>
              </div>
              <label class="lbl">Logo image</label>
              <div style="display:flex;gap:8px;margin-bottom:10px">
                <input class="field mono" id="pf-logo" readonly style="flex:1;font-size:10.5px">
                <button class="btn sm" id="pf-logo-browse">Browse&hellip;</button>
              </div>
              <label class="lbl">Banner image</label>
              <div style="display:flex;gap:8px;margin-bottom:14px">
                <input class="field mono" id="pf-banner" readonly style="flex:1;font-size:10.5px">
                <button class="btn sm" id="pf-banner-browse">Browse&hellip;</button>
              </div>
              <div style="display:flex;justify-content:flex-end;gap:10px;margin-top:14px">
                <button class="btn danger" id="pf-delete" style="display:none;margin-right:auto">Delete</button>
                <button class="btn" id="pf-cancel">Cancel</button>
                <button class="btn primary" id="pf-save">Save profile</button>
              </div>
            </div>

            <div class="pf-preview">
              <div class="phead" style="margin-bottom:4px"><h2>What users see</h2><span class="pmeta" id="pf-preview-context"></span></div>
              <div class="pf-ctx">
                <label for="pf-preview-app">App</label>
                <select class="field" id="pf-preview-app"><option value="">Example App</option></select>
                <label>Toolkit</label>
                <div class="seg seg-sm" id="segPfSwap">
                  <div class="thumb"></div>
                  <button class="on" data-val="v3">PSADT v3</button>
                  <button data-val="v4">PSADT v4</button>
                </div>
              </div>
              <p class="bnote" style="margin:0 0 12px">The dialog a PSADT package shows when it needs apps closed. Click the logo, banner or organisation to change them.</p>

              <div id="pf-preview-v3" style="border-radius:6px;overflow:hidden;background:#F0F0F0;border:1px solid #ACACAC;box-shadow:0 6px 20px rgba(0,0,0,.35);font-family:'Segoe UI',var(--font-b);max-width:380px">
                <div id="pf-v3-banner-wrap" class="pf-click-target" data-pf-click="pf-banner-browse" title="Click to set the banner image" style="width:100%;aspect-ratio:900/125;background:#fff;display:flex;align-items:center;justify-content:center;overflow:hidden;border-bottom:1px solid #ACACAC;cursor:pointer">
                  <img id="pf-v3-banner" style="width:100%;height:100%;object-fit:cover;display:none">
                  <span id="pf-v3-banner-placeholder" style="font-size:10px;color:#888">Click to set a banner (900&times;125 recommended)</span>
                </div>
                <div style="padding:12px 14px;background:#F0F0F0">
                  <div class="pf-click-target" title="The app being installed" style="font-weight:600;font-size:12.5px;color:#1a1a1a;cursor:pointer" id="pf-v3-title">Welcome to the Example App Setup</div>
                  <div style="font-size:10.5px;color:#444;margin-top:4px">Please close the following programs before continuing:</div>
                  <div style="background:#fff;border:1px solid #ACACAC;border-radius:2px;margin-top:6px;padding:5px 8px;font-size:10px;color:#333">Microsoft Word</div>
                  <div style="display:flex;gap:6px;margin-top:10px;justify-content:flex-end">
                    <div style="background:#E1E1E1;border:1px solid #ADADAD;border-radius:2px;padding:4px 12px;font-size:10.5px;color:#1a1a1a">Close &amp; Continue</div>
                  </div>
                </div>
              </div>

              <div id="pf-preview-v4" style="display:none;border-radius:12px;overflow:hidden;background:#202020;border:1px solid #3a3a3a;box-shadow:0 6px 24px rgba(0,0,0,.4);font-family:var(--font-b);max-width:380px">
                <div style="padding:20px 20px 16px;display:flex;gap:14px;align-items:flex-start">
                  <div id="pf-v4-icon-wrap" class="pf-click-target" data-pf-click="pf-logo-browse" title="Click to set the logo image" style="width:44px;height:44px;border-radius:10px;overflow:hidden;flex-shrink:0;background:#2d2d2d;display:grid;place-items:center;cursor:pointer">
                    <img id="pf-v4-icon" style="width:100%;height:100%;object-fit:cover;display:none">
                    <span id="pf-v4-icon-placeholder" style="font-size:8px;color:#999;text-align:center">logo</span>
                  </div>
                  <div style="min-width:0">
                    <div class="pf-click-target" title="The app being installed" style="font-weight:600;font-size:14px;color:#fff;cursor:pointer" id="pf-v4-title">Example App</div>
                    <div class="pf-click-target" data-pf-click="pf-orgname" title="Click to edit the organisation name" style="font-size:11px;color:#a0a0a0;margin-top:2px;cursor:pointer" id="pf-v4-subtitle">Acme Corp - please close the following applications to continue.</div>
                  </div>
                </div>
                <div style="padding:0 20px 18px">
                  <div style="background:#2d2d2d;border-radius:6px;padding:8px 12px;font-size:11px;color:#ddd">Microsoft Word</div>
                  <div style="display:flex;gap:8px;margin-top:14px;justify-content:flex-end">
                    <div style="background:#0078D7;border-radius:5px;padding:6px 16px;font-size:11.5px;color:#fff;font-weight:600">Close apps &amp; install</div>
                  </div>
                </div>
              </div>
              <p class="hint" style="margin-top:10px" id="pf-no-assets-hint">Real PSADT stock assets aren't cached on this machine yet - build a PSADT package once and this preview will use the actual banner/icon as fallback.</p>
            </div>
          </div>
          </div>
        </div>
      </section>

      <!-- ========== HISTORY ========== -->
      <section class="screen page-flush" data-screen="history" id="screen-history">
        <div class="page">
          <div class="phead"><h2>History</h2><span class="pmeta">every build, deploy mark and removal on this machine</span>
            <span id="history-demo-badge" class="pill warn" style="display:none">example data</span><span class="grow"></span>
            <input class="field" id="history-filter" placeholder="Filter by app" aria-label="Filter history" style="width:220px;height:30px"></div>
          <div class="fchips" id="history-chips" role="group" aria-label="Show"></div>
          <div class="grid-wrap"><table class="grid" id="history-table"></table></div>
          <div id="history-empty" class="empty" style="display:none">
            <b>No history yet</b>
            <p>Builds, deploy marks and removals on this machine are listed here, newest first.</p>
            <button class="btn primary sm" data-go="build">Build a package</button>
          </div>
        </div>
      </section>

      <!-- ========== DOCS & HELP ========== -->
      <section class="screen" data-screen="docs" id="screen-docs">
        <div style="max-width:760px;margin:0 auto;padding-bottom:36px">

          <div class="rise" style="margin:20px 0 18px">
            <div class="eyebrow">reference</div>
            <h1 style="font-family:var(--font-d);font-weight:700;font-size:24px;letter-spacing:-.01em;margin-top:4px">How AppUpdater works</h1>
            <p style="color:var(--dim);margin-top:4px;font-size:13.5px;max-width:520px">A quick walkthrough of every screen, plus where to find the source and file issues.</p>
          </div>

          <div class="card rise" style="margin-bottom:12px;display:flex;align-items:center;gap:14px;padding:14px 18px">
            <div style="width:38px;height:38px;border-radius:10px;background:var(--grad);display:grid;place-items:center;flex-shrink:0;box-shadow:0 0 20px rgba(var(--signal-rgb),.3)">
              <svg viewBox="0 0 24 24" width="18" height="18" fill="none" style="stroke:var(--on-accent)" stroke-width="1.8"><path d="M12 1a11 11 0 0 0-3.48 21.44c.55.1.75-.24.75-.53v-1.85c-3.06.67-3.7-1.47-3.7-1.47-.5-1.27-1.22-1.6-1.22-1.6-1-.68.08-.67.08-.67 1.1.08 1.68 1.13 1.68 1.13.98 1.68 2.57 1.2 3.2.92.1-.71.38-1.2.7-1.48-2.44-.28-5.02-1.22-5.02-5.42 0-1.2.43-2.18 1.12-2.94-.11-.28-.49-1.4.1-2.9 0 0 .93-.3 3.03 1.12a10.4 10.4 0 0 1 5.52 0c2.1-1.42 3.03-1.12 3.03-1.12.6 1.5.22 2.62.1 2.9.7.76 1.12 1.74 1.12 2.94 0 4.21-2.58 5.13-5.04 5.4.39.35.75 1.02.75 2.06v3.05c0 .3.2.64.76.53A11 11 0 0 0 12 1z"/></svg>
            </div>
            <div style="flex:1">
              <div style="font-family:var(--font-d);font-weight:600;font-size:14.5px">Source &amp; issues</div>
              <div style="font-size:12px;color:var(--dim);margin-top:2px">github.com/Lyvvy-xyz/Appupdater</div>
            </div>
            <button class="btn" id="docs-github-link">Open GitHub</button>
          </div>

          <div class="card rise" style="margin-bottom:12px;padding:14px 18px">
            <div style="display:flex;align-items:center;gap:14px;margin-bottom:12px">
              <div style="width:38px;height:38px;border-radius:10px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--signal)">
                <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 0c0 1.5-2.5 1.8-2.5 3.5"/><circle cx="12" cy="17" r=".6" fill="currentColor" stroke="none"/></svg>
              </div>
              <div style="flex:1">
                <div style="font-family:var(--font-d);font-weight:600;font-size:14.5px">Guided walkthrough</div>
                <div style="font-size:12px;color:var(--dim);margin-top:2px">Replay the tour that highlights each screen and explains what it does.</div>
              </div>
              <button class="btn primary" id="docs-replay-tour">Replay tour</button>
            </div>
          </div>

          <div class="rise" style="margin:20px 0 12px"><div class="eyebrow">screen by screen</div></div>

          <div class="card rise" style="margin-bottom:14px"><div class="card-b" style="display:flex;gap:16px">
            <div style="width:34px;height:34px;border-radius:9px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--signal)">
              <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 12l9-8 9 8M5 10v10h5v-6h4v6h5V10"/></svg>
            </div>
            <div>
              <div class="card-t" style="margin-top:2px">Home</div>
              <p style="margin-top:6px;font-size:13px;color:var(--dim);line-height:1.6">Your fleet at a glance, and whether the Cloudflare worker is connected. "Build app package" starts a new package; the table below shows the last few tracked apps.</p>
            </div>
          </div></div>

          <div class="card rise" style="margin-bottom:14px"><div class="card-b" style="display:flex;gap:16px">
            <div style="width:34px;height:34px;border-radius:9px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--signal)">
              <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/></svg>
            </div>
            <div style="flex:1">
              <div class="card-t" style="margin-top:2px">Build</div>
              <div style="display:grid;gap:8px;margin-top:10px">
                <div style="display:flex;gap:10px;align-items:baseline"><span class="mono" style="color:var(--faint);font-size:11px;flex-shrink:0">01</span><span style="font-size:13px;color:var(--dim)">Drop or browse to an installer (.exe/.msi) - version, publisher and silent args are detected automatically.</span></div>
                <div style="display:flex;gap:10px;align-items:baseline"><span class="mono" style="color:var(--faint);font-size:11px;flex-shrink:0">02</span><span style="font-size:13px;color:var(--dim)">Confirm identity fields - registry name must match Add/Remove Programs exactly for detection to work.</span></div>
                <div style="display:flex;gap:10px;align-items:baseline"><span class="mono" style="color:var(--faint);font-size:11px;flex-shrink:0">03</span><span style="font-size:13px;color:var(--dim)">Choose Runtime (auto-updates itself) or Simple, and an output target - .intunewin, or PSADT v3/v4/both.</span></div>
                <div style="display:flex;gap:10px;align-items:baseline"><span class="mono" style="color:var(--faint);font-size:11px;flex-shrink:0">04</span><span style="font-size:13px;color:var(--dim)">Review behaviour toggles, then Build.</span></div>
              </div>
            </div>
          </div></div>

          <div class="card rise" style="margin-bottom:14px"><div class="card-b" style="display:flex;gap:16px">
            <div style="width:34px;height:34px;border-radius:9px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--signal)">
              <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="4" width="18" height="12" rx="2"/><path d="M8 20h8M12 16v4"/></svg>
            </div>
            <div>
              <div class="card-t" style="margin-top:2px">App fleet</div>
              <p style="margin-top:6px;font-size:13px;color:var(--dim);line-height:1.6">Every app tracked in your local manifest. "Rebuild" re-opens the builder pre-filled for that app; "Mark deployed" records that you've pushed it live (tracked locally by the shell, separate from the manifest itself).</p>
            </div>
          </div></div>

          <div class="card rise" style="margin-bottom:14px"><div class="card-b" style="display:flex;gap:16px">
            <div style="width:34px;height:34px;border-radius:9px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--signal)">
              <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="4" width="7" height="7" rx="1.5"/><rect x="14" y="4" width="7" height="7" rx="1.5"/><rect x="3" y="15" width="7" height="7" rx="1.5"/><rect x="14" y="15" width="7" height="7" rx="1.5"/></svg>
            </div>
            <div>
              <div class="card-t" style="margin-top:2px">Client profiles</div>
              <p style="margin-top:6px;font-size:13px;color:var(--dim);line-height:1.6">A profile bundles a client's organisation name, logo/banner, and default output target so every build for that client is branded consistently. Pick one on the Build screen before building.</p>
            </div>
          </div></div>

          <div class="card rise"><div class="card-b" style="display:flex;gap:16px">
            <div style="width:34px;height:34px;border-radius:9px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--signal)">
              <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82"/></svg>
            </div>
            <div>
              <div class="card-t" style="margin-top:2px">Worker &amp; settings</div>
              <p style="margin-top:6px;font-size:13px;color:var(--dim);line-height:1.6">Connect to Cloudflare for auto-updates and a live status dashboard, or stay fully offline - packaging always works standalone. Recovery bundles back up your config/profiles/manifest with a passphrase; they restore only on the machine that made them.</p>
            </div>
          </div></div>

        </div>
      </section>

    </div>
    <div class="buildbar" id="buildbar" style="display:none">
      <div class="summary" id="build-summary">Select an installer to begin.</div>
      <button class="btn ghost" data-go="home">Cancel</button>
      <button class="btn primary big" id="btn-build" disabled><span id="btn-build-t">Build package</span><kbd>Ctrl &#8629;</kbd></button>
    </div>
    <div class="statusbar" id="statusbar"><span id="sb-winget"></span><span id="sb-cisa"></span><span id="sb-nvd"></span><span class="grow"></span><span id="sb-mode"></span><span id="sb-version"></span></div>
  </div>
</div>
<div class="toasts" id="toasts"></div>
<div class="chip-pop" id="chip-pop" hidden role="dialog" aria-live="polite"><div id="chip-pop-text"></div><button type="button" class="btn sm" id="chip-pop-link" hidden>Open</button></div>

<!-- In-app dialogs sit outside the screens, which are transparent and click-through when inactive. -->
        <div id="ui-dlg" class="modal" hidden>
          <div class="dlg" style="width:min(520px,92vw)" role="dialog" aria-modal="true" aria-labelledby="ui-dlg-title">
            <div class="dlg-h"><h2 id="ui-dlg-title"></h2><span class="pmeta" id="ui-dlg-sub"></span></div>
            <div class="dlg-b" id="ui-dlg-body"></div>
            <div class="log" id="ui-dlg-log" hidden></div>
            <p class="ui-err" id="ui-dlg-err" role="alert" hidden></p>
            <div class="dlg-f" id="ui-dlg-foot"></div>
          </div>
        </div>
        <div id="epm-wiz" style="display:none;position:fixed;inset:0;background:rgba(5,5,10,.65);z-index:90;align-items:center;justify-content:center">
          <div class="dlg" style="width:min(560px,92vw)" role="dialog" aria-labelledby="epm-wiz-title">
            <div class="dlg-h"><h2 id="epm-wiz-title">Set up vendor release checks</h2><span class="pmeta" id="epm-wiz-count"></span></div>
            <ol class="wiz-steps" id="epm-wiz-steps"><li>Where</li><li>Sign in</li><li>Set up</li><li>First check</li></ol>
            <div class="dlg-b">
              <div data-wiz="0">
                <p class="bnote">A small job checks each vendor every 6 hours. When there is a new installer it downloads it on a throwaway machine, checks who signed it and takes its SHA-256. Only those come back to AppUpdater.</p>
                <label class="dlg-opt wiz-pick"><input type="radio" name="epm-wiz-runner" value="github" checked><span><b>GitHub Actions</b><small>A private repo in your GitHub account. Free within GitHub's monthly Actions minutes.</small></span></label>
                <label class="dlg-opt wiz-pick" style="opacity:.55"><input type="radio" name="epm-wiz-runner" value="azure" disabled><span><b>Azure Automation</b><small>Runs in your Azure subscription. Coming later.</small></span></label>
                <p class="bnote wiz-warn" id="epm-wiz-noworker" hidden>Results come back through your Cloudflare worker, which is not connected yet. Connect it in Settings section 01 first.</p>
              </div>
              <div data-wiz="1" hidden>
                <p class="bnote">Signing in lets AppUpdater do three things, once:</p>
                <ul class="wiz-list"><li>Create a private repo, <span class="mono">appupdater-checks</span></li><li>Add the check script and its schedule</li><li>Start the first run</li></ul>
                <p class="bnote">The sign-in is not kept. To change anything later, sign in again.</p>
                <div id="epm-wiz-code-box" hidden>
                  <p class="bnote" style="margin-top:10px">GitHub's sign-in page has opened. Enter this code there and approve:</p>
                  <div style="display:flex;align-items:center;gap:10px;margin:6px 0"><span class="epm-code" id="epm-wiz-code"></span>
                    <button class="btn sm" id="epm-wiz-copy">Copy</button><button class="btn sm" id="epm-wiz-reopen">Open GitHub again</button></div>
                </div>
                <p class="bnote" id="epm-wiz-msg"></p>
              </div>
              <div data-wiz="2" hidden>
                <ul class="wiz-list wiz-progress"><li class="done">Signed in to GitHub</li><li class="now">Creating the repo, adding the check, starting the first run</li></ul>
                <p class="bnote" id="epm-wiz-msg2"></p>
              </div>
              <div data-wiz="3" hidden>
                <p class="bnote" id="epm-wiz-repo"></p>
                <ul class="wiz-list wiz-progress"><li class="done">Repo created and trusted by your worker</li><li id="epm-wiz-run" class="now">First run in progress, usually a few minutes</li></ul>
                <p class="bnote">Next, tell it which apps to watch. Each one needs where its releases come from and the publisher that must have signed it.</p>
              </div>
            </div>
            <div class="dlg-f">
              <button class="btn" id="epm-wiz-close">Close</button>
              <button class="btn" id="epm-wiz-back">Back</button>
              <button class="btn primary" id="epm-wiz-next">Next</button>
            </div>
          </div>
        </div>
<div id="tour-overlay">
  <div id="tour-spot"></div>
  <div id="tour-card">
    <div class="eyebrow" id="tour-step-count"></div>
    <div style="font-family:var(--font-d);font-weight:600;font-size:15px;margin:6px 0 8px" id="tour-title"></div>
    <p style="font-size:12.5px;color:var(--dim);margin-bottom:14px;line-height:1.5" id="tour-text"></p>
    <div id="tour-cf-choice" style="display:none;margin-bottom:14px">
      <div style="display:flex;gap:8px;margin-bottom:10px">
        <button class="btn primary sm" id="tour-cf-yes" style="flex:1">Set up now</button>
        <button class="btn sm" id="tour-cf-no" style="flex:1">Not now</button>
      </div>
      <label style="display:flex;align-items:center;gap:8px;font-size:11.5px;color:var(--dim);cursor:pointer">
        <input type="checkbox" id="tour-cf-keep-visible"> Keep these pages visible anyway
      </label>
    </div>
    <div style="display:flex;align-items:center;gap:8px" id="tour-nav-buttons">
      <button class="btn ghost sm" id="tour-skip">Skip tour</button>
      <div style="flex:1"></div>
      <button class="btn sm" id="tour-back">Back</button>
      <button class="btn primary sm" id="tour-next">Next</button>
    </div>
  </div>
</div>

<script>
  const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);
  const bridge = window.chrome && window.chrome.webview;
  function escapeHtml(value) {
    return String(value == null ? '' : value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }
  // Answers to get-settings arrive in request order; one asked for before the last save is older than what is on screen.
  let settingsAsked = 0, settingsAnswered = 0, settingsSavedAfter = 0;
  function send(action, payload) {
    if (action === 'get-settings') settingsAsked++;
    if (action === 'save-settings') settingsSavedAfter = settingsAsked;
    if (bridge) bridge.postMessage({ action, payload });
    else console.warn('WebView2 bridge unavailable — running outside host?', action, payload);
  }
  window.addEventListener('error', e => {
    try { send('client-error', { message: e.message, stack: (e.error && e.error.stack) || '', source: e.filename + ':' + e.lineno }); } catch (_) {}
  });
  window.addEventListener('unhandledrejection', e => {
    try { send('client-error', { message: 'Unhandled promise rejection: ' + (e.reason && e.reason.message || e.reason), stack: (e.reason && e.reason.stack) || '' }); } catch (_) {}
  });

  function toast(title, msg, isErr) {
    const t = document.createElement('div');
    t.className = 'toast' + (isErr ? ' err' : '');
    t.innerHTML = `<b><i></i>${escapeHtml(title)}</b><p>${escapeHtml(msg)}</p><span class="life"></span>`;
    $('#toasts').appendChild(t);
    setTimeout(() => { t.classList.add('out'); setTimeout(() => t.remove(), 320); }, 4000);
  }

  // One in-app dialog for questions, choices and secrets. uiDialog resolves with the entered values, or null when
  // cancelled; uiProgress turns the same dialog into a live log for a long action.
  let uiDlgResolve = null, uiDlgFields = [];
  const uiDlg = () => $('#ui-dlg');
  function uiFieldHtml(f) {
    const id = 'ui-f-' + f.id;
    if (f.type === 'checks') return `<fieldset class="ui-choice" data-field="${f.id}">${f.label ? `<legend class="lbl">${escapeHtml(f.label)}</legend>` : ''}`
      + f.options.map(o => `<label class="ui-opt"><input type="checkbox" name="${id}" value="${escapeHtml(o.value)}"${o.checked ? ' checked' : ''}><span><b>${escapeHtml(o.label)}</b></span></label>`).join('') + '</fieldset>';
    if (f.type === 'choice') return `<fieldset class="ui-choice" data-field="${f.id}">${f.label ? `<legend class="lbl">${escapeHtml(f.label)}</legend>` : ''}`
      + f.options.map((o, n) => `<label class="ui-opt${o.danger ? ' danger' : ''}"><input type="radio" name="${id}" value="${escapeHtml(o.value)}"${(f.value ? f.value === o.value : n === 0) ? ' checked' : ''}>`
        + `<span><b>${escapeHtml(o.label)}</b>${o.desc ? `<small>${escapeHtml(o.desc)}</small>` : ''}</span></label>`).join('') + '</fieldset>';
    return `<div class="ui-field" data-field="${f.id}"><label class="lbl" for="${id}">${escapeHtml(f.label)}</label>`
      + `<input class="field${f.mono ? ' mono' : ''}" id="${id}" type="${f.type === 'password' ? 'password' : 'text'}" autocomplete="off" spellcheck="false" placeholder="${escapeHtml(f.placeholder || '')}" value="${escapeHtml(f.value || '')}">`
      + (f.hint ? `<small>${escapeHtml(f.hint)}</small>` : '') + '</div>';
  }
  function uiValues() {
    const v = {};
    uiDlgFields.forEach(f => {
      if (f.type === 'checks') v[f.id] = [...uiDlg().querySelectorAll(`input[name="ui-f-${f.id}"]:checked`)].map(c => c.value);
      else if (f.type === 'choice') { const c = uiDlg().querySelector(`input[name="ui-f-${f.id}"]:checked`); v[f.id] = c ? c.value : ''; }
      else v[f.id] = $('#ui-f-' + f.id).value;
    });
    return v;
  }
  function uiRefresh() {
    const v = uiValues();
    uiDlgFields.forEach(f => { uiDlg().querySelector(`[data-field="${f.id}"]`).hidden = !!(f.showIf && !f.showIf(v)); });
  }
  function uiClose(result) {
    uiDlg().hidden = true;
    $('#ui-dlg-body').innerHTML = ''; $('#ui-dlg-log').innerHTML = '';
    const r = uiDlgResolve; uiDlgResolve = null;
    if (r) r(result);
  }
  // Walkthrough content: a step bar, one lead sentence, then rows of [icon, title, detail, tone, action].
  // Strings are escaped; only the icon glyph and row layout come from here.
  function uiWalkHtml({ step, lead, rows = [], note }) {
    return (step ? `<div class="wz-dots" aria-label="Step ${step[0]} of ${step[1]}">${Array.from({ length: step[1] }, (_, i) => `<i class="${i < step[0] ? 'on' : ''}"></i>`).join('')}</div>` : '')
      + (lead ? `<p class="wz-lead">${escapeHtml(lead)}</p>` : '')
      + (rows.length ? '<div class="wz-rows">' + rows.map(([ic, t, d, tone, act]) => `<div class="wz-row ${tone || ''}"><span class="wz-ic" aria-hidden="true">${escapeHtml(ic)}</span>`
        + `<div><b>${escapeHtml(t)}</b>${d ? `<small>${escapeHtml(d)}</small>` : ''}</div>`
        + (act ? `<button class="btn sm" data-wz-act="${escapeHtml(act[0])}">${escapeHtml(act[1])}</button>` : '<span></span>') + '</div>').join('') + '</div>' : '')
      + (note ? `<p class="wz-note">${escapeHtml(note)}</p>` : '');
  }
  function uiDialog({ title, sub = '', text = '', fields = [], ok = 'OK', danger = false, cancel = 'Cancel', validate, extra, walk, back, wide, after }) {
    if (uiDlgResolve) uiClose(null);
    uiDlg().classList.toggle('wide', !!wide);
    uiDlgFields = fields;
    $('#ui-dlg-title').textContent = title;
    $('#ui-dlg-sub').textContent = sub;
    $('#ui-dlg-body').innerHTML = (walk ? uiWalkHtml(walk) : '') + (text ? `<p class="bnote ui-text">${escapeHtml(text)}</p>` : '') + fields.map(uiFieldHtml).join('');
    if (after) { const box = document.createElement('div'); $('#ui-dlg-body').appendChild(box); after(box); }
    $('#ui-dlg-log').hidden = true;
    $('#ui-dlg-err').hidden = true;
    uiDlg()._extra = extra ? extra[1] : null;
    $('#ui-dlg-foot').innerHTML = (extra ? `<button class="btn" data-ui="extra" style="margin-right:auto">${escapeHtml(extra[0])}</button>` : '')
      + (back ? `<button class="btn" data-ui="back">${escapeHtml(back)}</button>` : '')
      + (cancel ? `<button class="btn" data-ui="cancel">${escapeHtml(cancel)}</button>` : '')
      + `<button class="btn ${danger ? 'danger-solid' : 'primary'}" data-ui="ok">${escapeHtml(ok)}</button>`;
    uiRefresh();
    uiDlg().hidden = false;
    const first = uiDlg().querySelector('.ui-field:not([hidden]) input, .ui-choice input:checked');
    (first || uiDlg().querySelector('[data-ui="ok"]')).focus();
    return new Promise(resolve => {
      uiDlgResolve = resolve;
      uiDlg()._submit = () => {
        const v = uiValues();
        // Values of hidden fields are not part of the answer.
        uiDlgFields.forEach(f => { if (f.showIf && !f.showIf(v)) delete v[f.id]; });
        const err = validate ? validate(v) : '';
        if (err) { $('#ui-dlg-err').textContent = err; $('#ui-dlg-err').hidden = false; return; }
        uiClose(v);
      };
    });
  }
  const uiConfirm = (title, text, ok = 'OK', danger = false) => uiDialog({ title, text, ok, danger }).then(v => v !== null);
  // Resolves when the user closes the finished log.
  function uiProgress(title, sub = '') {
    if (uiDlgResolve) uiClose(null);
    uiDlg().classList.remove('wide');
    uiDlgFields = [];
    $('#ui-dlg-title').textContent = title;
    $('#ui-dlg-sub').textContent = sub || 'working…';
    $('#ui-dlg-body').innerHTML = '';
    $('#ui-dlg-log').innerHTML = ''; $('#ui-dlg-log').hidden = false;
    $('#ui-dlg-err').hidden = true;
    $('#ui-dlg-foot').innerHTML = '<button class="btn" data-ui="close" disabled>Close</button>';
    uiDlg()._submit = null;
    uiDlg().hidden = false;
    return new Promise(resolve => { uiDlgResolve = resolve; });
  }
  function uiProgressLine(tone, text) {
    const log = $('#ui-dlg-log'), line = document.createElement('div');
    line.className = tone || 'info';
    line.textContent = (tone === 'ok' ? '✓ ' : tone === 'warn' ? '! ' : tone === 'bad' ? '✕ ' : tone === 'step' ? '› ' : '  ') + text;
    log.appendChild(line); log.scrollTop = log.scrollHeight;
  }
  function uiProgressDone(ok, text) {
    if (text) uiProgressLine(ok ? 'ok' : 'bad', text);
    $('#ui-dlg-sub').textContent = ok ? 'done' : 'failed';
    const close = $('#ui-dlg-foot [data-ui="close"]');
    if (close) { close.disabled = false; close.className = 'btn ' + (ok ? 'primary' : ''); close.focus(); }
  }
  $('#ui-dlg').addEventListener('click', e => {
    const b = e.target.closest('[data-ui]');
    if (!b) return;
    if (b.dataset.ui === 'back') uiClose({ __back: true });
    else if (b.dataset.ui === 'extra' && uiDlg()._extra) uiDlg()._extra();
    else if (b.dataset.ui === 'ok' && uiDlg()._submit) uiDlg()._submit();
    else if (b.dataset.ui === 'cancel' || b.dataset.ui === 'close') uiClose(null);
  });
  $('#ui-dlg').addEventListener('click', e => { const a = e.target.closest('[data-wz-act]'); if (a) uiClose({ __act: a.dataset.wzAct }); });
  $('#ui-dlg').addEventListener('input', uiRefresh);
  $('#ui-dlg').addEventListener('change', uiRefresh);
  $('#ui-dlg').addEventListener('keydown', e => {
    if (e.key === 'Escape') {
      e.stopPropagation();
      const close = $('#ui-dlg-foot [data-ui="close"]');
      if (!close || !close.disabled) uiClose(null);
    } else if (e.key === 'Enter' && uiDlg()._submit && e.target.tagName === 'INPUT') { e.preventDefault(); uiDlg()._submit(); }
  });

  // The choices at the top decide which parts of the form apply: printers and EPM rules never self-update,
  // and MSIX and zip packages only build as Intune apps.
  function applyContext() {
    const sb = $('#screen-build'), printer = form.Kind === 'printer';
    const packaged = !printer && (window._installerType === 'MSIX' || /\.zip$/i.test(window._selectedInstaller || ''));
    const btn = (seg, v) => $(`#${seg} button[data-val="${v}"]`);
    ['epm', 'psadt'].forEach(v => { btn('segTarget', v).disabled = printer || packaged; });
    btn('segMode', 'runtime').disabled = packaged;
    if ((printer || packaged) && form.SimplePkgTarget !== 'intunewin') btn('segTarget', 'intunewin').click();
    if (packaged && form.Mode !== 'simple') btn('segMode', 'simple').click();
    const epm = form.SimplePkgTarget === 'epm';
    sb.classList.toggle('epm', epm);
    // EPM can also be the choice already in place, for example when the builder reopens with it selected.
    if (epm && sb.classList.contains('on')) adviseEpmOnce();
    $('#btn-build-t').textContent = epm ? 'Create EPM rule' : 'Build package';
    sb.classList.toggle('simple', form.Mode === 'simple');
    $('#psadt-row').hidden = form.SimplePkgTarget !== 'psadt';
    $('#kindHint').textContent = printer ? 'Installs a printer and its driver. No installer file needed.' : 'An installer: exe, msi, msix/appx or a portable-app zip.';
    $('#targetHint').textContent = printer ? 'Printers are packaged as Intune apps.'
      : packaged ? 'MSIX and zip packages are uploaded as Intune apps.'
      : epm ? 'Lets standard users run this installer elevated. No package is built.'
      : form.SimplePkgTarget === 'psadt' ? 'An Intune app wrapped in PSAppDeployToolkit, with branded prompts users see.'
      : 'A .intunewin file to upload as a Win32 app in Intune.';
    $('#modeHint').textContent = packaged ? 'Intune replaces this package when you upload a new one.'
      : form.Mode === 'runtime' ? 'Devices check for new versions and install them on their own.'
      : 'You build and upload each new version.';
    const name = $('#f-displayname').value.trim() || 'App';
    updateEpmRows();
  }

  function segInit(seg, onChange) {
    const th = seg.querySelector('.thumb'), btns = [...seg.querySelectorAll('button')];
    function place(b) { th.style.left = b.offsetLeft + 'px'; th.style.width = b.offsetWidth + 'px'; }
    btns.forEach(b => b.addEventListener('click', () => {
      btns.forEach(x => x.classList.remove('on')); b.classList.add('on'); place(b);
      onChange && onChange(b.dataset.val);
    }));
    requestAnimationFrame(() => place(seg.querySelector('button.on') || btns[0]));
    new ResizeObserver(() => place(seg.querySelector('button.on') || btns[0])).observe(seg);
  }

  function pipeNames() {
    // The progress bar names the file each step produces.
    const id = ($('#f-appid') && $('#f-appid').value.trim()) || 'App';
    const source = form.Kind === 'printer' ? 'printer' : (window._selectedInstaller ? window._selectedInstaller.split(/[\\/]/).pop() : 'installer');
    const psadt = form.SimplePkgTarget === 'psadt';
    if (form.Kind !== 'printer' && form.SimplePkgTarget === 'epm') return [source, 'SHA-256', 'Signer', 'EPM-rules.csv', 'Intune EPM'];
    const detect = form.Kind === 'printer' ? 'Detect-Printer.ps1' : form.Mode === 'runtime' ? `Detect-${id}.ps1` : 'detect.ps1';
    const install = form.Kind === 'printer' ? 'Install-Printer.ps1' : psadt ? 'Deploy-Application.ps1' : form.Mode === 'runtime' ? `Deploy-${id}.ps1` : 'install.ps1';
    return [source, detect, install, psadt ? `${id}-PSADT` : `${id}.intunewin`, 'Intune'];
  }
  function renderPipe(activeIdx, doneUpTo, flowIdx) {
    const pipe = $('#pipe');
    if (activeIdx == null) { pipe.style.display = 'none'; return; }
    pipe.style.display = 'flex';
    const pipeLabels = pipeNames();
    pipe.innerHTML = pipeLabels.map((label, i) => {
      const st = i < doneUpTo ? 'done' : i === activeIdx ? 'live' : '';
      const flow = flowIdx === i ? ' flow' : '';
      const line = i < pipeLabels.length - 1 ? `<div class="pline${flow}"><i></i></div>` : '';
