          break;
        case 'status-data': {
          const age = h => h == null ? null : h < 1 ? 'under 1 h old' : h < 48 ? `${Math.round(h)} h old` : `${Math.round(h / 24)} days old`;
          $('#sb-winget').innerHTML = payload.lookups ? (payload.wingetAge == null ? '<span class="dot off">\u25CF</span> winget index not downloaded yet' : `<span class="dot">\u25CF</span> winget index ${age(payload.wingetAge)}`) : '<span class="dot off">\u25CF</span> online lookups off';
          $('#sb-cisa').textContent = payload.lookups && payload.kevAge != null ? `CISA list ${age(payload.kevAge)}` : '';
          $('#sb-nvd').textContent = payload.lookups && payload.nvd ? 'NVD on' : '';
          $('#sb-mode').textContent = payload.connected ? 'Cloudflare connected' : 'Offline \u00b7 local manifest';
          $('#sb-version').textContent = payload.version ? 'v' + payload.version : '';
          break;
        }
        case 'browse-script-result':
          if (payload.ok && /^f-(prehook|posthook|postuninstallhook)$/.test(payload.field)) $('#' + payload.field).value = payload.path;
          break;
        case 'preflight-blocked': {
          const list = (payload.findings || []).map(f => `<li style="margin:4px 0;color:${f.level === 'red' ? 'var(--bad)' : 'var(--warn)'}">${escapeHtml(f.message)}</li>`).join('');
          $('#step-list').innerHTML = `<div class="phase doing"><span class="pi"><svg viewBox="0 0 24 24"><path d="M5 13l4 4L19 7"/></svg></span>Pre-deploy checks &middot; stopped</div>`;
          $('#progress-error-title').textContent = 'Build stopped by pre-deploy checks';
          $('#progress-error-msg').innerHTML = `<div>Pre-deploy checks found a problem with this installer. Check where it came from before deploying it.</div><ul style="margin:8px 0 0 18px;padding:0">${list}</ul>
            <button class="btn danger sm" id="preflight-override" style="margin-top:10px">Build anyway</button>`;
          $('#progress-error').style.display = 'block';
          $('#preflight-override').addEventListener('click', () => {
            if (!window._lastBuildPayload) return;
