  let epmState = null;
  const wingetText = w => !w ? '' : ({ match: 'winget has the same hash', 'vendor-newer': `vendor is newer than winget ${w.version}`,
    'winget-newer': `winget has a newer ${w.version}; check the source`, missing: 'not in winget', 'not-checked': 'no winget ID',
    'hash-mismatch': `winget lists a different hash for ${w.version}` })[w.status] || w.status;
  function renderEpm(st) {
    if (st) epmState = st;
    const s = epmState || {}, cfg = s.cfg, last = s.last && s.last.at;
    const stale = last && Date.now() - new Date(last).getTime() > 36 * 3600e3;
    const onAzure = !!(cfg && cfg.runner === 'azure');
    $('#epm-status-t').textContent = !cfg ? 'Not set up' : stale ? 'Checks have stopped' : (last ? 'Checking every 6 hours' : 'Waiting for the first run') + (onAzure ? ' on Azure' : ' on GitHub');
    $('#epm-status').textContent = !cfg ? 'A hosted machine on GitHub or Azure checks each vendor every 6 hours. Set up shows the costs of each before anything is created.'
      : stale ? `Last run ${ago(last)}. ` + (onAzure ? 'Check the Automation account’s Jobs in the Azure portal.' : 'GitHub pauses Actions when the monthly spending limit is reached, and resumes on the 1st.')
      : cfg.repo + (last ? ' · last run ' + ago(last) : '');
    $('#epm-cost').hidden = !onAzure;
    $('#epm-cost').textContent = 'Expected Azure cost: $0 to $0.05 a month (Automation free minutes plus a few KB of storage). Review it on your Azure bill; prices can change.';
    $('#epm-azure-remove').hidden = $('#epm-azure-pricing').hidden = !onAzure;
    $('#epm-setup').textContent = cfg ? 'Change…' : 'Set up…';
    $('#epm-add').hidden = !cfg;
    const apps = s.apps || [], res = s.results || {};
    $('#epm-apps').innerHTML = apps.map(a => {
      const r = res[a.id], src = a.source.type === 'github' ? a.source.repo : a.source.url.replace(/^https:\/\//, '');
      const [tone, tag] = !r ? ['', 'waiting'] : r.status === 'ok' ? ['ok', 'v' + r.version] : r.status === 'blocked' ? ['bad', 'blocked'] : ['wn', 'error'];
      const detail = !r ? 'Checked on the next run.' : r.status === 'ok'
        ? `SHA-256 ${String(r.sha256).slice(0, 16)}… · signed by ${r.signer} · ${wingetText(r.winget)}` : (r.version ? r.version + ': ' : '') + r.reason;
      return `<div class="epm-row"><div><b>${escapeHtml(a.name)}</b><small class="mono">${escapeHtml(src)}</small><small>${escapeHtml(detail)}</small></div>`
        + `<span class="badge ${tone}">${escapeHtml(tag)}</span><button class="linkbtn" data-epm-remove="${escapeHtml(a.id)}">Remove</button></div>`;
    }).join('') || '<p class="bnote" style="margin:8px 0 0">No apps watched yet.</p>';
  }
  function ago(at) {
