  }
  const actBtn = (act, id, extra) => `<button class="btn sm${act[2] ? ' primary' : ''}" ${act[1]}="${escapeHtml(id)}"${extra || ''}>${escapeHtml(act[0])}</button>`;
  let queueSel = 0;
