      .sort((x, y) => rank[x.st.tone] - rank[y.st.tone]);
    // Apps asked about that are no longer in the fleet still get asked.
    for (const d of window._feedbackDue) if (feedbackOpen(d.id) && !lastFleet.some(a => a.id === d.id))
