  $('#btn-export-recovery').addEventListener('click', async () => {
    const v = await uiDialog({ title: 'Protect the recovery bundle', text: 'The bundle holds your worker token. Choose a passphrase of at least 8 characters; you need it to restore.',
      fields: [{ id: 'pass', label: 'Passphrase', type: 'password' }, { id: 'again', label: 'Passphrase again', type: 'password' }], ok: 'Choose where to save…',
      validate: v => v.pass.length < 8 ? 'Use at least 8 characters.' : v.pass !== v.again ? 'The passphrases do not match.' : '' });
