  function logLine(text, cls) {
    const log = $('#log');
    const row = document.createElement('div');
    const t = (log.children.length * 0.3).toFixed(1);
    row.innerHTML = `<span class="t">${t}s</span><span class="${escapeHtml(cls||'in')}">${escapeHtml(text)}</span>`;
    log.appendChild(row);
    while (log.children.length > 1000) log.firstElementChild.remove();
    log.scrollTop = log.scrollHeight;
  }

  const stepLabels = ['Generating deploy script', 'Generating detect script', 'Updating manifest', 'Packaging output', 'Finalizing'];
  function renderStepList(currentStep, label) {
    const [n] = String(currentStep).split('/').map(Number);
    $('#step-list').innerHTML = stepLabels.map((l, i) => {
      const idx = i + 1;
      const cls = idx < n ? 'did' : idx === n ? 'doing' : '';
      const icon = `<span class="pi"><svg viewBox="0 0 24 24"><path d="M5 13l4 4L19 7"/></svg></span>`;
      return `<div class="phase ${cls}">${icon}${idx}/${stepLabels.length} &middot; ${escapeHtml(idx === n ? label : l)}</div>`;
    }).join('');
  }

  // The finished screen says, in order, what to do with the output in Intune; every value has a copy button.
  function renderDoneSheet(payload) {
    const id = $('#f-appid').value || $('#f-printername').value.trim().replace(/[^A-Za-z0-9._-]/g, ''), name = $('#f-displayname').value || $('#f-printername').value || id;
    const printer = form.Kind === 'printer', epm = form.SimplePkgTarget === 'epm', psadt = form.SimplePkgTarget === 'psadt';
    const runtime = !epm && (printer || form.Mode === 'runtime');
    const files = payload.files || [];
    const pkgFile = files.find(f => /\.intunewin$/i.test(f)) || id + '.intunewin';
    const ps = 'powershell.exe -NoProfile -ExecutionPolicy Bypass -File ';
    const groups = [];
    const kind = epm ? 'EPM rule' : (runtime ? 'AppUpdater Runtime · updates itself' : 'Simple Package · you push updates') + (psadt ? ' · PSADT package' : ' · .intunewin');
    groups.push({ t: 'What you built', rows: [['Type', kind], ['Folder', payload.path || '']] });
    const checks = (payload.findings || []).map(f => [f.level === 'red' ? 'Check overridden' : 'Check', f.message, true]);
    if (checks.length) groups.push({ t: 'Checks before deploying', p: 'Read these before you assign the app.', rows: checks });
    if (epm) {
      groups.push({ t: 'Create the rule in Intune', p: 'Endpoint security → Endpoint Privilege Management → Create an Elevation rules policy, then add one rule per row below.',
        rows: [['Policy name', window._epmPolicyName || 'EPM']].concat([].concat(payload.epm || []).flatMap(r => [
          ['File name', r.FileName], ['SHA-256', r.SHA256],
          ['Rule type', r.SuggestedRule + (r.CertificateFile ? ' (certificate file ' + r.CertificateFile + ' is in the folder)' : '')]])), action: ['intune-add-build', 'Add it to Intune for me\u2026'] });
      groups.push({ t: 'Keep it current', p: 'Each new version of the installer needs its own rule. Watching the vendor gets the next hash without downloading it here.', action: ['epm-watch', 'Watch for new versions…'] });
      if (!intune.signedIn) groups.push({ t: 'Check it against Intune (optional)', p: 'Connect your Intune tenant to see whether this version is already allowed and which policy holds this app\u2019s rules. You can connect any time from App fleet \u203a EPM or Settings \u203a 09 Intune for EPM.', action: ['intune-connect', 'Connect Intune\u2026'] });
    } else {
      groups.push({ t: 'Add it in Intune', p: 'Apps → Windows → Add → Windows app (Win32), then upload this file from the folder.', rows: [['Package file', pkgFile]] });
      let install, uninstall, detect;
      if (runtime) { install = ps + `Deploy-${id}.ps1`; uninstall = ps + `Deploy-${id}.ps1 -Uninstall`; detect = `Detect-${id}.ps1`; }
      else if (psadt) { install = ps + 'Deploy-Application.ps1 -DeploymentType Install'; uninstall = ps + 'Deploy-Application.ps1 -DeploymentType Uninstall'; detect = 'detect.ps1'; }
      else { install = ps + 'install.ps1'; uninstall = ps + 'uninstall.ps1'; detect = 'detect.ps1'; }
      groups.push({ t: 'Program', p: 'On the Program page, paste these.', rows: [['Install command', install], ['Uninstall command', uninstall],
        ['Install behaviour', !runtime && window._perUser ? 'User - this installer only installs for the signed-in user' : 'System']] });
      groups.push({ t: 'Detection', p: 'Detection rules → Use a custom detection script, and upload this file from the folder.', rows: [['Detection', 'Custom script: ' + detect]] });
