  });
  $('#epm-wiz-reopen').addEventListener('click', () => send('epm-open-device', {}));
  // Settings › 08: the same choice as the setup screen, then that machine's own walkthrough.
  $('#epm-setup').addEventListener('click', async () => {
    const runner = await chooseCheckMachine();
    if (runner === 'azure') { if (await openAzureSetup()) send('epm-state', {}); }
    else if (runner === 'github') openEpmWizard();
  });
  $('#epm-azure-remove').addEventListener('click', removeAzureAgent);
  $('#epm-azure-pricing').addEventListener('click', () => send('open-azure-pricing', {}));
  $('#epm-apps').addEventListener('click', function (ev) {
    const b = ev.target.closest('[data-epm-remove]');
    if (!b || !epmState) return;
    send('epm-save-apps', { apps: (epmState.apps || []).filter(a => a.id !== b.dataset.epmRemove) });
  });
  $('#epm-add-btn').addEventListener('click', function () {
    const v = id => $(id).value.trim(), msg = $('#epm-add-msg');
    const name = v('#epm-name'), src = v('#epm-source'), vregex = v('#epm-vregex'), download = v('#epm-download');
    const gh = /^(?:https:\/\/github\.com\/)?([\w.-]+\/[\w.-]+?)(?:\.git)?\/?$/.exec(src);
    let source;
    if (vregex && download) source = { type: 'page', url: src, versionRegex: vregex, download };
    else if (gh && !/^https?:\/\/(?!github\.com)/.test(src)) source = { type: 'github', repo: gh[1] };
    else if (/^https:\/\//.test(src)) source = { type: 'redirect', url: src };
    if (!name || !source) { msg.textContent = 'A name and a GitHub repo or https link are needed.'; return; }
    if (source.type === 'page' && !/^https:\/\//.test(src)) { msg.textContent = 'The web page must be an https link.'; return; }
    if (source.type === 'github' && v('#epm-asset')) source.asset = v('#epm-asset');
    if (source.type !== 'page' && vregex) source.versionRegex = vregex;
    const apps = (epmState && epmState.apps) || [];
    let id = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'app';
    for (let n = 2; apps.some(a => a.id === id); n++) id = id.replace(/-\d+$/, '') + '-' + n;
    const app = { id, name, source, publisher: v('#epm-publisher') };
    if (v('#epm-winget')) app.winget = v('#epm-winget');
    msg.textContent = 'Saving…';
    send('epm-save-apps', { apps: apps.concat([app]) });
  });
  $('#docs-reset-onboarding').addEventListener('click', () => {
    uiConfirm('Reset the guide', 'Show the guided tour and first-run hints again? They appear the next time AppUpdater opens.', 'Reset').then(yes => {
      if (!yes) return;
      send('reset-onboarding', {});
      toast('Guide reset', 'Close and reopen AppUpdater to see it again.');
    });
  });
  $('#tgl-cf-nav').addEventListener('click', function(){
    $('#tgl-cf-nav').classList.toggle('on');
    window._showCfNav = $('#tgl-cf-nav').classList.contains('on');
    applyCfNavVisibility();
    saveSettingsNow(); flashSaved();
  });

  function renderFleet(apps) {
    // PS can serialize an empty fleet as {}, which `|| []` would let through.
    lastFleet = Array.isArray(apps) ? apps : [];
    paintFleet();
    renderHomeStats(lastFleet);
    renderGettingStarted();
    const connectCard = $('#connect-card'), workerStatus = $('#worker-status');
    if (window._workerUrl) {
      connectCard.style.display = 'none';
      workerStatus.innerHTML = `<span style="display:flex;align-items:center;gap:10px"><span style="width:8px;height:8px;border-radius:50%;background:var(--ok)"></span><span style="font-family:var(--font-m);font-size:12px;color:var(--ok)">${escapeHtml(window._workerUrl)}</span></span>`;
      $('#worker-on').hidden = false; $('#worker-off').hidden = true;
    } else {
      connectCard.style.display = window._showCfAdvert ? 'block' : 'none';
      workerStatus.innerHTML = '<span class="dim">Not connected. Building works without it.</span>';
      $('#worker-on').hidden = true; $('#worker-off').hidden = false;
    }
  }
  function fleetEmptyHtml() {
    const cf = !window._workerUrl && window._showCfAdvert
      ? ` <button class="linkbtn" data-go="worker">Connect a worker</button> to see devices check in as well. <button class="linkbtn dim" data-fleet-advert-dismiss>Hide this</button>` : '';
    return `<tr><td class="empty-cell" colspan="7">No apps tracked yet. <button class="linkbtn" data-go="build">Build a package</button> and it appears here.${cf}</td></tr>`;
  }
  let fleetView = 'all';
  const fleetViews = [
    ['all', 'All', () => true],
    ['needs', 'Needs you', a => { const st = appState(a); return st.tone === 'bad' || st.tone === 'warn' || !!(st.act && st.act[2]); }],
    ['undeployed', 'Not deployed', a => a.status !== 'deployed'],
    ['newer', 'Newer in winget', a => !!a.newerVersion],
    ['failing', 'Failing', a => a.outcome === 'failed']
  ];
  function ledgerHtml(a) {
    const l = Array.isArray(a.ledger) ? a.ledger : [];
    if (!l.length) return '<span class="id">\u2014</span>';
    return '<div class="ledger">' + l.map(v => `<div class="lv" title="${escapeHtml(v.v)}: built${v.t ? ', tested' : ''}${v.d ? ', deployed' : ''}${v.o === 'ok' ? ', installed fine' : v.o === 'failed' ? ', reported failing' : ''}">
      <div class="sq"><i class="b"></i><i class="${v.t ? 't' : ''}"></i><i class="${v.d ? 'd' : ''}"></i><i class="${v.o === 'ok' ? 'o' : v.o === 'failed' ? 'x' : ''}"></i></div><span>${escapeHtml(v.v)}</span></div>`).join('') + '</div>';
  }
  // EPM apps are the vendor-watched ones plus EPM rules built here; they share Fleet under their own chip.
  const epmAppCount = () => { const w = ((epmState || {}).apps || []).map(a => lettersOf(a.name)); return w.length + lastFleet.filter(a => a.type === 'epm' && !w.includes(lettersOf(a.name))).length; };
  function refreshEpmView() { send('epm-state', {}); if (intune.signedIn) send('intune-read', {}); renderEpmScreen(); }
  function showFleetEpm(open) { goTo('fleet'); fleetView = 'epm'; paintFleet(); refreshEpmView(); if (open) openIntuneWizard(); }
  function paintFleet() {
    const q = ($('#fleet-filter') ? $('#fleet-filter').value : '').toLowerCase();
    $('#fleet-chips').innerHTML = fleetViews.map(v => `<button class="fchip${fleetView === v[0] ? ' on' : ''}" data-fleet-view="${v[0]}">${v[1]} <span>${lastFleet.filter(v[2]).length}</span></button>`).join('')
      + `<button class="fchip${fleetView === 'epm' ? ' on' : ''}" data-fleet-view="epm">EPM <span>${epmAppCount()}</span></button>`;
    const epmView = fleetView === 'epm';
    $('#fleet-grid').hidden = epmView; $('#fleet-epm').hidden = !epmView;
    if (epmView) { $('#fleet-bulk-bar').style.display = 'none'; renderEpmScreen(); return; }
    const pred = (fleetViews.find(v => v[0] === fleetView) || fleetViews[0])[2];
    const apps = lastFleet.filter(a => pred(a) && (!q || a.name.toLowerCase().includes(q) || a.id.toLowerCase().includes(q)));
    const rowsHtml = apps.map(a => {
      const st = appState(a), id = escapeHtml(a.id);
      const primary = st.ask ? `<button class="btn sm primary" data-go="home">Answer</button>` : st.act ? actBtn(st.act, a.id) : '';
      const menu = [
        a.outputDir ? `<button data-open-app="${id}">Open folder</button>` : '',
        a.outputDir && !(st.act && st.act[1] === 'data-test') ? `<button data-test="${id}">Test on this machine</button>` : '',
        st.act && st.act[1] === 'data-rebuild' ? '' : `<button data-rebuild="${id}">Rebuild</button>`,
        a.status !== 'deployed' && !(st.act && st.act[1] === 'data-mark-deployed') ? `<button data-mark-deployed="${id}">Mark deployed</button>` : '',
        `<button class="danger" data-remove="${id}">Remove&hellip;</button>`].join('');
      const checked = selectedFleetIds.has(a.id) ? ' checked' : '';
      return `<tr class="r"><td><input type="checkbox" data-select="${id}"${checked} aria-label="Select ${escapeHtml(a.name)}"></td>
      <td><div class="nm">${escapeHtml(a.name)}</div><div class="id">${id}${a.profile ? ' \u00b7 ' + escapeHtml(a.profile) : ''}</div></td>
      <td class="mono">${escapeHtml(a.version || 'auto')}${a.newerVersion ? `<span class="newer" title="winget package ${escapeHtml(a.wingetId)}"> \u2192 ${escapeHtml(a.newerVersion)}</span>` : ''}</td>
      <td class="mono dim">${escapeHtml(typeLabel(a.type))}</td>
      <td>${ledgerHtml(a)}</td>
      <td class="st ${st.tone}"><span aria-hidden="true">${st.g}</span> ${escapeHtml(st.label)}</td>
      <td><div class="next">${primary}<details class="rowmenu"><summary aria-label="More for ${escapeHtml(a.name)}">\u22ef</summary><div>${menu}</div></details></div></td></tr>`;
    }).join('');
    const presentIds = new Set(apps.map(a => a.id));
    for (const id of Array.from(selectedFleetIds)) if (!presentIds.has(id)) selectedFleetIds.delete(id);
    $('#fleet-table').innerHTML = `<colgroup><col style="width:40px"><col><col style="width:150px"><col style="width:110px"><col style="width:250px"><col style="width:170px"><col style="width:200px"></colgroup>
      <tr><th></th><th>App</th><th>Version</th><th>Output</th><th>Versions <span class="legend">built \u00b7 tested \u00b7 deployed \u00b7 installed</span></th><th>State</th><th style="text-align:right">Next</th></tr>` +
      (rowsHtml || (lastFleet.length ? `<tr><td class="empty-cell" colspan="7">Nothing matches.</td></tr>` : fleetEmptyHtml()));
    const needs = lastFleet.filter(a => appState(a).tone === 'bad' || appState(a).tone === 'warn').length;
    $('#fleet-meta').innerHTML = `${lastFleet.length} app${lastFleet.length === 1 ? '' : 's'}` + (needs ? ` \u00b7 <span style="color:var(--warn)">${needs} need you</span>` : '') + ` \u00b7 ${lastFleet.filter(a => a.status === 'deployed').length} deployed`;
    $('#fleet-summary').textContent = `${lastFleet.length} app${lastFleet.length === 1 ? '' : 's'} tracked`;
    paintBulkBar();
    renderQueue();
  }
  document.addEventListener('click', e => {
    const v = e.target.closest('[data-fleet-view]');
    if (v) { fleetView = v.dataset.fleetView; paintFleet(); if (fleetView === 'epm') refreshEpmView(); }
    // Close any open row menu when clicking elsewhere, or after choosing from it.
    $$('.rowmenu[open]').forEach(m => { if (!m.contains(e.target) || e.target.closest('.rowmenu>div button')) m.open = false; });
  });
  function paintBulkBar() {
    const bar = $('#fleet-bulk-bar');
    if (!bar) return;
    const n = selectedFleetIds.size;
    bar.style.display = n ? 'flex' : 'none';
    if (n) $('#fleet-bulk-count').textContent = `${n} selected`;
  }
  let historyView = 'all', lastHistory = [];
  function renderHistory(events) {
    lastHistory = Array.isArray(events) ? events : [];
    const has = lastHistory.length > 0;
    $('#history-empty').style.display = has ? 'none' : 'block';
    $('#history-table').parentElement.style.display = has ? '' : 'none';
    $('#history-chips').style.display = has ? '' : 'none';
    if (!has) { $('#history-table').innerHTML = ''; return; }
    const kinds = [['all', 'All'], ['built', 'Built'], ['deployed', 'Deployed'], ['removed', 'Removed']];
    const kindOf = ev => (kinds.find(k => k[0] !== 'all' && ev.event.indexOf(k[0]) === 0) || ['other'])[0];
    $('#history-chips').innerHTML = kinds.map(k => `<button class="fchip${historyView === k[0] ? ' on' : ''}" data-history-view="${k[0]}">${k[1]} <span>${k[0] === 'all' ? lastHistory.length : lastHistory.filter(ev => kindOf(ev) === k[0]).length}</span></button>`).join('');
    const q = ($('#history-filter').value || '').toLowerCase();
    const shown = lastHistory.filter(ev => (historyView === 'all' || kindOf(ev) === historyView) && (!q || (ev.name + ' ' + ev.id).toLowerCase().includes(q)));
    let lastDay = '';
    const rowsHtml = shown.map(ev => {
      const d = new Date(ev.at), day = d.toLocaleDateString(undefined, { weekday: 'long', day: 'numeric', month: 'long' }), m = eventMark(ev.event);
      const head = day !== lastDay ? `<tr><td colspan="5" class="dayrow">${escapeHtml(day)}</td></tr>` : '';
      lastDay = day;
      return head + `<tr class="r"><td class="mono dim">${escapeHtml(d.toTimeString().slice(0, 5))}</td>
      <td class="st ${m[0]}"><span aria-hidden="true">${m[1]}</span> ${escapeHtml(ev.event)}</td>
      <td><div class="nm">${escapeHtml(ev.name)}</div><div class="id">${escapeHtml(ev.id)}</div></td>
      <td class="mono dim">${escapeHtml(typeLabel(ev.target))}</td><td class="mono dim">${ev.profile || '\u2014'}</td></tr>`;
    }).join('');
    $('#history-table').innerHTML = `<colgroup><col style="width:90px"><col style="width:200px"><col><col style="width:150px"><col style="width:200px"></colgroup>
      <tr><th>Time</th><th>Event</th><th>App</th><th>Output</th><th>Profile</th></tr>` + (rowsHtml || `<tr><td class="empty-cell" colspan="5">Nothing matches.</td></tr>`);
  }
  document.addEventListener('click', e => { const v = e.target.closest('[data-history-view]'); if (v) { historyView = v.dataset.historyView; renderHistory(lastHistory); } });
  $('#history-filter').addEventListener('input', () => renderHistory(lastHistory));
  document.addEventListener('click', e => {
    const rb = e.target.closest('[data-rebuild]');
    if (rb) {
      const app = lastFleet.find(a => a.id === rb.dataset.rebuild);
      if (app) {
        goTo('build');
        $('#f-appid').value = app.id;
        $('#f-displayname').value = app.name;
        updateSummary();
        toast('Rebuild', 'Fields pre-filled - pick the installer again to continue.');
      }
    }
    const oa = e.target.closest('[data-open-app]');
    if (oa) send('open-folder', { which: 'app', id: oa.dataset.openApp });
    const bs = e.target.closest('[data-browse-script]');
    if (bs) send('browse-script', { field: bs.dataset.browseScript });
    const md = e.target.closest('[data-mark-deployed]');
    if (md) send('mark-deployed', { id: md.dataset.markDeployed });
    const tb = e.target.closest('[data-test]');
    if (tb) openTestModal(tb.dataset.test);
    const rmv = e.target.closest('[data-remove]');
    if (rmv) {
      const id = rmv.dataset.remove, app = lastFleet.find(a => a.id === id), name = app ? app.name : id;
      uiDialog({ title: `Remove ${name}`, sub: id, ok: 'Remove', danger: true, fields: [{ id: 'mode', type: 'choice', options: [
        { value: 'manifest', label: 'Stop tracking it', desc: 'Removes it from the app list. Its files and scheduled tasks on this PC stay, and devices that have it keep working.' },
        { value: 'everything', label: 'Stop tracking it and clean up this PC', desc: `Also deletes, on this PC only: its scheduled tasks, the "Update ${name}" desktop shortcut, its ProgramData folder and its build output.\nDevices that already have it are not affected.`, danger: true }] }]
      }).then(v => { if (v) send('remove-from-fleet', { id, mode: v.mode }); });
    }
    if (e.target.closest('[data-fleet-advert-dismiss]')) {
      window._showCfAdvert = false;
      $('#tgl-cf-advert').classList.remove('on');
      send('dismiss-cloudflare-advert', {});
      paintFleet();
      toast('Hidden', 'Bring it back any time from Worker & settings.');
    }
  });
  document.addEventListener('change', e => {
    const cb = e.target.closest('[data-select]');
    if (cb) {
      if (cb.checked) selectedFleetIds.add(cb.dataset.select); else selectedFleetIds.delete(cb.dataset.select);
      paintBulkBar();
    }
  });
  const fleetBulkMarkBtn = $('#fleet-bulk-mark-deployed');
  if (fleetBulkMarkBtn) fleetBulkMarkBtn.addEventListener('click', () => {
    const ids = Array.from(selectedFleetIds);
    if (!ids.length) return;
    uiConfirm('Mark deployed', `Mark ${ids.length} app${ids.length === 1 ? '' : 's'} as deployed? Home then asks on a later launch whether ${ids.length === 1 ? 'it' : 'they'} installed on devices.`, 'Mark deployed').then(yes => {
      if (!yes) return;
      ids.forEach(id => send('mark-deployed', { id }));
      selectedFleetIds.clear();
      paintBulkBar();
    });
  });
  const fleetBulkClearBtn = $('#fleet-bulk-clear');
  if (fleetBulkClearBtn) fleetBulkClearBtn.addEventListener('click', () => { selectedFleetIds.clear(); paintFleet(); });

  let currentTestId = null;
  function openTestModal(id) {
    currentTestId = id;
    const app = lastFleet.find(a => a.id === id);
    $('#test-modal-title').textContent = 'Test locally' + (app ? ' - ' + app.name : '');
    $('#test-log').innerHTML = '';
    $('#test-also-uninstall').checked = false;
    $('#test-modal').style.display = 'flex';
  }
  $('#test-modal-close').addEventListener('click', () => { $('#test-modal').style.display = 'none'; });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && $('#test-modal').style.display !== 'none') $('#test-modal').style.display = 'none';
  });
  $('#test-modal-start').addEventListener('click', () => {
    $('#test-log').innerHTML = '';
    logTestLine('Starting...', 'ac');
    send('test-locally', { id: currentTestId, alsoUninstall: $('#test-also-uninstall').checked, simulateSystem: $('#test-simulate-system').checked });
  });
  function appendToTestLog(el) {
    const log = $('#test-log');
    log.appendChild(el);
    log.scrollTop = log.scrollHeight;
  }
  function logTestLine(text, cls) {
    const log = $('#test-log');
    const row = document.createElement('div');
    row.innerHTML = '<span class="' + escapeHtml(cls||'in') + '">' + escapeHtml(text) + '</span>';
    log.appendChild(row);
    while (log.children.length > 1000) log.firstElementChild.remove();
    log.scrollTop = log.scrollHeight;
  }
  if ($('#fleet-filter')) $('#fleet-filter').addEventListener('input', paintFleet);

  $('#connect-preview-btn').addEventListener('click', () => {
    const demo = $('#connect-demo');
    demo.style.display = demo.style.display === 'none' ? 'block' : 'none';
  });
  $('#connect-card-dismiss').addEventListener('click', () => {
    window._showCfAdvert = false;
    $('#tgl-cf-advert').classList.remove('on');
    send('dismiss-cloudflare-advert', {});
    renderFleet(lastFleet);
    toast('Hidden', 'Bring it back any time from Worker & settings.');
  });
  $('#getting-started-dismiss').addEventListener('click', () => {
    window._showGettingStarted = false;
    $('#tgl-getting-started').classList.remove('on');
    send('dismiss-getting-started', {});
    renderGettingStarted();
    toast('Hidden', 'Bring it back any time from Worker & settings.');
  });


  // Connect to Cloudflare: why, the token, account and status password, then live setup.
  async function openConnectWizard() {
    if (window._workerUrl) { goTo('worker'); return; }
    const sub = n => `Step ${n} of 4`;
    const intro = await uiDialog({ title: 'Connect to Cloudflare', sub: sub(1), ok: 'Next', walk: { step: [1, 4],
      lead: 'A Cloudflare worker is a small free service on your own Cloudflare account. It is how deployed devices report back.',
      rows: [['●', 'Live fleet', 'Devices report which version they have and whether installs worked; Fleet and Home show it.'],
             ['↻', 'Self-updating apps', 'Apps built to update themselves check the worker for new versions.'],
             ['⌂', 'Status page', 'A password-protected page with your fleet that opens in any browser.'],
             ['#', 'EPM vendor checks', 'New versions and their SHA-256 arrive through it.']],
      note: 'You need a Cloudflare account; the free plan is enough. Building packages works without any of this.' } });
    if (!intro) return;
    let accounts = null, token = '';
    while (!accounts) {
      const t = await uiDialog({ title: 'Create a Cloudflare API token', sub: sub(2), ok: 'Check token', walk: { step: [2, 4],
        rows: [['1', 'Open the token page', 'Use the button below, then choose Create Token.'],
               ['2', 'Use the "Edit Cloudflare Workers" template', 'Choose Use template next to it.'],
               ['3', 'Check its permissions', 'Workers Scripts: Edit · Workers KV Storage: Edit · Account Settings: Read'],
               ['4', 'Create it and paste it below', 'It is used for setup only and not saved.']] },
        fields: [{ id: 'token', label: 'API token', type: 'password', mono: true, value: token }],
        validate: v => v.token.trim() ? '' : 'Paste the token Cloudflare showed you.', extra: ['Open Cloudflare token page', () => send('cf-open-tokens', {})] });
      if (!t) return;
      token = t.token.trim();
      uiProgress('Checking the token', sub(2));
      const r = await new Promise(res => { window._cfLookup = res; send('cf-lookup', { token }); });
      if (r.ok) { uiClose(null); accounts = r.accounts; }
      else { uiProgressDone(false, r.message || 'Cloudflare did not accept the token.'); await new Promise(res => { const c = $('#ui-dlg-foot [data-ui="close"]'); c.textContent = 'Try again'; c.addEventListener('click', res, { once: true }); }); }
    }
    const org = window._defaultOrgName || '';
    const d = await uiDialog({ title: 'Account and status page', sub: sub(3), ok: 'Connect', walk: { step: [3, 4],
      lead: 'Last details before setup. The password goes straight to your worker and is not kept on this PC.' },
      fields: [
        accounts.length > 1 ? { id: 'account', type: 'choice', label: 'Cloudflare account', options: accounts.map(a => ({ value: a.id, label: a.name })) } : null,
        { id: 'orgName', label: 'Organisation name', value: org, hint: 'Shown to users in update windows.' },
        { id: 'pass', label: 'Status page password', type: 'password', hint: 'At least 12 characters, with a letter and a digit.' },
        { id: 'again', label: 'Password again', type: 'password' }].filter(Boolean),
      validate: v => !v.orgName.trim() ? 'Enter your organisation name.' : (v.pass.length < 12 || !/[A-Za-z]/.test(v.pass) || !/\d/.test(v.pass)) ? 'Use at least 12 characters, with a letter and a digit.' : v.pass !== v.again ? 'The passwords do not match.' : '' });
    if (!d) { token = ''; return; }
    const acct = accounts.length > 1 ? accounts.find(a => a.id === d.account) : accounts[0];
    const closed = uiProgress('Setting up your worker', sub(4) + ' · about a minute');
    send('cf-connect', { token, accountId: acct.id, accountName: acct.name, orgName: d.orgName.trim(), password: d.pass });
    token = '';
    await closed;
  }


  // Add to Intune: find or create the app's policy, choose who a new policy applies to, offer older versions for
  // removal, preview, then write and read back. The backend takes the hash from its own records, not from here.
  async function pickIntuneTarget(policyName) {
    for (;;) {
      const q = await uiDialog({ title: `Who gets ${policyName}?`, text: 'A new policy is assigned once. Later versions go into the same policy.', ok: 'Next',
        fields: [{ id: 'who', type: 'choice', options: [{ value: 'group', label: 'A group', desc: 'Search for an Entra group by name.' }, { value: 'allUsers', label: 'All users' }, { value: 'allDevices', label: 'All devices' }] },
          { id: 'q', label: 'Group name starts with', showIf: v => v.who === 'group' }],
        validate: v => v.who === 'group' && (v.q || '').trim().length < 2 ? 'Type at least two letters of the group name.' : '' });
      if (!q) return null;
      if (q.who !== 'group') return { id: q.who, label: q.who === 'allUsers' ? 'all users' : 'all devices' };
      uiProgress('Finding groups', 'searching Entra');
      const r = await new Promise(res => { window._intuneGroups = res; send('intune-groups', { q: q.q.trim() }); });
      uiClose(null);
      const groups = [].concat(r.groups || []);
      if (!r.ok || !groups.length) { await uiDialog({ title: 'No groups found', text: r.message || `No group name starts with "${q.q.trim()}".`, ok: 'Search again', cancel: '' }); continue; }
      const g = await uiDialog({ title: 'Choose the group', ok: 'Use this group', fields: [{ id: 'g', type: 'choice', options: groups.map(x => ({ value: x.id, label: x.name, desc: x.description || '' })) }] });
      if (!g) return null;
      const grp = groups.find(x => x.id === g.g);
      return { id: grp.id, label: grp.name };
    }
  }
  async function addToIntune(item) {
    if (!window._intuneWrite) {
      const v = await uiDialog({ title: 'Adding rules is switched off', ok: 'Open Settings', cancel: 'Close',
        text: 'AppUpdater can add this rule to the app’s EPM policy and check it by reading the policy back. Switch it on in Settings › 09 Intune for EPM. Until then, copy the values into Intune yourself.' });
      if (v) { goTo('worker'); $('#intune-section').scrollIntoView({ block: 'start' }); }
      return;
    }
    if (!intune.signedIn || !intune.canWrite) {
      const v = await uiDialog({ title: 'Connect Intune first', ok: 'Connect Intune…',
        text: intune.signedIn ? 'The current sign-in can only read. Connect again and approve adding rules.' : 'Connect your Intune tenant so AppUpdater can add the rule.' });
      if (v) { if (intune.signedIn) send('intune-signout', {}); openIntuneWizard(); }
      return;
    }
    const hash = String(item.hash || '').toUpperCase(), app = { name: item.name };
    const holding = intune.policies.find(p => p.rules.some(r => r.hash === hash));
    if (holding) { toast('Already in Intune', `${item.name} ${item.version} is in ${holding.name}.`); return; }
    const pol = policyForApp(app, hash);
    let target = null;
    const policyName = pol ? pol.name : `EPM · ${item.name}`;
    if (!pol) { target = await pickIntuneTarget(policyName); if (!target) return; }
    // Keep the newest existing rule as the previous version; offer the older ones for removal.
    const mine = pol ? pol.rules.filter(r => r.name && ruleMentions(r, app)) : [];
    const older = mine.slice(0, Math.max(0, mine.length - 1));
    const fields = [{ id: 'ruleType', type: 'choice', label: 'When a standard user runs it', options: [
      { value: 'self', label: 'They confirm it', desc: 'Windows asks for a business reason before it runs elevated.' },
      { value: 'automatic', label: 'It runs elevated straight away', desc: 'No prompt. Use only for installers you fully trust.' }] }];
    if (older.length) fields.push({ id: 'remove', type: 'checks', label: 'Remove older versions (the previous one stays)', options: older.map(r => ({ value: r.name, label: r.name, checked: true })) });
    const v = await uiDialog({ title: `Add ${item.name} ${item.version} to Intune`, ok: 'Add to Intune', fields,
      text: `Policy: ${pol ? `${pol.name} (${assignedText(pol)})` : `${policyName} (new, assigned to ${target.label})`}\nRule: ${item.name} ${item.version}\nFile name: ${item.file}\nSHA-256: ${hash}\nSigned by: ${item.signer || 'not signed'}\n\nAfterwards AppUpdater reads the policy back and checks every value.` });
    if (!v) return;
    uiProgress(`Adding ${item.name} ${item.version}`, 'writing to Intune');
    send('intune-apply', { source: item.source, appId: item.appId || '', hash, appName: item.name, version: item.version, policyId: pol ? pol.id : '', policyName,
      target: target ? target.id : '', ruleType: v.ruleType, removeNames: v.remove || [] });
  }

  // Pick where vendor checks run. Both are hosted machines made for each run; the costs are shown before anything is created.
  const AZURE_REGIONS = [['uksouth', 'UK South'], ['westeurope', 'West Europe'], ['northeurope', 'North Europe'], ['eastus', 'East US'], ['eastus2', 'East US 2'], ['westus2', 'West US 2'], ['australiaeast', 'Australia East'], ['southeastasia', 'Southeast Asia'], ['canadacentral', 'Canada Central']];
  const waitFor = type => new Promise(res => { (window._waiters = window._waiters || {})[type] = res; });
  async function chooseCheckMachine() {
    const v = await uiDialog({ title: 'Where should checks run?', ok: 'Next', wide: true,
      walk: { lead: 'A hosted machine is created for each run, downloads the new installer, checks it and takes its SHA-256, then is deleted. Nothing downloads on your PC.' },
      fields: [{ id: 'runner', type: 'choice', options: [
        { value: 'github', label: 'GitHub · free', desc: 'A private repo in your GitHub account. Private repos get 2,000 free Actions minutes a month; this uses about 15 to 60.\nNew versions wait for you to click Add to Intune. Results come back through your Cloudflare worker.' },
        { value: 'azure', label: 'Azure · expected $0 to $0.05 a month', desc: 'An Automation account and a small storage account in your Azure subscription. Automation includes 500 free job minutes a month; this uses about 120 to 250. Storage for a few KB costs pennies a year.\nIt adds each verified version to Intune by itself. Needs an Azure subscription, which asks for a card.' }] }],
      extra: ['Azure pricing', () => send('open-azure-pricing', {})] });
    return v ? v.runner : '';
  }
  async function openAzureSetup() {
    const intro = await uiDialog({ title: 'Run checks on Azure', sub: 'Step 1 of 5', ok: 'Sign in to Azure…', wide: true, extra: ['Azure pricing', () => send('open-azure-pricing', {})], walk: { step: [1, 5],
      lead: 'AppUpdater creates one resource group, appupdater-epm, in a subscription you choose. Removing that group removes everything.',
      rows: [['1', 'Automation account with its own identity', 'Runs the check every 6 hours. 500 free job minutes a month, then about $0.002 a minute; this uses roughly 120 to 250.'],
             ['2', 'Storage account, one private container', 'Holds the watch list and results. A few KB: well under $0.05 a month.'],
             ['3', 'Permission for that identity', 'Change Intune device configuration only. Free.'],
             ['$', 'Expected total: $0 to $0.05 a month', 'Prices vary by region and can change, so review them yourself on Azure’s pricing page and keep an eye on your Azure bill.', 'warn']],
      note: 'You need the Owner role on the subscription now, and a Global or Privileged Role Administrator for the Intune permission in step 4.' } });
    if (!intro) return false;
    // 2: sign in
    let closed = uiProgress('Sign in to Azure', 'Step 2 of 5');
    send('azure-signin', {});
    const code = await waitFor('azure-code');
    if (!code.ok) { uiProgressDone(false, code.message || 'Microsoft did not return a sign-in code.'); await closed; return false; }
    $('#ui-dlg-body').innerHTML = `<p class="bnote">Microsoft’s sign-in page has opened. Enter this code with an account that is Owner of the subscription:</p><div class="epm-code">${escapeHtml(code.code)}</div>`;
    const signed = await waitFor('azure-signed-in');
    if (!signed.ok) { uiProgressDone(false, signed.message || 'Sign-in did not finish.'); await closed; return false; }
    uiClose(null);
    // 3: subscription and region
    const subs = [].concat(signed.subscriptions || []);
    const where = await uiDialog({ title: 'Subscription and region', sub: 'Step 3 of 5', ok: 'Create in Azure', wide: true, walk: { step: [3, 5], lead: `Signed in as ${signed.account}. Choose where the resource group goes.` },
      fields: [{ id: 'sub', type: 'choice', label: 'Subscription', options: subs.map(x => ({ value: x.id, label: x.name, desc: x.id })) },
               { id: 'loc', type: 'choice', label: 'Region (pick one near you; prices differ slightly)', options: AZURE_REGIONS.map(([value, label]) => ({ value, label })) }] });
    if (!where) return false;
    // 4: create, then the Intune permission
    closed = uiProgress('Creating in Azure', 'Step 4 of 5 · a few minutes');
    send('azure-create', { subscriptionId: where.sub, location: where.loc });
    const made = await waitFor('azure-created');
    uiProgressDone(made.ok, made.ok ? `Created. Storage ${made.storageAccount}; the container key is in Windows Credential Manager.` : (made.message || 'Azure did not finish.'));
    await closed;
    if (!made.ok) return false;
    const admin = await uiDialog({ title: 'Allow it to change Intune policies', sub: 'Step 4 of 5', ok: 'Sign in as admin…', wide: true, walk: { step: [4, 5],
      lead: 'The Automation account’s identity needs one Microsoft Graph permission: change Intune device configuration. An admin approves it once.',
      rows: [['i', 'Who can approve', 'A Global Administrator or Privileged Role Administrator.'], ['i', 'What it can do', 'Read and change device configuration policies, which include EPM. Nothing else in your tenant.']] } });
    if (!admin) return false;
    closed = uiProgress('Approving the permission', 'Step 4 of 5');
    send('azure-grant', {});
    const gcode = await waitFor('azure-grant-code');
    if (!gcode.ok) { uiProgressDone(false, gcode.message || 'Microsoft did not return a sign-in code.'); await closed; return false; }
    uiProgressLine('step', `Enter ${gcode.code} on Microsoft’s page with an admin account`);
    const granted = await waitFor('azure-granted');
    uiProgressDone(granted.ok, granted.ok ? 'Permission approved.' : (granted.message || 'The permission was not approved.'));
    await closed;
    if (!granted.ok) return false;
    // 5: test run
    closed = uiProgress('Testing the Azure machine', 'Step 5 of 5 · 2 to 5 minutes');
    send('azure-test', {});
    const tested = await waitFor('azure-tested');
    uiProgressDone(tested.ok, tested.ok ? 'Test passed. Checks now run every 6 hours on Azure.' : (tested.message || 'The test run did not finish.'));
    await closed;
    if (tested.ok && tested.state) { renderEpm(tested.state); renderEpmScreen(); }
    return !!tested.ok;
  }
  async function removeAzureAgent() {
    const yes = await uiConfirm('Remove from Azure', 'Deletes the appupdater-epm resource group: the Automation account, its schedule and the storage with the results. Vendor checks stop. Your Intune policies are not touched.', 'Delete from Azure', true);
    if (!yes) return;
    send('azure-remove', {});
    let r = await waitFor('azure-removed');
    if (!r.ok && r.needSignIn) {
      const closed = uiProgress('Sign in to Azure', 'to remove the resource group');
      send('azure-signin', {});
      const code = await waitFor('azure-code');
      if (!code.ok) { uiProgressDone(false, code.message || 'Microsoft did not return a sign-in code.'); await closed; send('epm-state', {}); return; }
      $('#ui-dlg-body').innerHTML = `<p class="bnote">Enter this code on Microsoft’s page:</p><div class="epm-code">${escapeHtml(code.code)}</div>`;
      const signed = await waitFor('azure-signed-in');
      uiProgressDone(signed.ok, signed.ok ? 'Signed in. Removing…' : (signed.message || 'Sign-in did not finish.'));
      if (signed.ok) { send('azure-remove', {}); r = await waitFor('azure-removed'); uiProgressLine(r.ok ? 'ok' : 'bad', r.ok ? 'Resource group deletion started; Azure finishes it in a few minutes.' : (r.message || 'Azure refused the delete.')); }
      await closed;
    } else toast(r.ok ? 'Removed from Azure' : 'Not removed', r.ok ? 'Azure is deleting the resource group.' : (r.message || 'Azure refused the delete.'), !r.ok);
    send('epm-state', {});
  }

  // The setup screen's map: a train runs example versions through the real path, on the GitHub or Azure line.
  // Lines and stops are fixed markup; only positions, colours and the bubble text change as it runs.
  function mountSubway(host, focus) {
    const runner = epmState && epmState.cfg && epmState.cfg.runner === 'azure' ? 'azure' : 'github', az = runner === 'azure';
    const lit = { overview: ['vendor', 'machine', 'au', 'intune', 'dev'], intune: ['au', 'intune'], write: ['intune'], checks: ['vendor', 'machine', 'au', 'intune'] }[focus] || ['vendor', 'machine', 'au', 'intune', 'dev'];
    const dim = g => lit.includes(g) ? '' : ' dim';
    const checks = [['New version?', 'no → skip'], ['Download', ''], ['Approved signer?', 'no → blocked'], ['SHA-256', ''], ['Same as winget?', 'differs → blocked'], ['Report', '']];
    const stop = (line, i, y) => `<div class="sw-stop${dim('machine')}${(line === 'az') !== az ? ' off' : ''}" style="left:${200 + i * 72}px;top:${y}px" data-stop="${line}${i}"><i style="--c:${line === 'az' ? 'var(--sw-az)' : 'var(--sw-gh)'}"></i><span class="${line === 'az' ? 'up' : ''}">${checks[i][0]}<br><em>${checks[i][1]}</em></span></div>`;
    const main = (g, x, label, sub, up) => `<div class="sw-stop big${dim(g)}" style="left:${x}px;top:125px" data-stop="${g}"><i></i><span class="${up ? 'up' : ''}">${label}<br><small>${sub}</small></span></div>`;
    host.innerHTML = `<div class="sw" style="height:280px"><div class="sw-in">
      <div class="sw-line${dim('vendor')}" style="left:60px;top:134px;width:100px;height:6px"></div>
      <div class="sw-dash" style="left:160px;top:135px;width:440px"></div><div class="sw-note" style="left:245px;top:143px">without a check machine: you pick the installer, hashed on your PC</div>
      <div class="sw-line" style="left:600px;top:134px;width:300px;height:6px"></div>
      <div class="sw-line gh${dim('machine')}${az ? ' off' : ''}" style="left:157px;top:59px;width:6px;height:81px"></div><div class="sw-line gh${dim('machine')}${az ? ' off' : ''}" style="left:157px;top:59px;width:443px;height:6px"></div><div class="sw-line gh${dim('machine')}${az ? ' off' : ''}" style="left:597px;top:59px;width:6px;height:81px"></div>
      <div class="sw-tag gh${az ? ' off' : ''}" style="left:175px;top:22px">GitHub · optional · free · you click Add</div>
      <div class="sw-line az${dim('machine')}${az ? '' : ' off'}" style="left:157px;top:134px;width:6px;height:81px"></div><div class="sw-line az${dim('machine')}${az ? '' : ' off'}" style="left:157px;top:209px;width:553px;height:6px"></div><div class="sw-line az${dim('machine')}${az ? '' : ' off'}" style="left:707px;top:134px;width:6px;height:81px"></div>
      <div class="sw-tag az${az ? '' : ' off'}" style="left:175px;top:258px">Azure · optional · about $0–0.05 a month · adds to Intune itself</div>
      ${checks.map((_, i) => stop('gh', i, 52)).join('')}${checks.map((_, i) => stop('az', i, 202)).join('')}
      ${main('vendor', 48, 'Vendor', 'new release', true)}${main('au', 588, 'AppUpdater', 'App fleet › EPM, Runs')}${main('intune', 698, 'Intune', az ? 'added by Azure, read back' : 'you click Add, read back')}${main('dev', 888, 'Devices', 'elevated if hash matches')}
      <div class="sw-bubble"><b></b><span></span></div><div class="sw-train"></div></div></div>`;
    const inner = host.querySelector('.sw-in');
    // Measured once the dialog has its size; the map is drawn at 948px and scaled down to fit.
    const fit = () => { const w = host.clientWidth, k = w && w < 948 ? w / 948 : 1; inner.style.transform = k < 1 ? `scale(${k})` : ''; host.firstElementChild.style.height = (280 * k) + 'px'; };
    requestAnimationFrame(fit);
    if (window.ResizeObserver) new ResizeObserver(fit).observe(host);
    const y = az ? 212 : 62, cx = i => 210 + i * 72, line = az ? 'az' : 'gh';
    const into = [{ x: 60, y: 137, stop: 'vendor' }, { x: 160, y: 137 }, { x: 160, y }];
    const scenes = [
      ['7-Zip 26.07', [['Vendor', '7-Zip 26.07 released'], ['Check machine', `Fresh ${az ? 'Azure' : 'GitHub'} machine for this run`], ['Check machine', 'Starting the checks'],
        ['New version?', 'Yes: 26.07 (was 26.06)'], ['Download', '7z2607-x64.exe · 1.6 MB'], ['Approved signer?', 'Signed by Igor Pavlov ✓'], ['SHA-256', '9B697F65ECC2…DACF40F42EC'],
        ['Same as winget?', 'winget lists the same hash ✓'], ['Report', 'File deleted, machine gone, result sent']].concat(az
          ? [['Intune', 'Added to Dev Tools EPM, read back ✓', 'ok'], ['Devices', 'A standard user runs it: elevated', 'ok']]
          : [['AppUpdater', 'App fleet › EPM: 26.07 ready to add'], ['Intune', 'You click Add: in Dev Tools EPM, read back ✓', 'ok'], ['Devices', 'A standard user runs it: elevated', 'ok']])],
      ['PowerToys', [['Vendor', 'PowerToys page checked'], ['Check machine', 'Fresh machine for this run'], ['Check machine', 'Starting the checks'], ['New version?', 'Still 0.102.3101. Download skipped.', 'warn']]],
      ['Notepad++ 8.7', [['Vendor', 'Notepad++ 8.7 released'], ['Check machine', 'Fresh machine for this run'], ['Check machine', 'Starting the checks'], ['New version?', 'Yes: 8.7'],
        ['Download', 'npp.8.7.Installer.x64.exe · 4.9 MB'], ['Approved signer?', 'Signed by "Unknown Ltd". Blocked; nothing goes to Intune.', 'bad']]]];
    const path = n => {
      const pts = into.concat(Array.from({ length: 6 }, (_, i) => ({ x: cx(i), y, stop: line + i })));
      return pts.concat(az ? [{ x: 710, y: 137, stop: 'intune' }, { x: 900, y: 137, stop: 'dev' }] : [{ x: 600, y: 137, stop: 'au' }, { x: 710, y: 137, stop: 'intune' }, { x: 900, y: 137, stop: 'dev' }]).slice(0, n);
    };
    let sc = 0, i = 0;
    const train = inner.querySelector('.sw-train'), bubble = inner.querySelector('.sw-bubble');
    const step = () => {
      if (!host.isConnected) return;
      const [, msgs] = scenes[sc], pts = path(msgs.length), p = pts[i], [head, text, tone] = msgs[i];
      inner.querySelectorAll('.sw-stop').forEach(el => el.classList.remove('on', 'bad'));
      pts.slice(0, i + 1).forEach(q => { const el = q.stop && inner.querySelector(`[data-stop="${q.stop}"]`); if (el) el.classList.add(tone === 'bad' && q === p ? 'bad' : 'on'); });
      train.style.left = (p.x - 7) + 'px'; train.style.top = (p.y - 7) + 'px'; train.className = 'sw-train' + (tone === 'bad' ? ' bad' : az ? ' az' : '');
      bubble.style.left = Math.min(Math.max(p.x - 115, 0), 948 - 230) + 'px'; bubble.style.top = (p.y < 100 ? p.y + 62 : p.y > 180 ? p.y - 92 : p.y + 56) + 'px';
      bubble.className = 'sw-bubble ' + (tone || ''); bubble.firstElementChild.textContent = head; bubble.lastElementChild.textContent = text;
      if (++i >= msgs.length) { i = 0; sc = (sc + 1) % scenes.length; setTimeout(step, 2600); } else setTimeout(step, 1300);
    };
    step();
  }
  // App fleet's EPM view: what the vendor checks found next to the elevation rules already in Intune. Read-only.
  let intune = { signedIn: false, account: '', policies: [], loaded: false };
  const lettersOf = v => String(v || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  const ruleType = t => ({ automatic: 'Automatic', self: 'User confirmed', supportarbitrated: 'Support approved', deny: 'Deny' })[String(t || '').toLowerCase()] || t || 'Unknown type';
  const ruleMentions = (rule, app) => { const n = lettersOf(app.name); return n.length >= 3 && [rule.fileName, rule.product, rule.name, rule.internalName].some(f => lettersOf(f).includes(n)); };
  function policyForApp(app, hash) {
    const ps = intune.policies;
    return ps.find(p => hash && p.rules.some(r => r.hash === hash)) || ps.find(p => p.name === `EPM · ${app.name}`) || ps.find(p => p.rules.some(r => ruleMentions(r, app))) || null;
  }
  const assignedText = p => !p.assignments.length ? 'not assigned' : 'assigned to ' + p.assignments.map(a => (a.exclude ? 'not ' : '') + (a.name || 'a group')).join(', ');
  function renderEpmScreen() {
    const s = epmState || {}, apps = s.apps || [], res = s.results || {};
    const chip = $('[data-fleet-view="epm"] span');
    if (chip) chip.textContent = epmAppCount();
    window._epmView = { intune: intune.signedIn, checks: !!s.cfg, policyFor: n => intune.signedIn ? policyForApp({ name: n }, '') : null };
    updateEpmRows();
    // Until something is connected or built, the view is one line and the setup button.
    const empty = !intune.signedIn && !s.cfg && !apps.length && !lastFleet.some(a => a.type === 'epm');
    $('#epm-empty').hidden = !empty; $('#epm-main').hidden = empty;
    $('#intune-pol-sec').hidden = !intune.signedIn;
    // Each run says what it checked, what it skipped or blocked and why, and what happened in Intune.
    const runs = [].concat(s.runs || []).slice(0, 5);
    $('#epm-runs-sec').hidden = !runs.length;
    $('#epm-runs-meta').textContent = s.cfg && s.cfg.runner === 'azure' ? 'on Azure \u00b7 last 30 kept' : '';
    const mark = { ok: ['ok', '\u2713'], unchanged: ['', '\u2013'], blocked: ['bad', '\u2715'], error: ['warn', '!'], 'source-error': ['warn', '!'] };
    $('#epm-runs').innerHTML = runs.map(r => `<div class="run"><b>${escapeHtml(new Date(r.at).toLocaleString(undefined, { weekday: 'short', hour: '2-digit', minute: '2-digit' }))}</b>`
      + ([].concat(r.items || []).map(it => { const m = mark[it.status] || ['', '\u00b7']; return `<div class="ri ${m[0]}"><i>${m[1]}</i><span>${escapeHtml(it.name)}: ${escapeHtml(it.note || it.status)}</span></div>`; }).join('') || '<div class="ri"><i>\u2013</i><span>No apps watched yet.</span></div>') + '</div>').join('');
    $('#epm-screen-watch').hidden = !s.cfg;
    $('#intune-signin').hidden = intune.signedIn; $('#intune-signout').hidden = $('#intune-refresh').hidden = !intune.signedIn;
    $('#intune-set-connect').hidden = intune.signedIn; $('#intune-set-out').hidden = $('#intune-set-open').hidden = !intune.signedIn;
    $('#intune-set-t').textContent = intune.signedIn ? `Connected as ${intune.account || 'your account'}` : 'Not connected';
    $('#intune-set-s').textContent = intune.signedIn
      ? `${intune.policies.length} elevation rules polic${intune.policies.length === 1 ? 'y' : 'ies'}` + (intune.settingsPolicies === 0 ? '. No elevation settings policy turns EPM on for devices yet.' : '') + '. The sign-in lasts until AppUpdater closes.'
      : 'Needs EPM licensed in the tenant and an Intune Administrator or Endpoint Security Manager account.';
    $('#intune-status-t').textContent = intune.signedIn ? `Intune: connected as ${intune.account || 'your account'}` : 'Intune not connected';
    $('#intune-status').textContent = intune.signedIn
      ? `${intune.policies.length} elevation rules polic${intune.policies.length === 1 ? 'y' : 'ies'}.`
        + (intune.settingsPolicies === 0 ? ' No elevation settings policy turns EPM on for devices yet.' : '')
        + (intune.canWrite ? ' New versions can be added from here.' : window._intuneWrite ? ' Connect again to allow adding rules.' : ' Adding rules is off (Settings \u203a 09).')
      : 'Connect your Intune tenant to see which versions your EPM policies already allow, and to add new ones once adding rules is on in Settings \u203a 09.';
    const watchedNames = apps.map(a => lettersOf(a.name));
    const builtOnly = lastFleet.filter(a => a.type === 'epm' && !watchedNames.includes(lettersOf(a.name)));
    $('#epm-cover').innerHTML = (!apps.length ? ''
      : apps.map(app => {
        const r = res[app.id] || null, ok = r && r.status === 'ok', hash = ok ? String(r.sha256 || '').toUpperCase() : '';
        const found = ok ? `${r.version} verified, signed by ${r.signer}` : r ? (r.status === 'blocked' ? `${r.version || 'latest'} blocked: ${r.reason}` : `check failed: ${r.reason || 'unknown'}`) : 'waiting for the first check';
        let st = ['dim', intune.signedIn ? 'nothing to compare yet' : 'connect Intune to compare'], act = '';
        if (intune.signedIn && ok) {
          const holding = intune.policies.filter(p => p.rules.some(x => x.hash === hash));
          const pol = policyForApp(app, hash);
          if (holding.length) st = ['ok', `${r.version} is in ${holding.map(p => p.name).join(', ')}`];
          else if (pol && pol.rules.some(x => x.certificate && ruleMentions(x, app))) st = ['ok', `covered by a certificate rule in ${pol.name}`];
          else { st = ['warn', `${r.version} is not in Intune yet` + (pol ? ` (its rules are in ${pol.name})` : '')]; act = `<button class="btn sm" data-epm-add="${escapeHtml(app.id)}">Add to Intune…</button>`; }
        }
        return `<div class="cov"><div><b>${escapeHtml(app.name)}</b><small>${escapeHtml(found)}</small></div><span class="st ${st[0]}">${escapeHtml(st[1])}</span>${act || '<span></span>'}</div>`;
      }).join('')) + builtOnly.map(a => `<div class="cov"><div><b>${escapeHtml(a.name)}</b><small>EPM rule built here for ${escapeHtml(a.version)}; not watched for new versions</small></div>`
        + `<span class="st dim">${intune.signedIn ? 'compare once it is watched' : 'connect Intune to compare'}</span><button class="btn sm" data-epm-watch-built="${escapeHtml(a.id)}">Watch\u2026</button></div>`).join('')
      || '<p class="bnote">No EPM apps yet. Build an EPM rule, or watch an app for new versions.</p>';
    if (!intune.signedIn) { $('#intune-policies').innerHTML = '<p class="bnote">Connect Intune to list them.</p>'; return; }
    const watchedHashes = new Set(apps.map(a => res[a.id] && String(res[a.id].sha256 || '').toUpperCase()).filter(Boolean));
    $('#intune-policies').innerHTML = intune.policies.map(p => `<div class="pol"><h3>${escapeHtml(p.name)}</h3><div class="meta">${escapeHtml(assignedText(p))} · ${p.rules.length} rule${p.rules.length === 1 ? '' : 's'}${p.rules.length >= 90 ? ' · near the 100-rule limit' : ''}</div>`
      + p.rules.map((r, i) => {
        const watched = watchedHashes.has(r.hash) || apps.some(a => ruleMentions(r, a));
        return `<div class="rule"><div><b>${escapeHtml(r.name || r.fileName || 'Unnamed rule')}</b><div class="mono">${escapeHtml(r.fileName || '')}${r.hash ? ' · ' + escapeHtml(r.hash.slice(0, 16)) + '…' : r.certificate ? ' · certificate' : ''}</div></div>`
          + `<span>${escapeHtml(ruleType(r.ruleType))}</span>`
          + (watched ? '<span class="pmeta">watched</span>' : `<button class="linkbtn" data-epm-watch-rule="${escapeHtml(p.id)}:${i}">Watch…</button>`) + '</div>';
      }).join('') + '</div>').join('') || '<p class="bnote">No elevation rules policies in this tenant yet.</p>';
  }
  // Anyone can connect their own tenant: Microsoft's Graph Command Line Tools app signs in, so nothing is registered.
  let intuneWizard = false;
  async function openIntuneWizard() {
    const v = await uiDialog({ title: 'Connect Intune for EPM', sub: 'Step 1 of 3', ok: 'Sign in…', walk: { step: [1, 3],
      lead: 'AppUpdater compares your EPM policies with the versions it knows about' + (window._intuneWrite ? ', and adds new ones for you.' : '.'),
      rows: [['✓', 'EPM licensed in the tenant', 'Intune Suite, the EPM add-on, or its free 90-day trial (Intune admin center › Tenant administration › Intune add-ons).'],
             ['✓', 'An Intune admin account', 'Intune Administrator or Endpoint Security Manager.'],
             ['i', 'Nothing is installed in your tenant', 'Sign-in uses Microsoft’s own Graph Command Line Tools app. The first time, an administrator may need to approve it.'],
             ['i', window._intuneWrite ? 'Read and change policies' : 'Read only', window._intuneWrite ? 'Adding rules is on, so it also asks to change device configuration policies.' : 'Adding rules can be switched on later in Settings › 09.']],
      note: 'The sign-in lasts until AppUpdater closes and is not saved.' } });
    if (!v) return;
    intuneWizard = true;
    const closed = uiProgress('Sign in to Intune', 'Step 2 of 3');
    send('intune-signin', {});
    await closed;
  }
  $('#intune-signin').addEventListener('click', openIntuneWizard);
  $('#intune-set-connect').addEventListener('click', openIntuneWizard);
  $('#epm-fleet-setup').addEventListener('click', () => epmSetupHub());
  $('#epm-empty-setup').addEventListener('click', () => epmSetupHub());
  $('#epm-empty-guide').addEventListener('click', () => $('#epm-guide').click());
  $('#epm-guide').addEventListener('click', () => { goTo('build'); if (form.SimplePkgTarget !== 'epm') pickSeg('segTarget', 'epm'); epmWalkthrough(); });
  $('#tgl-intune-write').addEventListener('click', async () => {
    const on = !window._intuneWrite;
    if (on && !(await uiConfirm('Let AppUpdater add rules?', 'Add to Intune will then write rules into your EPM policies: the new version is added, older ones you tick are removed, and each change is read back and checked.\n\nThis has not been tried against every tenant yet. Try it on a test tenant first if you can. Connect Intune again afterwards so the sign-in includes permission to change policies.', 'Switch on'))) return;
    window._intuneWrite = on;
    $('#tgl-intune-write').classList.toggle('on', on);
    send('set-intune-write', { on });
    flashSaved();
  });
  $('#intune-set-out').addEventListener('click', () => send('intune-signout', {}));
  $('#intune-set-open').addEventListener('click', () => showFleetEpm(false));
  $('#intune-signout').addEventListener('click', () => send('intune-signout', {}));
  $('#intune-refresh').addEventListener('click', () => { $('#intune-status').textContent = 'Reading your EPM policies…'; send('intune-read', {}); });
  $('#epm-screen-watch').addEventListener('click', () => { goTo('worker'); if (epmState && !epmState.cfg) openEpmWizard(); else { $('#epm-add').open = true; $('#epm-section').scrollIntoView({ block: 'start' }); } });
  $('#fleet-epm').addEventListener('click', e => {
    if (e.target.closest('[data-epm-setup]')) { goTo('worker'); openEpmWizard(); return; }
    const add = e.target.closest('[data-epm-add]');
    if (add) {
      const app = ((epmState || {}).apps || []).find(a => a.id === add.dataset.epmAdd), r = ((epmState || {}).results || {})[add.dataset.epmAdd];
      if (app && r) addToIntune({ source: 'watched', appId: app.id, name: app.name, version: r.version, file: r.file, hash: r.sha256, signer: r.signer });
      return;
    }
    const built = e.target.closest('[data-epm-watch-built]');
    if (built) {
      const a = lastFleet.find(x => x.id === built.dataset.epmWatchBuilt);
      goTo('worker');
      if (epmState && !epmState.cfg) { openEpmWizard(); return; }
      $('#epm-add').open = true; $('#epm-name').value = a ? a.name : '';
      $('#epm-section').scrollIntoView({ block: 'start' }); $('#epm-source').focus();
      return;
    }
    const w = e.target.closest('[data-epm-watch-rule]');
    if (w) {
      const [pid, idx] = w.dataset.epmWatchRule.split(':'), p = intune.policies.find(x => x.id === pid), r = p && p.rules[Number(idx)];
      if (!r) return;
      goTo('worker');
      if (epmState && !epmState.cfg) { openEpmWizard(); return; }
      $('#epm-add').open = true;
      $('#epm-name').value = r.product || r.name || String(r.fileName || '').replace(/\.(exe|msi)$/i, '');
      $('#epm-section').scrollIntoView({ block: 'start' }); $('#epm-source').focus();
    }
  });
  // Worker actions; each opens the in-app dialog and runs in the background with a live log.
  const CF_TOKEN = { id: 'token', label: 'Cloudflare API token', type: 'password', mono: true, hint: 'The token you set the worker up with. It is used for this action only and not saved.' };
  const needToken = v => (v.token || '').trim() ? '' : 'Enter your Cloudflare API token.';
  const WORKER_ACTIONS = [
    { id: 'redeploy', label: 'Re-deploy', title: 'Re-deploy the worker', desc: 'Uploads this version of the worker, rotates the event secret and re-sends your app list. Do this after updating AppUpdater.',
      fields: () => [CF_TOKEN], ok: 'Re-deploy', validate: needToken },
    { id: 'domain', label: 'Set up…', title: 'Use your own domain', desc: 'Serve the worker from a domain on your Cloudflare account, such as updates.yourcompany.com. Packages built afterwards use it.',
      fields: w => [{ id: 'domain', label: 'Domain', mono: true, placeholder: 'updates.yourcompany.com', value: w.pendingDomain || '' }, CF_TOKEN], ok: 'Set up domain',
      validate: v => !/^[a-z0-9.-]+\.[a-z]{2,}$/.test((v.domain || '').trim().replace(/^https?:\/\//, '').replace(/\/$/, '')) ? 'Enter a lowercase domain such as updates.yourcompany.com.' : needToken(v) },
    { id: 'password', label: 'Reset…', title: 'Reset the status page password', desc: 'Clears the /status password and signs out every browser. You then choose a new one on the status page; it never passes through this PC.',
      fields: () => [CF_TOKEN], ok: 'Reset password', danger: true, validate: needToken },
    { id: 'mfa', label: 'Open…', title: 'Two-step sign-in for the status page', desc: 'Opens the setup page in your browser. Sign in with the status password, then scan the QR code with an authenticator app such as Microsoft Authenticator.',
      fields: () => [], ok: 'Open setup page' },
    { id: 'url', label: 'Change…', title: 'Change the worker address', desc: 'Only needed when a domain was set up outside AppUpdater. The workers.dev address stays as the fallback.',
      fields: w => [{ id: 'url', label: 'Worker address', mono: true, placeholder: 'https://updates.yourcompany.com', value: w.url || '' }], ok: 'Save address',
      validate: v => /^(https:\/\/)?[A-Za-z0-9.-]+\.[A-Za-z]{2,}(:\d+)?\/?$/.test((v.url || '').trim()) ? '' : 'Enter an https address such as https://updates.yourcompany.com.' },
    { id: 'rotate', label: 'Rotate…', title: 'Rotate the manifest token', desc: 'Makes a new secret for this PC to talk to the worker. The old one stops working at once, so let running builds finish first.',
      fields: () => [CF_TOKEN], ok: 'Rotate token', danger: true, validate: needToken },
    { id: 'disconnect', label: 'Disconnect…', title: 'Disconnect from Cloudflare', desc: '',
      fields: w => [
        { id: 'mode', type: 'choice', options: [
          { value: 'offline', label: 'Disconnect this PC only', desc: 'The worker stays live and devices keep working. You can reconnect any time.' },
          { value: 'delete', label: 'Disconnect and delete the worker', desc: 'Deletes the worker and its data from Cloudflare. Deployed devices lose their update source. This cannot be undone.', danger: true }] },
        { id: 'confirmName', label: `Type ${w.workerName} to confirm`, mono: true, placeholder: w.workerName, showIf: v => v.mode === 'delete' },
        Object.assign({}, CF_TOKEN, { showIf: v => v.mode === 'delete' })],
      ok: 'Disconnect', danger: true,
      validate: v => v.mode !== 'delete' ? '' : v.confirmName !== window._worker.workerName ? `Type ${window._worker.workerName} exactly to delete the worker.` : needToken(v) }
  ];
  window._worker = { url: '', workerName: 'app-updater', pendingDomain: '' };
  function renderWorkerActs() {
    const w = window._worker;
    $('#worker-acts').innerHTML = WORKER_ACTIONS.map(a => {
      const pending = a.id === 'domain' && w.pendingDomain;
      return `<div class="wk-act${pending ? ' warn' : ''}"><div><b>${escapeHtml(pending ? 'Finish setting up ' + w.pendingDomain : a.title)}</b><small>${escapeHtml(a.desc || 'Stop using the worker on this PC, or delete it from Cloudflare.')}</small></div>`
        + `<button class="btn sm${a.id === 'disconnect' ? ' danger' : ''}" data-worker-act="${a.id}">${escapeHtml(a.label)}</button></div>`;
    }).join('');
  }
  let workerActRunning = '';
  async function runWorkerAction(id) {
    const a = WORKER_ACTIONS.find(x => x.id === id), w = window._worker;
    if (!a || workerActRunning) return;
    const v = await uiDialog({ title: a.title, sub: w.url.replace(/^https:\/\//, ''), text: a.desc, fields: a.fields(w), ok: a.ok, danger: !!a.danger, validate: a.validate });
    if (!v) return;
    const payload = Object.assign({ action: a.id === 'disconnect' ? (v.mode === 'delete' ? 'delete' : 'offline') : a.id }, v);
    delete payload.mode;
    workerActRunning = payload.action;
    if (['redeploy', 'domain', 'password', 'rotate', 'delete'].includes(payload.action)) uiProgress(a.title, 'working…');
    send('worker-action', payload);
  }
  $('#worker-acts').addEventListener('click', e => { const b = e.target.closest('[data-worker-act]'); if (b) runWorkerAction(b.dataset.workerAct); });
  $('#connect-btn').addEventListener('click', () => { goTo('worker'); openConnectWizard(); });
  $('#btn-worker-connect').addEventListener('click', () => openConnectWizard());
  $('#btn-open-status').addEventListener('click', () => send('open-status-dashboard', {}));

  send('get-fleet', {});
  send('get-settings', {});
  send('get-profiles', {});
  send('get-history', {});
  send('get-psadt-stock-assets', {});
  send('get-status', {});
  // The status line also covers catalogues that finish downloading after launch.
  setInterval(() => send('get-status', {}), 60000);

  // Keyboard layer: number keys for the rail, Ctrl+O to pick an installer, Ctrl+Enter to build, Ctrl+K for every command.
  $$('.rail .nav-btn[data-go]').forEach((b, i) => { if (i < 6) b.insertAdjacentHTML('beforeend', `<span class="nav-num" aria-hidden="true">${i + 1}</span>`); });
  const railScreens = ['home', 'build', 'fleet', 'profiles', 'history', 'worker'];
  const pickInstaller = () => { goTo('build'); if (form.Kind !== 'printer') send('browse-installer', {}); };
  const buildNow = () => { if (!$('#screen-build').classList.contains('on')) goTo('build'); else if (!$('#btn-build').disabled) $('#btn-build').click(); };
  const commands = [
    ['Go', 'Home', () => goTo('home'), '1'], ['Go', 'Package builder', () => goTo('build'), '2'], ['Go', 'App fleet', () => goTo('fleet'), '3'],
    ['Go', 'Client profiles', () => goTo('profiles'), '4'], ['Go', 'History', () => goTo('history'), '5'], ['Go', 'Worker & settings', () => goTo('worker'), '6'], ['Go', 'Fleet: EPM apps and Intune', () => showFleetEpm(false)],
    ['Build', 'Pick an installer', pickInstaller, 'Ctrl O'], ['Build', 'Build package', buildNow, 'Ctrl \u21b5'],
    ['Build', 'Delivery: Simple', () => { goTo('build'); pickSeg('segMode', 'simple'); }], ['Build', 'Delivery: Runtime', () => { goTo('build'); pickSeg('segMode', 'runtime'); }],
    ['Build', 'Output: .intunewin', () => { goTo('build'); pickSeg('segTarget', 'intunewin'); }], ['Build', 'Output: PSADT', () => { goTo('build'); pickSeg('segTarget', 'psadt'); }], ['Build', 'Output: EPM rule', () => { goTo('build'); pickSeg('segTarget', 'epm'); }],
    ['Build', 'Package a printer', () => { goTo('build'); pickSeg('segKind', 'printer'); }],
    ['Settings', 'Toggle online lookups', () => { goTo('worker'); $('#tgl-release-check').click(); }]
  ];
  let cmdSel = 0, cmdShown = [];
  document.body.insertAdjacentHTML('beforeend', `<div id="cmdk" hidden><div class="box" role="dialog" aria-label="Commands"><input id="cmdk-input" placeholder="Type a command or screen" aria-label="Command"><ul id="cmdk-list"></ul>
    <div class="foot"><span>\u2191\u2193 move</span><span>Enter run</span><span>Esc close</span></div></div></div>`);
  function renderCommands() {
    const q = $('#cmdk-input').value.trim().toLowerCase();
    cmdShown = commands.filter(c => !q || (c[0] + ' ' + c[1]).toLowerCase().includes(q));
    cmdSel = Math.max(0, Math.min(cmdSel, cmdShown.length - 1));
    $('#cmdk-list').innerHTML = cmdShown.map((c, i) => `<li class="${i === cmdSel ? 'sel' : ''}" data-i="${i}"><span class="grp">${escapeHtml(c[0])}</span><b>${escapeHtml(c[1])}</b>${c[3] ? `<kbd>${escapeHtml(c[3])}</kbd>` : ''}</li>`).join('');
  }
  const openCommands = () => { $('#cmdk').hidden = false; $('#cmdk-input').value = ''; cmdSel = 0; renderCommands(); $('#cmdk-input').focus(); };
  const closeCommands = () => { $('#cmdk').hidden = true; };
  const runCommand = i => { const c = cmdShown[i]; closeCommands(); if (c) c[2](); };
  $('#cmd-open').addEventListener('click', openCommands);
  $('#cmdk-input').addEventListener('input', () => { cmdSel = 0; renderCommands(); });
  $('#cmdk').addEventListener('click', e => { const li = e.target.closest('li'); if (li) runCommand(Number(li.dataset.i)); else if (e.target.id === 'cmdk') closeCommands(); });
  document.addEventListener('keydown', e => {
    const ctrl = e.ctrlKey || e.metaKey, key = e.key.toLowerCase();
    if (ctrl && key === 'k') { e.preventDefault(); $('#cmdk').hidden ? openCommands() : closeCommands(); return; }
    if (!$('#cmdk').hidden) {
      if (e.key === 'Escape') closeCommands();
      else if (e.key === 'ArrowDown') { cmdSel++; renderCommands(); e.preventDefault(); }
      else if (e.key === 'ArrowUp') { cmdSel--; renderCommands(); e.preventDefault(); }
      else if (e.key === 'Enter') { e.preventDefault(); runCommand(cmdSel); }
      return;
    }
    const typing = /^(INPUT|TEXTAREA|SELECT)$/.test((document.activeElement || {}).tagName || '');
    if (ctrl && e.key === 'Enter') { e.preventDefault(); buildNow(); }
    else if (ctrl && key === 'o') { e.preventDefault(); pickInstaller(); }
    else if (!ctrl && !e.altKey && !typing && /^[1-6]$/.test(e.key) && $('#test-modal').style.display !== 'flex') goTo(railScreens[Number(e.key) - 1]);
  });

  window._gotFleetData = false;
  setTimeout(() => {
    if (!window._gotFleetData) renderFleet([]);
  }, 5000);
</script>
</body>
</html>

'@

# APPUPDATER_NO_ELEVATE=1 skips elevation for unattended test runs.
$__principal = [Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()
if (-not $__principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) -and $env:APPUPDATER_NO_ELEVATE -ne '1') {
  $__args = @('-Sta', '-ExecutionPolicy', 'Bypass', '-WindowStyle', 'Hidden', '-File', ('"{0}"' -f $PSCommandPath))
  Start-Process (Join-Path $PSHOME 'powershell.exe') -Verb RunAs -ArgumentList ($__args -join ' ')
  exit 0
}

Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase

$__CoreB64Chunks = @(
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
)
try {
  $__CoreSrc = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(($__CoreB64Chunks -join '')))
} catch {
  try { Add-Content -LiteralPath (Join-Path $PSScriptRoot 'AppUpdater.log') -Value "$(Get-Date -Format s) [FATAL] Base64 decode of core blob threw: $($_.Exception.Message)" -ErrorAction Stop } catch {}
  throw 'The embedded AppUpdater engine is damaged. Download a fresh copy.'
}

# Written to a real file so the core script's $PSCommandPath resolves.
$__CoreTempFile = Join-Path ([System.IO.Path]::GetTempPath()) ("AppUpdaterCore_{0}.generated.ps1" -f [guid]::NewGuid().ToString('N'))
try {
  [System.IO.File]::WriteAllText($__CoreTempFile, $__CoreSrc, [System.Text.Encoding]::UTF8)
} catch {
  try { Add-Content -LiteralPath (Join-Path $PSScriptRoot 'AppUpdater.log') -Value "$(Get-Date -Format s) [FATAL] Failed to write core temp file: $($_.Exception.Message)" -ErrorAction Stop } catch {}
  throw 'AppUpdater could not prepare its engine in the temporary folder.'
}

function Ensure-WebView2Assemblies {
  param([string]$Dir, [string]$LoaderDestDir)

  $core   = Join-Path $Dir 'Microsoft.Web.WebView2.Core.dll'
  $wpf    = Join-Path $Dir 'Microsoft.Web.WebView2.Wpf.dll'
  $loader = Join-Path $LoaderDestDir 'WebView2Loader.dll'
  if ((Test-Path $core) -and (Test-Path $wpf) -and (Test-Path $loader)) {
    try {
      $coreVersion = [Reflection.AssemblyName]::GetAssemblyName($core).Version
      $wpfVersion = [Reflection.AssemblyName]::GetAssemblyName($wpf).Version
      if ($coreVersion -eq $wpfVersion -and (Get-Item -LiteralPath $loader).Length -gt 0) { return $true }
    } catch { Write-Warning 'The WebView2 cache is incomplete or damaged; fetching a fresh copy.' }
  }

  try {
    New-Item -ItemType Directory -Path $Dir -Force -ErrorAction Stop | Out-Null
    $tmpZip = Join-Path ([System.IO.Path]::GetTempPath()) "webview2_$([guid]::NewGuid()).zip"
    $tmpExtract = Join-Path ([System.IO.Path]::GetTempPath()) "webview2_$([guid]::NewGuid())"

    $version = '1.0.2792.45'
    $url = "https://www.nuget.org/api/v2/package/Microsoft.Web.WebView2/$version"

    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    Invoke-WebRequest -Uri $url -OutFile $tmpZip -UseBasicParsing -TimeoutSec 60 -ErrorAction Stop

    Add-Type -AssemblyName System.IO.Compression.FileSystem
    [System.IO.Compression.ZipFile]::ExtractToDirectory($tmpZip, $tmpExtract)

    $sourceCore = Join-Path $tmpExtract 'lib\net462\Microsoft.Web.WebView2.Core.dll'
    $sourceWpf = Join-Path $tmpExtract 'lib\net462\Microsoft.Web.WebView2.Wpf.dll'
    if ([Reflection.AssemblyName]::GetAssemblyName($sourceCore).Version -ne [Reflection.AssemblyName]::GetAssemblyName($sourceWpf).Version) { throw 'WebView2 assembly versions do not match.' }
    $arch = if ([IntPtr]::Size -eq 8) { 'win-x64' } else { 'win-x86' }
    $sourceLoader = Join-Path $tmpExtract "runtimes\$arch\native\WebView2Loader.dll"
    # These load into an elevated process; accept only Microsoft-signed binaries.
    foreach ($binary in @($sourceCore, $sourceWpf, $sourceLoader)) {
      $signature = Get-AuthenticodeSignature -LiteralPath $binary -ErrorAction Stop
      if ($signature.Status -ne 'Valid' -or $signature.SignerCertificate.Subject -notmatch 'O=Microsoft Corporation(?:,|$)') {
        throw "The signature of $([IO.Path]::GetFileName($binary)) could not be verified."
      }
    }
    Copy-Item -LiteralPath $sourceCore -Destination $core -Force -ErrorAction Stop
    Copy-Item -LiteralPath $sourceWpf -Destination $wpf -Force -ErrorAction Stop
    Copy-Item -LiteralPath $sourceLoader -Destination $loader -Force -ErrorAction Stop

    return (Test-Path $core) -and (Test-Path $wpf) -and (Test-Path $loader)
  } catch {
    Write-Warning "WebView2 assembly auto-download failed: $($_.Exception.Message)"
    return $false
  } finally {
    foreach ($temporaryPath in @($tmpZip, $tmpExtract)) {
      if ($temporaryPath -and (Test-Path -LiteralPath $temporaryPath)) { Remove-Item -LiteralPath $temporaryPath -Recurse -Force -ErrorAction SilentlyContinue }
    }
  }
}

$__wv2Ready = Ensure-WebView2Assemblies -Dir $Wv2AssemblyDir -LoaderDestDir $PSScriptRoot

function Test-WebView2RuntimeInstalled {
  $keys = @(
    'HKLM:\SOFTWARE\WOW6432Node\Microsoft\EdgeUpdate\Clients\{F3017226-FE2A-4295-8BDF-00C3A9A7E4C5}',
    'HKLM:\SOFTWARE\Microsoft\EdgeUpdate\Clients\{F3017226-FE2A-4295-8BDF-00C3A9A7E4C5}',
    'HKCU:\SOFTWARE\Microsoft\EdgeUpdate\Clients\{F3017226-FE2A-4295-8BDF-00C3A9A7E4C5}'
  )
  foreach ($k in $keys) {
    if (Test-Path $k) {
      $pv = (Get-ItemProperty -Path $k -Name 'pv' -ErrorAction SilentlyContinue).pv
      if ($pv -and $pv -ne '0.0.0.0') { return $true }
    }
  }
  return $false
}

function Install-WebView2Runtime {
  try {
    $setupExe = Join-Path ([System.IO.Path]::GetTempPath()) "MicrosoftEdgeWebview2Setup_$([guid]::NewGuid()).exe"
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    Invoke-WebRequest -Uri 'https://go.microsoft.com/fwlink/p/?LinkId=2124703' -OutFile $setupExe -UseBasicParsing -TimeoutSec 60 -ErrorAction Stop
    $signature = Get-AuthenticodeSignature -LiteralPath $setupExe -ErrorAction Stop
    if ($signature.Status -ne 'Valid' -or $signature.SignerCertificate.Subject -notmatch 'O=Microsoft Corporation(?:,|$)') { throw 'The WebView2 installer signature could not be verified.' }
    $p = Start-Process -FilePath $setupExe -ArgumentList '/silent', '/install' -PassThru -ErrorAction Stop
    if (-not $p.WaitForExit(180000)) { throw 'WebView2 installation timed out after 3 minutes.' }
    return (Test-WebView2RuntimeInstalled)
  } catch {
    Write-Warning "WebView2 runtime install failed: $($_.Exception.Message)"
    return $false
  } finally {
    if ($p) { if (-not $p.HasExited) { $p.Kill() }; $p.Dispose() }
    if ($setupExe -and (Test-Path -LiteralPath $setupExe)) { Remove-Item -LiteralPath $setupExe -Force -ErrorAction SilentlyContinue }
  }
}

if (-not (Test-WebView2RuntimeInstalled)) {
  $__wv2RuntimeReady = Install-WebView2Runtime
  if (-not $__wv2RuntimeReady) { $__wv2Ready = $false }
}

if (-not $__wv2Ready) {
  Add-Type -AssemblyName PresentationFramework
  [System.Windows.MessageBox]::Show(
    "Could not fetch the WebView2 runtime files automatically (no internet, or the download was blocked).`n`n" +
    "Falling back to the classic AppUpdater interface for this run.",
    'AppUpdater', 'OK', 'Information'
  ) | Out-Null
  try { & $__CoreTempFile }
  finally { Remove-Item -LiteralPath $__CoreTempFile -ErrorAction SilentlyContinue }
  exit 0
}

