}

$ManifestPath = Join-Path $env:ProgramData 'AppUpdater\appVersions.xml'

$DeployStatusFile = Join-Path $env:ProgramData 'AppUpdater\deploy-status.json'

function ConvertTo-HashtableShallow($Obj) {
  $ht = @{}
  if ($Obj) { foreach ($p in $Obj.PSObject.Properties) { $ht[$p.Name] = $p.Value } }
  $ht
}

function Get-DeployStatusStore {
  if (-not (Test-Path -LiteralPath $DeployStatusFile)) { return @{} }
  $store = ConvertTo-HashtableShallow (Read-StateJson -Path $DeployStatusFile)
  foreach ($key in @($store.Keys)) { $store[$key] = ConvertTo-HashtableShallow $store[$key] }
  return $store
}

function Save-DeployStatusStore {
  param([hashtable]$Store)
  Write-AtomicText -Path $DeployStatusFile -Text ($Store | ConvertTo-Json -Depth 6)
}

$DeployHistoryFile = Join-Path $env:ProgramData 'AppUpdater\deploy-history.json'
$DeployHistoryMaxEvents = 500

function Get-DeployHistory {
  if (Test-Path -LiteralPath $DeployHistoryFile) { return @(Read-StateJson -Path $DeployHistoryFile -AllowArray) }
  return @()
}

function Add-DeployHistoryEvent {
  param([string]$AppID, [string]$AppName, [string]$Event, [string]$Target, [string]$ProfileName)
  $history = @(Get-DeployHistory)
  $history += [ordered]@{
    id = $AppID; name = $(if ($AppName) { $AppName } else { $AppID })
    event = $Event; at = (Get-Date -Format 'o')
    target = $Target; profile = $ProfileName
  }
  if ($history.Count -gt $DeployHistoryMaxEvents) {
    $history = $history[($history.Count - $DeployHistoryMaxEvents)..($history.Count - 1)]
  }
  Write-AtomicText -Path $DeployHistoryFile -Text (ConvertTo-Json -InputObject @($history) -Depth 6)
}

# Per-app memory for repeat packaging: the settings of the last build and a short build history, keyed by App ID.
$AppMemoryFile = Join-Path $env:ProgramData 'AppUpdater\app-memory.json'
$AppMemoryMaxBuilds = 20
# Prepared winget-pkgs contributions by App ID, waiting for the admin to confirm.
$global:WingetPending = @{}
# Apps marked deployed before this launch are asked about once per launch.
$script:SessionStartedAt = Get-Date
# Version-specific values (installer path, version, minimum version) are not reused as settings.
$AppMemorySettingKeys = @('AppID','DisplayName','RegistryName','SilentArgs','Mode','SimplePkgTarget','PSADTVersion','ProfileName',
                          'ProcessesToKill','AllowDefer','BundleFolder','PerUser','DownloadURL',
                          'PreInstallHookPath','PostInstallHookPath','PostUninstallHookPath','RemoveOlderVersions')

function ConvertTo-PlainHashtable($Obj) {
  if ($Obj -is [Collections.IDictionary]) { return $Obj }
  return ConvertTo-HashtableShallow $Obj
}

function Get-AppMemory {
  if (-not (Test-Path -LiteralPath $AppMemoryFile)) { return @{} }
  $store = ConvertTo-HashtableShallow (Read-StateJson -Path $AppMemoryFile)
  foreach ($key in @($store.Keys)) {
    $app = ConvertTo-PlainHashtable $store[$key]
    $app.settings = ConvertTo-PlainHashtable $app.settings
    $app.keys = ConvertTo-PlainHashtable $app.keys
    $app.builds = @(@($app.builds) | Where-Object { $_ } | ForEach-Object { ConvertTo-PlainHashtable $_ })
    $store[$key] = $app
  }
  return $store
}

function Get-AppFamilyKey([string]$Name, [string]$Publisher) {
  $n = ConvertTo-WingetNormalName $Name
  if (-not $n) { return '' }
  return "$n|$(ConvertTo-WingetNormalName $Publisher -Publisher)"
}

function Find-KnownApp {
  # Strongest identity first: MSI upgrade code, winget package, then name and publisher without versions.
  param([string]$UpgradeCode, [string]$WingetId, [string]$Name, [string]$Publisher)
  $store = Get-AppMemory
  $family = Get-AppFamilyKey $Name $Publisher
  foreach ($test in @(
      @{ Key = 'upgradeCode'; Value = $UpgradeCode }, @{ Key = 'wingetId'; Value = $WingetId }, @{ Key = 'family'; Value = $family })) {
    if (-not $test.Value) { continue }
    $hits = @($store.Keys | Where-Object { [string]$store[$_].keys[$test.Key] -eq $test.Value })
    if ($hits.Count -eq 0) { continue }
    $id = @($hits | Sort-Object { [string](@($store[$_].builds)[-1].at) } -Descending)[0]
    $app = $store[$id]
    $last = @($app.builds)[-1]
    return @{ appId = $id; settings = $app.settings; matchedBy = $test.Key
              lastVersion = [string]$last.version; lastBuiltAt = [string]$last.at
              lastDetectVersion = [string]$last.detectVersion; lastInstallerVersion = [string]$last.installerVersion }
  }
  return $null
}

function Save-AppMemoryBuild {
  param([hashtable]$FormData, [hashtable]$Installer = @{}, [string]$OutputDir, [object[]]$Findings = @())
  $id = [string]$FormData.AppID
  if (-not $id -or $FormData.PackageKind -eq 'Printer') { return }
  $store = Get-AppMemory
  $app = if ($store.ContainsKey($id)) { $store[$id] } else { @{ settings = @{}; keys = @{}; builds = @() } }
  $settings = @{}
  foreach ($k in $AppMemorySettingKeys) { if ($FormData.ContainsKey($k)) { $settings[$k] = $FormData[$k] } }
  $app.settings = $settings
  $identity = ConvertTo-PlainHashtable $FormData.Identity
  if (-not $identity) { $identity = @{} }
  $keys = ConvertTo-PlainHashtable $app.keys
  if (-not $keys) { $keys = @{} }
  $family = Get-AppFamilyKey ([string]$identity.name) ([string]$identity.publisher)
  if ($family) { $keys.family = $family }
  if ($identity.upgradeCode) { $keys.upgradeCode = [string]$identity.upgradeCode }
  if ($identity.wingetId) { $keys.wingetId = [string]$identity.wingetId }
  $app.keys = $keys
  $builds = @(@($app.builds) | Where-Object { $_ }) + @(@{
    version = [string]$FormData.Version; installerVersion = [string]$identity.installerVersion; detectVersion = [string]$FormData.DetectVersion
    at = (Get-Date -Format 'o'); outputDir = $OutputDir; target = [string]$FormData.SimplePkgTarget; mode = [string]$FormData.Mode
    wingetId = [string]$identity.wingetId; sha256 = [string]$Installer.sha256
    signed = [string]$Installer.status; signer = [string]$Installer.signer; thumbprint = [string]$Installer.thumbprint
    findings = @($Findings | ForEach-Object { "$($_.level): $($_.message)" }); overrodeRed = [bool]$FormData.OverrideRed
  })
  if ($builds.Count -gt $AppMemoryMaxBuilds) { $builds = $builds[($builds.Count - $AppMemoryMaxBuilds)..($builds.Count - 1)] }
  $app.builds = $builds
  $store[$id] = $app
  Write-AtomicText -Path $AppMemoryFile -Text ($store | ConvertTo-Json -Depth 8)
}

