    $waitTimer.Interval = [TimeSpan]::FromMilliseconds(50)
    $waitTimer.Add_Tick({ if ($Task.IsCompleted -or $clock.Elapsed.TotalSeconds -ge 60) { $frame.Continue = $false } }.GetNewClosure())
    try {
      $waitTimer.Start()
      if (-not $Task.IsCompleted) { [System.Windows.Threading.Dispatcher]::PushFrame($frame) }
      if (-not $Task.IsCompleted) { throw 'WebView2 initialization timed out after 60 seconds.' }
