                    if (-not $r.ok) { return }
                    try {
                      switch ($r.action) {
                        'domain' {
                          $config.WorkerDevURL = if ($config.WorkerDevURL) { $config.WorkerDevURL } else { $config.WorkerURL }
                          $config.WorkerURL = "https://$($r.domain)"
                          $config.CustomDomainPending = $false; $config.CustomDomainTarget = ''
