              else {
                $agent = ConvertTo-PlainHashtable $config.EpmAzure
                Start-BackgroundAction -Wv $wv -Roots @('Invoke-Arm') -Event 'azure-removed' -TimeoutSeconds 120 -Variables @{ _tok = $AzureAuth.arm; _path = "/subscriptions/$($agent.subscriptionId)/resourceGroups/$($agent.resourceGroup)" } -Script @'
Invoke-Arm -Token $_tok -Path $_path -Api '2021-04-01' -Method Delete | Out-Null
$_result.ok = $true
'@ -OnDone ({
                  param($r)
                  if (-not $r.ok) { return }
                  $config.Remove('EpmAzure'); if ($config.EpmRunner -eq 'azure') { $config.EpmRunner = '' }
                  try { [void][WinCredManager]::Delete('AppUpdater-EpmAzureSas') } catch { }
                  [void](Save-PersistedConfig -Config $config)
                }.GetNewClosure())
              }
            }
            'epm-open-device' { try { Start-Process 'https://github.com/login/device' } catch { } }
            'get-profiles' {
              $pd = Get-PackagingProfiles
              Send-ToPage $wv 'profiles-data' @{ profiles = $pd.Profiles; lastUsed = $pd.LastUsed }
            }
            'save-profile' {
              $p = $msg.payload
              $ok = Save-PackagingProfile -Profile @{
                Name = $p.Name; OrgName = $p.OrgName
                LogoImagePath = $p.LogoImagePath; BannerImagePath = $p.BannerImagePath
                DefaultTarget = $p.DefaultTarget
              }
              $pd = Get-PackagingProfiles
              Send-ToPage $wv 'profiles-data' @{ profiles = $pd.Profiles; lastUsed = $pd.LastUsed; saveOk = $ok }
            }
            'delete-profile' {
              Remove-PackagingProfile -Name $msg.payload.name
              $pd = Get-PackagingProfiles
              Send-ToPage $wv 'profiles-data' @{ profiles = $pd.Profiles; lastUsed = $pd.LastUsed }
            }
            'browse-image' {
              $pickedPath = $null
              if ($env:APPUPDATER_TEST_IMAGE -and (Test-Path -LiteralPath $env:APPUPDATER_TEST_IMAGE -PathType Leaf)) {
                $pickedPath = $env:APPUPDATER_TEST_IMAGE
              } else {
                $ifd = New-Object Microsoft.Win32.OpenFileDialog
                $ifd.Filter = 'Images (*.png;*.jpg;*.jpeg;*.svg)|*.png;*.jpg;*.jpeg;*.svg|All files (*.*)|*.*'
                if ($ifd.ShowDialog($window)) { $pickedPath = $ifd.FileName }
              }
              if ($pickedPath) {
                Send-ToPage $wv 'browse-image-result' @{ ok = $true; field = $msg.payload.field; path = $pickedPath; dataUrl = (Get-ImageDataUrl -Path $pickedPath) }
              } else {
                Send-ToPage $wv 'browse-image-result' @{ ok = $false; field = $msg.payload.field }
              }
            }
            'browse-script' {
              $pickedPath = $null
              if ($env:APPUPDATER_TEST_SCRIPT -and (Test-Path -LiteralPath $env:APPUPDATER_TEST_SCRIPT -PathType Leaf)) {
                $pickedPath = $env:APPUPDATER_TEST_SCRIPT
              } else {
                $sfd = New-Object Microsoft.Win32.OpenFileDialog
                $sfd.Filter = 'PowerShell scripts (*.ps1)|*.ps1'
                if ($sfd.ShowDialog($window)) { $pickedPath = $sfd.FileName }
              }
              if ($pickedPath) { Send-ToPage $wv 'browse-script-result' @{ ok = $true; field = [string]$msg.payload.field; path = $pickedPath } }
            }
            'get-image-preview' {
              Send-ToPage $wv 'image-preview-result' @{ field = $msg.payload.field; dataUrl = (Get-ImageDataUrl -Path $msg.payload.path) }
            }
            'get-psadt-stock-assets' {
              try {
                $bannerPath = Join-Path $PSADTCacheDir 'PSAppDeployToolkit\Assets\Banner.Classic.png'
                $iconPath   = Join-Path $PSADTCacheDir 'PSAppDeployToolkit\Assets\AppIcon.png'
                if ((Test-Path $bannerPath) -and (Test-Path $iconPath)) {
                  Send-ToPage $wv 'psadt-stock-assets' @{ ok = $true; banner = (Get-ImageDataUrl -Path $bannerPath); icon = (Get-ImageDataUrl -Path $iconPath) }
                } else {
                  Send-ToPage $wv 'psadt-stock-assets' @{ ok = $false }
                }
              } catch {
                Send-ToPage $wv 'psadt-stock-assets' @{ ok = $false }
              }
            }
            'mark-deployed' {
              $mdManifest = Get-LocalManifest -XmlFile $ManifestPath
              $mdApp = if ($mdManifest.Ok) { $mdManifest.Apps | Where-Object { $_.ID -eq $msg.payload.id } | Select-Object -First 1 } else { $null }
              Set-DeployStatus -AppID $msg.payload.id -AppName $(if ($mdApp) { $mdApp.DisplayName } else { $msg.payload.id }) -MarkDeployed
              Send-ToPage $wv 'fleet-data' (Get-FleetPayload -Config $config)
            }
            'remove-from-fleet' {
              if (Test-OperationActive) {
                throw 'Wait for the active build or test to finish before removing packages.'
              }
              $rmId = $msg.payload.id
              $rmManifest = Get-LocalManifest -XmlFile $ManifestPath
              $rmApp = if ($rmManifest.Ok) { $rmManifest.Apps | Where-Object { $_.ID -eq $rmId } | Select-Object -First 1 } else { $null }
              $rmName = if ($rmApp) { $rmApp.DisplayName } else { $rmId }
              $rmChoice = [string]$msg.payload.mode
              if ($rmChoice -notin @('manifest', 'everything')) {
                Send-ToPage $wv 'remove-from-fleet-result' @{ ok = $false; message = 'Choose what to remove.' }
              } else {
                $rmReport = $null
                if ($rmChoice -eq 'everything') {
                  $rmReport = Remove-AppLocalArtifacts -AppID $rmId -DisplayName $rmName
                }
                try {
                  if (Test-Path -LiteralPath $ManifestPath) {
                    [xml]$rmXml = Get-Content -LiteralPath $ManifestPath -Raw -Encoding UTF8 -ErrorAction Stop
                    $rmNodes = @($rmXml.AppManifest.App | Where-Object { $_.ID -eq $rmId })
                    foreach ($rmNode in $rmNodes) { $rmXml.AppManifest.RemoveChild($rmNode) | Out-Null }
                    Write-AtomicText -Path $ManifestPath -Text $rmXml.OuterXml
                  }
                  $rmStore = Get-DeployStatusStore
                  if ($rmStore.ContainsKey($rmId)) { $rmStore.Remove($rmId); Save-DeployStatusStore -Store $rmStore }
                  Add-DeployHistoryEvent -AppID $rmId -AppName $rmName -Event ('removed' + $(if ($rmChoice -eq 'everything') { ' (+ local cleanup)' } else { '' }))
                  Send-ToPage $wv 'remove-from-fleet-result' @{ ok = $true; everything = ($rmChoice -eq 'everything') }
                } catch {
                  Send-ToPage $wv 'remove-from-fleet-result' @{ ok = $false; message = $_.Exception.Message }
                }
              }
              Send-ToPage $wv 'fleet-data' (Get-FleetPayload -Config $config)
            }
            'test-locally' {
              $store = Get-DeployStatusStore
              $entry = $store[$msg.payload.id]
              if (-not $entry -or -not $entry.outputDir -or -not (Test-Path $entry.outputDir)) {
                Send-ToPage $wv 'test-log' @{ line = 'No output folder on record for this app - rebuild it first.'; done = $true; ok = $false }
              } else {
                Start-LocalTestJob -Wv $wv -AppID $msg.payload.id -OutputDir $entry.outputDir -Target $entry.target -AlsoUninstall:([bool]$msg.payload.alsoUninstall) -SimulateSystem:([bool]$msg.payload.simulateSystem)
              }
            }
            'get-settings' {
              Send-ToPage $wv 'settings-data' @{
                orgName = $config.OrgName
                reduceMotion = [bool]$config.ReduceMotion
                highContrast = [bool]$config.HighContrast
                colorblindSafe = [bool]$config.ColorblindSafe
                releaseCheckEnabled = -not [bool]$config.DisableReleaseCheck
                nvdEnabled = [bool]$config.NvdLookups
                showCloudflareAdvert = -not [bool]$config.HideCloudflareAdvert
                showGettingStarted = -not [bool]$config.HideGettingStarted
                showCloudflareNav = -not [bool]$config.HideCloudflareNav
                onboardingSeen = [bool]$config.OnboardingSeen
                intuneSuggested = [bool]$config.IntuneSuggested
                intuneWrite = [bool]$config.IntuneWriteEnabled
                modeExplainerSeen = [bool]$config.ModeExplainerSeen
                version = $global:Version
                newerAvailable = [bool]($global:_relCheck -and $global:_relCheck.Newer -and $global:_relCheck.Latest)
                latestVersion = if ($global:_relCheck) { $global:_relCheck.Latest } else { '' }
                releaseInfo = if ($global:_relCheck -and $global:_relCheck.Newer -and $global:_relCheck.Latest) {
                  "Update available: v$($global:_relCheck.Latest) on GitHub"
                } elseif ($global:_relCheck -and $global:_relCheck.Latest) {
                  "Up to date (latest release: v$($global:_relCheck.Latest))"
                } else { 'Release check pending or offline.' }
              }
            }
            'save-settings' {
              $config.OrgName = $msg.payload.orgName
              $config.ReduceMotion = [bool]$msg.payload.reduceMotion
              $global:ReduceMotion = $config.ReduceMotion
              $config.HighContrast = [bool]$msg.payload.highContrast
              $config.ColorblindSafe = [bool]$msg.payload.colorblindSafe
              $config.DisableReleaseCheck = -not [bool]$msg.payload.releaseCheckEnabled
              $config.NvdLookups = [bool]$msg.payload.nvdEnabled
              $config.HideCloudflareAdvert = -not [bool]$msg.payload.showCloudflareAdvert
              $config.HideGettingStarted = -not [bool]$msg.payload.showGettingStarted
              $config.HideCloudflareNav = -not [bool]$msg.payload.showCloudflareNav
              $ok = Save-PersistedConfig -Config $config
              Send-ToPage $wv 'settings-saved' @{ ok = $ok }
              Send-ToPage $wv 'fleet-data' (Get-FleetPayload -Config $config)
            }
            'dismiss-cloudflare-advert' {
              $config.HideCloudflareAdvert = $true
              [void](Save-PersistedConfig -Config $config)
            }
            'dismiss-getting-started' {
              $config.HideGettingStarted = $true
              [void](Save-PersistedConfig -Config $config)
            }
            'mark-intune-suggested' {
              $config.IntuneSuggested = $true
              [void](Save-PersistedConfig -Config $config)
            }
            'mark-onboarding-seen' {
              $config.OnboardingSeen = $true
              [void](Save-PersistedConfig -Config $config)
            }
            'reset-onboarding' {
              $config.OnboardingSeen = $false
              $config.ModeExplainerSeen = $false
              [void](Save-PersistedConfig -Config $config)
            }
            'client-error' {
              Write-AppLog "Client-side JS error: $($msg.payload.message) at $($msg.payload.source)`n$($msg.payload.stack)" ERROR
            }
            'open-folder' {
              switch ($msg.payload.which) {
                'output' { try { Start-Process explorer.exe $global:OutputBase } catch { } }
                'build'  {
                  # Only a folder this session built, never a path from the page.
                  $dir = [string]$global:LastBuildDir
                  try { if ($dir -and (Test-Path -LiteralPath $dir -PathType Container)) { Start-Process explorer.exe $dir } else { Start-Process explorer.exe $global:OutputBase } } catch { }
                }
                'app'    {
                  # The folder on record for that app, never a path from the page.
                  $entry = (Get-DeployStatusStore)[[string]$msg.payload.id]
                  try { if ($entry -and $entry.outputDir -and (Test-Path -LiteralPath $entry.outputDir -PathType Container)) { Start-Process explorer.exe $entry.outputDir } else { Start-Process explorer.exe $global:OutputBase } } catch { }
                }
                'cache'  { try { Start-Process explorer.exe $PSADTCacheDir } catch { } }
                'log'    { try { Start-Process notepad.exe $global:LogFile } catch { } }
              }
            }
            'open-github-releases' {
              try { Start-Process 'https://github.com/Lyvvy-xyz/Appupdater/releases' } catch { }
            }
            'drag-window' {
              try {
                $hwnd = (New-Object System.Windows.Interop.WindowInteropHelper($window)).Handle
                [AppUpdater.Win32Drag]::ReleaseCapture() | Out-Null
                [AppUpdater.Win32Drag]::SendMessage($hwnd, 0xA1, 0x2, 0) | Out-Null   # WM_NCLBUTTONDOWN, HTCAPTION
              } catch { }
            }
            'minimize-window' {
              $window.WindowState = 'Minimized'
            }
            'close-window' {
              $window.Close()
            }
            'export-recovery-bundle' {
              $pass = [string]$msg.payload.passphrase
              if ($pass.Length -lt 8) { Send-ToPage $wv 'recovery-export-result' @{ ok = $false; message = 'Use a passphrase of at least 8 characters.' } }
              else {
                $pw = [Net.NetworkCredential]::new('', $pass).SecurePassword; $pass = $null
                $sfd = New-Object Microsoft.Win32.SaveFileDialog
                $sfd.Title = 'Save recovery bundle'
                $sfd.FileName = "AppUpdater-recovery-$(Get-Date -Format 'yyyyMMdd').aurb"
                $sfd.Filter = 'AppUpdater recovery bundle (*.aurb)|*.aurb'
                if ($sfd.ShowDialog($window)) {
                  $json = Export-RecoveryState -Config $config
                  $ok = Protect-RecoveryBundle -PlainJson $json -Passphrase $pw -OutFile $sfd.FileName
                  Send-ToPage $wv 'recovery-export-result' @{ ok = $ok; path = $sfd.FileName }
                }
              }
            }
            'import-recovery-bundle' {
              $ofd2 = New-Object Microsoft.Win32.OpenFileDialog
              $ofd2.Title = 'Select recovery bundle'
              $ofd2.Filter = 'AppUpdater recovery bundle (*.aurb)|*.aurb|All files (*.*)|*.*'
              $pass2 = [string]$msg.payload.passphrase
              if (-not $pass2) { Send-ToPage $wv 'recovery-import-result' @{ ok = $false; message = 'Enter the bundle passphrase.' } }
              elseif ($ofd2.ShowDialog($window)) {
                $pw2 = [Net.NetworkCredential]::new('', $pass2).SecurePassword; $pass2 = $null
                if ($pw2) {
                  try {
                    $json2 = Unprotect-RecoveryBundle -InFile $ofd2.FileName -Passphrase $pw2
                    $newCfg = Import-RecoveryState -StateJson $json2
                    # Later saves write $config back, so it must hold the restored values.
                    $config.Clear(); foreach ($key in @($newCfg.Keys)) { $config[$key] = $newCfg[$key] }
                    Send-ToPage $wv 'recovery-import-result' @{ ok = $true }
                    Send-ToPage $wv 'config-data' @{ orgName = $config.OrgName }
                    Send-ToPage $wv 'fleet-data' (Get-FleetPayload -Config $config)
                  } catch {
                    Send-ToPage $wv 'recovery-import-result' @{ ok = $false; message = $_.Exception.Message }
                  }
                }
              }
            }
            default {
              throw "Unknown application action: $($msg.action)"
            }
          }
        } catch {
          Send-ToPage $wv 'error' @{ message = $_.Exception.Message }
        }
      }.GetNewClosure())
  $wv.CoreWebView2.NavigateToString($__UiHtml)
} catch {
  $__err = $_.Exception
  $__detail = if ($__err.InnerException) { "$($__err.Message)`n`nInner: $($__err.InnerException.Message)" } else { $__err.ToString() }
  [System.Windows.MessageBox]::Show(
    "The app window failed to start up.`n`n$__detail",
    'AppUpdater - startup error', 'OK', 'Error'
  ) | Out-Null
  $window.Close()
}
})

function Test-OperationActive {
  return (($script:ActiveBuild -and -not $script:ActiveBuild.Finished) -or ($script:ActiveTest -and -not $script:ActiveTest.Finished))
}

function Start-LocalTestJob {
  param($Wv, [string]$AppID, [string]$OutputDir, [string]$Target, [switch]$AlsoUninstall, [switch]$SimulateSystem)

  if ($script:ActiveTest -and -not $script:ActiveTest.Finished) { throw 'A local test is already running.' }
  if ($script:ActiveBuild -and -not $script:ActiveBuild.Finished) { throw 'Wait for the package build to finish before testing.' }

  $tq = [System.Collections.Queue]::Synchronized((New-Object System.Collections.Queue))
  $td = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))

  $rs = [runspacefactory]::CreateRunspace()
  $ps = $null
  try {
  $rs.Open()
  $rs.SessionStateProxy.SetVariable('_tq', $tq)
  $rs.SessionStateProxy.SetVariable('_td', $td)
  $rs.SessionStateProxy.SetVariable('_out', $OutputDir)
  $rs.SessionStateProxy.SetVariable('_appId', $AppID)
  $rs.SessionStateProxy.SetVariable('_target', $Target)
  $rs.SessionStateProxy.SetVariable('_alsoUninstall', [bool]$AlsoUninstall)
  $rs.SessionStateProxy.SetVariable('_simulateSystem', [bool]$SimulateSystem)
  $rs.SessionStateProxy.SetVariable('_epmFn', "function Write-EpmRules {`n$((Get-Item Function:\Write-EpmRules).ScriptBlock)`n}")

  $ps = [powershell]::Create()
  $ps.Runspace = $rs
  [void]$ps.AddScript({
    $ErrorActionPreference = 'Stop'
    function Log($m) { if ($_tq.Count -lt 2000) { $_tq.Enqueue($m) } }
    # $_runAs (@{ User; Password }) runs the scripts as that standard user, as Intune's User install behaviour does;
    # its files go under ProgramData because the user cannot read this account's temp folder.
    $tmpBase = if ($_runAs) { [IO.Directory]::CreateDirectory((Join-Path $env:ProgramData 'AppUpdaterTest')).FullName } else { [System.IO.Path]::GetTempPath() }
    $runAsLabel = if ($_runAs) { $_runAs.User } else { 'SYSTEM' }
    function RunAndLog($exe, $argsList, $label) {
      Log "> $label"
      if ($_simulateSystem -or $_runAs) {
        return Invoke-AsSystemViaTask $exe $argsList $label
      }
      try {
        $p = Start-Process -FilePath $exe -ArgumentList $argsList -PassThru -NoNewWindow
        # Reading Handle keeps ExitCode available after the process exits.
        $null = $p.Handle
        if (-not $p.WaitForExit(600000)) { throw "$label timed out after 10 minutes." }
        $p.Refresh()
        Log "  exit code $($p.ExitCode)"
        return $p.ExitCode
      } finally {
        if ($p) { if (-not $p.HasExited) { $p.Kill() }; $p.Dispose() }
      }
    }
    function RunScriptAndLog($path, $argStr, $label) {
      if (-not (Test-Path -LiteralPath $path)) { throw "Required script missing: $([System.IO.Path]::GetFileName($path))" }
      return RunAndLog 'powershell.exe' "-NoProfile -ExecutionPolicy Bypass -File `"$path`" $argStr" $label
    }

    function Invoke-AsSystemViaTask($exe, $argsList, $label) {
      $taskName = "AppUpdaterLocalTest_$([guid]::NewGuid().ToString('N').Substring(0,8))"
      $outFile = Join-Path $tmpBase "$taskName.out.txt"
      $startedFile = "$outFile.started"
      $resultFile = "$outFile.exit"
      $wrapped = "[IO.File]::WriteAllText('$($startedFile.Replace("'","''"))', 'started'); & '$($exe.Replace("'","''"))' $argsList > '$($outFile.Replace("'","''"))' 2>&1; [IO.File]::WriteAllText('$($resultFile.Replace("'","''"))', [string]`$LASTEXITCODE); exit `$LASTEXITCODE"
      $encodedCommand = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($wrapped))
      $action = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument "-NoProfile -WindowStyle Hidden -EncodedCommand $encodedCommand"
      try {
        if ($_runAs) {
          Register-ScheduledTask -TaskName $taskName -Action $action -User $_runAs.User -Password $_runAs.Password -RunLevel Limited -Force -ErrorAction Stop | Out-Null
        } else {
          $principal = New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest
          Register-ScheduledTask -TaskName $taskName -Action $action -Principal $principal -Force -ErrorAction Stop | Out-Null
        }
        Start-ScheduledTask -TaskName $taskName
        $waited = 0
        do { Start-Sleep -Milliseconds 500; $waited += 500 }
        while (-not (Test-Path -LiteralPath $resultFile) -and $waited -lt 600000)
        if (-not (Test-Path -LiteralPath $resultFile)) { throw "$label did not complete within 10 minutes." }
        $exitCode = [int](Get-Content -LiteralPath $resultFile -Raw -ErrorAction Stop)
        if (Test-Path $outFile) { (Get-Content $outFile -Raw) -split "`n" | Where-Object { $_.Trim() } | ForEach-Object { Log "    [$runAsLabel] $_" } }
        Log "  exit code $exitCode (ran as $runAsLabel)"
        return $exitCode
      } catch {
        Log "  FAILED to run as $($runAsLabel): $($_.Exception.Message)"
        return -1
      } finally {
        Stop-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue
        Unregister-ScheduledTask -TaskName $taskName -Confirm:$false -ErrorAction SilentlyContinue
        Remove-Item -LiteralPath $outFile, $startedFile, $resultFile -Force -ErrorAction SilentlyContinue
      }
    }

    function Expand-IntuneWinForTest($IntuneWinPath, $DestDir) {
      Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
      $outerDir = Join-Path ([System.IO.Path]::GetTempPath()) "iwt_outer_$([guid]::NewGuid())"
      $tmpZip = Join-Path ([System.IO.Path]::GetTempPath()) "iwt_content_$([guid]::NewGuid()).zip"
      $inputStream = $outputStream = $cryptoStream = $decryptor = $aes = $reader = $null
      try {
        [System.IO.Compression.ZipFile]::ExtractToDirectory($IntuneWinPath, $outerDir)
        $detXml = Join-Path $outerDir 'IntuneWinPackage\Metadata\Detection.xml'
        if (-not (Test-Path -LiteralPath $detXml)) { throw 'Not a recognized .intunewin file (Detection.xml missing).' }
        [xml]$xml = Get-Content -LiteralPath $detXml -Raw
        $encInfo = $xml.ApplicationInfo.EncryptionInfo
        $encFile = Get-ChildItem (Join-Path $outerDir 'IntuneWinPackage\Contents') -File -ErrorAction Stop | Select-Object -First 1
        $inputStream = [IO.File]::OpenRead($encFile.FullName)
        $reader = [IO.BinaryReader]::new($inputStream)
        $header = $reader.ReadBytes(48)
        if ($header.Length -ne 48 -or $inputStream.Length -le 48) { throw 'Encrypted package is truncated.' }
        $iv = New-Object byte[] 16
        [Array]::Copy($header, 32, $iv, 0, 16)
        $aes = [Security.Cryptography.Aes]::Create()
        $aes.Mode = 'CBC'; $aes.Key = [Convert]::FromBase64String($encInfo.EncryptionKey); $aes.IV = $iv
        $decryptor = $aes.CreateDecryptor()
        $cryptoStream = [Security.Cryptography.CryptoStream]::new($inputStream, $decryptor, [Security.Cryptography.CryptoStreamMode]::Read)
        $outputStream = [IO.File]::Create($tmpZip)
        $cryptoStream.CopyTo($outputStream, 81920)
        $outputStream.Dispose(); $outputStream = $null
        [System.IO.Compression.ZipFile]::ExtractToDirectory($tmpZip, $DestDir)
      } finally {
        foreach ($resource in @($outputStream, $cryptoStream, $decryptor, $reader, $inputStream, $aes)) {
          if ($resource) { $resource.Dispose() }
        }
        Remove-Item -LiteralPath $outerDir -Recurse -Force -ErrorAction SilentlyContinue
        Remove-Item -LiteralPath $tmpZip -Force -ErrorAction SilentlyContinue
      }
    }

    function Get-ArpSnapshot {
      $roots = @('Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall',
                 'Registry::HKEY_LOCAL_MACHINE\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall')
      # S-1-5-18 is SYSTEM's own profile, where per-user installers land when Intune runs them.
      foreach ($hive in @(Get-ChildItem 'Registry::HKEY_USERS' -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^S-1-5-(18|21-[\d-]+)$' })) {
        $roots += "Registry::HKEY_USERS\$($hive.PSChildName)\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"
      }
      $snapshot = @{}
      foreach ($key in @(Get-ChildItem -Path $roots -ErrorAction SilentlyContinue)) {
        $entry = Get-ItemProperty -LiteralPath $key.PSPath -ErrorAction SilentlyContinue
        if ($entry.DisplayName) { $snapshot[$key.Name] = $entry }
      }
      return $snapshot
    }
    function Write-ArpChanges($Before, $After) {
      $changed = @($After.Keys | Where-Object { -not $Before.ContainsKey($_) -or [string]$Before[$_].DisplayVersion -ne [string]$After[$_].DisplayVersion })
      if (-not $changed.Count) { Log '  Add/Remove Programs: no new or changed entry. The app may not register itself, or the installer did nothing.'; return }
      foreach ($name in $changed) {
        $entry = $After[$name]
        $scope = if ($name -match '^HKEY_USERS\\S-1-5-18\\') { "SYSTEM's profile only" } elseif ($name -match '^HKEY_USERS\\') { 'one user only' } else { 'all users' }
        Log "  Add/Remove Programs: '$($entry.DisplayName)' version '$($entry.DisplayVersion)' - installed for $scope$(if ($entry.QuietUninstallString) { ', has a silent uninstall command' })"
      }
      if (@($changed | Where-Object { $_ -match '^HKEY_USERS\\' }).Count) {
        Log "  WARNING: per-user installer. Deploy it with Intune install behaviour User; run as SYSTEM it only reaches SYSTEM's own profile."
      }
      Log "  Detection matches the 'Registry display name' field; set it to the name above if they differ, then rebuild."
      return @($changed | ForEach-Object { [string]$After[$_].DisplayName })
    }
    function Get-DetectTarget($DetectPath) {
      return [regex]::Match([IO.File]::ReadAllText($DetectPath), "Find-ARPEntry -Target '((?:[^']|'')*)'").Groups[1].Value.Replace("''", "'")
    }
    function Get-RegistrySuggestion($Names, $DetectPath, $Target) {
      # The entry the install added that best fits the name detection, or the Runtime agent, looks for.
      $target = if ($Target) { $Target } else { Get-DetectTarget $DetectPath }
      $wanted = ($target -replace '[^A-Za-z0-9]', '').ToLowerInvariant()
      $fits = @($Names | Where-Object { $n = ($_ -replace '[^A-Za-z0-9]', '').ToLowerInvariant(); $wanted -and $n -and ($n.Contains($wanted) -or $wanted.Contains($n)) })
      if ($fits.Count -eq 1) { return $fits[0] }
      $apps = @($Names | Where-Object { $_ -notmatch 'maintenance|updater?\b|helper|runtime|redistributable' })
      if ($apps.Count -eq 1) { return $apps[0] }
      return ''
    }
    function Get-RegisteredEntry($Snapshot, $DetectPath, $Target) {
      # The Add/Remove Programs entry for the registry name, in Find-ARPEntry's order: exact, normalized, normalized prefix.
      $target = if ($Target) { $Target } else { Get-DetectTarget $DetectPath }
      $norm = { param($n) ([string]$n -replace '[^\p{L}\p{N}]', '').ToLowerInvariant() }
      $wanted = & $norm $target
      if (-not $wanted) { return $null }
      $entries = @($Snapshot.Values)
      return @(@($entries | Where-Object { $_.DisplayName -eq $target }) + @($entries | Where-Object { (& $norm $_.DisplayName) -eq $wanted }) +
        @($entries | Where-Object { $n = & $norm $_.DisplayName; $n -and ($n.StartsWith($wanted) -or $wanted.StartsWith($n)) })) | Select-Object -First 1
    }
    function Complete-InstalledCheck($Snapshot, $DetectPath, $Target) {
      # Offers the registered version as detection's minimum when detect.ps1 has none, and adds the app's updaters to the EPM rules.
      $entry = Get-RegisteredEntry $Snapshot $DetectPath $Target
      if (-not $entry) { return }
      $script:registeredEntry = @{ DisplayName = [string]$entry.DisplayName; DisplayVersion = ([string]$entry.DisplayVersion).Trim()
                                   Publisher = [string]$entry.Publisher; ProductCode = [string]$entry.PSChildName }
      if ([IO.File]::ReadAllText($DetectPath) -match "(?m)^\`$minimum = ''" -and [string]$entry.DisplayVersion -match '\d') { $script:registeredVersion = ([string]$entry.DisplayVersion).Trim() }
      $location = ([string]$entry.InstallLocation).Trim().Trim('"')
      if ($_epmFn -and $location -and (Test-Path -LiteralPath $location -PathType Container)) {
        . ([scriptblock]::Create($_epmFn))
        $exes = @(Get-ChildItem -LiteralPath $location -Filter '*.exe' -File -Recurse -Depth 3 -ErrorAction SilentlyContinue)
        $updaters = @($exes | Where-Object { $_.FullName.Substring($location.Length) -match '(?i)update|upgrade|maintenance|\\gup\.exe$' } | Select-Object -First 10)
        # The main program: the largest executable in the install folder itself that is not a helper.
        $main = @($exes | Where-Object { $_.DirectoryName.TrimEnd('\') -eq $location.TrimEnd('\') -and $_.Name -notmatch '(?i)unins|uninstall|setup|update|helper|crash|report|redist' } |
          Sort-Object Length -Descending | Select-Object -First 1)
        if ($main.Count) { Write-EpmRules -Paths @($main.FullName) -OutputDir $_out -Role 'app' | Out-Null }
        if ($updaters.Count) { Write-EpmRules -Paths @($updaters.FullName) -OutputDir $_out -Role 'updater' | Out-Null }
        if ($main.Count -or $updaters.Count) { Log "  EPM: added $(@($main + $updaters).Count) installed file(s) from $location to EPM-rules.csv: $(@(@($main + $updaters).Name) -join ', ')" }
      }
    }
    $script:suggestion = ''
    $script:registeredVersion = ''
    $script:registeredEntry = $null
    function Stop-OnDetectionFailure($Code, $Names, $DetectPath, $Snapshot) {
      $script:suggestion = Get-RegistrySuggestion $Names $DetectPath
      if ($script:suggestion) { Log "  Suggested registry display name: '$($script:suggestion)'" }
      # Found but below the minimum: the app numbers its versions differently from the installer.
      $minimum = [regex]::Match([IO.File]::ReadAllText($DetectPath), "(?m)^\`$minimum = '([^']*)'").Groups[1].Value
      $entry = if ($minimum -and $Snapshot) { Get-RegisteredEntry $Snapshot $DetectPath }
      if ($entry -and [string]$entry.DisplayVersion -match '\d' -and ([string]$entry.DisplayVersion).Trim() -ne $minimum) {
        $script:registeredVersion = ([string]$entry.DisplayVersion).Trim()
        Log "  The app registered version '$($script:registeredVersion)', which does not meet the minimum '$minimum'. It numbers versions differently from the installer; use '$($script:registeredVersion)' as the minimum."
      }
      throw "Post-install detection failed with exit code $Code."
    }

    try {
      $intuneWinFile = Get-ChildItem $_out -Filter '*.intunewin' -ErrorAction SilentlyContinue | Select-Object -First 1
      $testDir = $_out
      if ($intuneWinFile) {
        Log "Found $($intuneWinFile.Name) - decrypting and extracting for a real test..."
        $testDir = Join-Path $tmpBase "iwt_extracted_$([guid]::NewGuid())"
        try {
          Expand-IntuneWinForTest $intuneWinFile.FullName $testDir
          Log "  Decrypted OK -> testing the actual packaged contents"
        } catch {
          throw "Could not validate the packaged artifact: $($_.Exception.Message)"
        }
      } else {
        Log 'No .intunewin file found in the output folder - testing the loose scripts instead.'
      }

      # Runtime packages carry detection as an Intune sidecar; require it before installing.
      $detect = $null
      foreach ($candidateDir in @($testDir, $_out, (Join-Path (Split-Path $_out -Parent) $_appId))) {
        foreach ($candidateName in @('detect.ps1', "Detect-$_appId.ps1")) {
          $candidate = Join-Path $candidateDir $candidateName
          if (Test-Path -LiteralPath $candidate -PathType Leaf) { $detect = Get-Item -LiteralPath $candidate; break }
        }
        if ($detect) { break }
      }
      if (-not $detect) { throw 'No detection script found; the installation test cannot be verified.' }
      if ($_target -eq 'psadt' -or $_target -eq 'psadt-v3' -or $_target -eq 'psadt-v4' -or $_target -eq 'both') {
        $deployApp = Join-Path $testDir 'Deploy-Application.ps1'
        $deployMode = if ($_simulateSystem) { 'Silent' } else { 'Interactive' }
        $arpBefore = Get-ArpSnapshot
        $installExit = RunScriptAndLog $deployApp "-DeploymentType Install -DeployMode $deployMode" "Install (PSADT, $deployMode)"
        $arpAfter = Get-ArpSnapshot
        $arpNew = Write-ArpChanges $arpBefore $arpAfter
        if ($installExit -notin @(0,3010,1641)) { throw "PSADT installation failed with exit code $installExit." }
        $detected = RunScriptAndLog $detect.FullName '' 'Post-install detection'
        if ($detected -ne 0) { Stop-OnDetectionFailure $detected $arpNew $detect.FullName $arpAfter }
        Complete-InstalledCheck $arpAfter $detect.FullName
        if ($_alsoUninstall) {
          $uninstallExit = RunScriptAndLog $deployApp "-DeploymentType Uninstall -DeployMode $deployMode" "Uninstall (PSADT, $deployMode)"
          if ($uninstallExit -notin @(0,3010,1641)) { throw "PSADT uninstall failed with exit code $uninstallExit." }
          $detected = RunScriptAndLog $detect.FullName '' 'Post-uninstall detection'
          if ($detected -ne 1) { throw "Expected not-installed detection exit code 1 after uninstall, got $detected." }
        }
      } else {
        $install = Get-ChildItem $testDir -Filter 'install.ps1' -ErrorAction SilentlyContinue | Select-Object -First 1
        if (-not $install) { $install = Get-ChildItem $testDir -Filter "Deploy-$_appId.ps1" -ErrorAction SilentlyContinue | Select-Object -First 1 }
        $uninstall = Get-ChildItem $testDir -Filter 'uninstall.ps1' -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($_alsoUninstall -and -not $uninstall) { throw 'This output has no uninstall script. Disable the uninstall test or build a package that supports it.' }

        if ($detect) {
          $r0 = RunScriptAndLog $detect.FullName '' 'Pre-check (detect.ps1)'
          Log "  --> $(if ($r0 -eq 0) { 'Already detected as installed' } else { 'Not detected (expected before install)' })"
        }
        if ($install) {
          $arpBefore = Get-ArpSnapshot
          $installExit = RunScriptAndLog $install.FullName '' 'Install'
          $arpAfter = Get-ArpSnapshot
          $arpNew = Write-ArpChanges $arpBefore $arpAfter
          if ($installExit -notin @(0,3010,1641)) { throw "Installation failed with exit code $installExit." }
        } else {
          throw 'No install script found in this output folder.'
        }
        if ($detect) {
          $r1 = RunScriptAndLog $detect.FullName '' 'Post-install check (detect.ps1)'
          if ($r1 -ne 0) { Stop-OnDetectionFailure $r1 $arpNew $detect.FullName $arpAfter }
          $agentTarget = $null
          if ($install.Name -like 'Deploy-*') {
            # Runtime detection only confirms the agent, so check the name the agent itself looks for: a name the app does not
            # register makes the agent reinstall it on every run.
            $agentScript = if ($env:ProgramData) { Join-Path $env:ProgramData "AppUpdater\$_appId\$_appId.ps1" }
            $agentTarget = if ($agentScript -and (Test-Path -LiteralPath $agentScript)) { [regex]::Match([IO.File]::ReadAllText($agentScript), "(?m)^\`$RegistryName\s*=\s*'((?:[^']|'')*)'").Groups[1].Value.Replace("''", "'") }
            if ($agentTarget -and -not (Get-RegisteredEntry $arpAfter $null $agentTarget)) {
              $script:suggestion = Get-RegistrySuggestion $arpNew $null $agentTarget
              Log "  The agent looks for '$agentTarget' in Add/Remove Programs, which the app did not register, so it would reinstall the app on every run."
              if ($script:suggestion) { Log "  Suggested registry display name: '$($script:suggestion)'" }
              throw 'The Runtime agent cannot find the installed app by its registry name.'
            }
          }
          Complete-InstalledCheck $arpAfter $detect.FullName $agentTarget
          Log "  --> $(if ($r1 -eq 0) { 'PASS - detected after install' } else { 'FAIL - NOT detected after install (detection rule or install command is wrong)' })"
        } else { throw 'No detection script found in this output folder.' }
        if ($_alsoUninstall) {
          if (-not $uninstall) { throw 'No uninstall script found; uninstall test cannot run.' }
          $uninstallExit = RunScriptAndLog $uninstall.FullName '' 'Uninstall'
          if ($uninstallExit -notin @(0,3010,1641)) { throw "Uninstall failed with exit code $uninstallExit." }
          if ($detect) {
            $r2 = RunScriptAndLog $detect.FullName '' 'Post-uninstall check (detect.ps1)'
            if ($r2 -ne 1) { throw "Expected not-installed detection exit code 1 after uninstall, got $r2." }
            Log "  --> $(if ($r2 -ne 0) { 'PASS - no longer detected' } else { 'FAIL - still detected after uninstall' })"
          }
        }
      }
      if ($script:registeredVersion) { Log "  Detection accepts any version. The app registered version '$($script:registeredVersion)'; rebuild with it as the minimum version so older copies are upgraded." }
      Log '=== Local test complete ==='
      $_td.Add(@{ ok = $true; suggestedDetectVersion = $script:registeredVersion; registered = $script:registeredEntry }) | Out-Null
    } catch {
      Log "ERROR: $($_.Exception.Message)"
      $_td.Add(@{ ok = $false; suggestedRegistryName = $script:suggestion; suggestedDetectVersion = $script:registeredVersion }) | Out-Null
    } finally {
      if ($testDir -and $testDir -ne $_out) { Remove-Item -LiteralPath $testDir -Recurse -Force -ErrorAction SilentlyContinue }
    }
  })
  $handle = $ps.BeginInvoke()
  } catch {
    if ($ps) { $ps.Dispose() }
    $rs.Dispose()
    throw
  }

  $script:ActiveTest = @{ Finished = $false; Started = [Diagnostics.Stopwatch]::StartNew() }
  $job = $script:ActiveTest

  $timer = New-Object System.Windows.Threading.DispatcherTimer
  $timer.Interval = [TimeSpan]::FromMilliseconds(150)
  $timer.Add_Tick({
    for ($i = 0; $i -lt 100 -and $tq.Count -gt 0; $i++) { Send-ToPage $Wv 'test-log' @{ line = $tq.Dequeue(); done = $false } }
    if ($job.Started.Elapsed.TotalMinutes -gt 40 -and -not $handle.IsCompleted -and -not $job.StopHandle) { $job.StopHandle = $ps.BeginStop($null, $null) }
    if ($handle.IsCompleted -and $tq.Count -eq 0) {
      $timer.Stop()
      try {
        $ps.EndInvoke($handle) | Out-Null
        if ($td.Count -ne 1) { throw 'Local test ended without a result.' }
        $wingetOffer = $false
        if ($td[0].ok -and $td[0].registered) {
          try { $wingetOffer = [bool](Set-AppMemoryTestResult -AppID $AppID -Registered $td[0].registered) } catch { Write-AppLog "Could not record the test result: $($_.Exception.Message)" WARN }
        }
        Send-ToPage $Wv 'test-log' @{ line = ''; done = $true; ok = $td[0].ok; suggestedRegistryName = [string]$td[0].suggestedRegistryName; suggestedDetectVersion = [string]$td[0].suggestedDetectVersion; wingetOffer = $wingetOffer }
      } catch { Send-ToPage $Wv 'test-log' @{ line = $_.Exception.Message; done = $true; ok = $false } }
      finally { $ps.Dispose(); $rs.Dispose(); $job.Finished = $true }
    }
  }.GetNewClosure())
  $timer.Start()
}

function Start-WingetLookupJob {
  # Background half of installer inspection: counts the files beside the installer and, unless outbound lookups are off, asks winget.
  param($Wv, [string]$InstallerPath, [hashtable]$Inspection, [bool]$UseWinget = $true)
  $functions = foreach ($name in @('Find-WingetInstaller','Invoke-WingetQuery','Get-WingetManifestPath','ConvertFrom-SimpleYaml',
                                   'Select-WingetInstallerEntry','ConvertTo-WingetSilentArgs','ConvertTo-WingetNormalName','ConvertTo-LooseVersion',
                                   'Get-InstallerFolderInfo','Test-SafeHttpsUrl')) {
    "function $name {`n$((Get-Item "Function:\$name").ScriptBlock)`n}"
  }
  if ($UseWinget -and -not ((Test-Path -LiteralPath (Join-Path $WingetCacheDir 'index.db')) -and (Test-Path -LiteralPath (Join-Path $KevCacheDir 'kev.json')))) { Start-WingetIndexRefresh }
  $result = [hashtable]::Synchronized(@{})
  $rs = [runspacefactory]::CreateRunspace()
  $ps = $null
  try {
    $rs.Open()
    foreach ($vn in @('WingetCacheDir','WingetCacheURL')) { $rs.SessionStateProxy.SetVariable($vn, (Get-Variable $vn -ValueOnly -Scope Script)) }
    $rs.SessionStateProxy.SetVariable('WingetSqliteSource', $global:WingetSqliteSource)
    $rs.SessionStateProxy.SetVariable('_result', $result)
    $rs.SessionStateProxy.SetVariable('_path', $InstallerPath)
    $rs.SessionStateProxy.SetVariable('_inspection', $Inspection)
    $rs.SessionStateProxy.SetVariable('_useWinget', $UseWinget)
    $ps = [powershell]::Create()
    $ps.Runspace = $rs
    [void]$ps.AddScript(($functions -join "`n") + "`n" + {
      $global:WingetSqliteSource = $WingetSqliteSource
      try {
        $f = Get-InstallerFolderInfo -InstallerPath $_path
        $_result.folder = @{ files = $f.Files; bytes = $f.Bytes; isRoot = $f.IsRoot; tooMany = $f.TooMany }
      } catch { $_result.folder = @{ files = 0; bytes = 0; isRoot = $false; tooMany = $true } }
      try {
        if (-not $_useWinget) { $_result.note = 'winget lookups are off (Settings > online lookups)'; return }
        if (-not (Test-Path -LiteralPath (Join-Path $WingetCacheDir 'index.db'))) { $_result.note = 'winget catalogue still downloading - switches are from file inspection'; return }
        $match = Find-WingetInstaller -InstallerPath $_path -ProductCode $_inspection.ProductCode -Name $_inspection.DisplayName `
          -Publisher $_inspection.Publisher -Version $_inspection.Version
        if ($match) { $_result.match = $match } else { $_result.note = 'not in the winget catalogue - switches are from file inspection' }
      } catch { $_result.note = "winget lookup failed: $($_.Exception.Message)" }
    }.ToString())
    $handle = $ps.BeginInvoke()
  } catch {
    if ($ps) { $ps.Dispose() }
    $rs.Dispose()
    Write-AppLog "winget lookup could not start: $($_.Exception.Message)" WARN
    Send-ToPage $Wv 'installer-winget-result' @{ path = $InstallerPath; match = $null; note = 'winget lookup could not start - switches are from file inspection'
                                                 folder = @{ files = 0; bytes = 0; isRoot = $false; tooMany = $true } }
    return
  }
  $started = [Diagnostics.Stopwatch]::StartNew()
  $timer = New-Object System.Windows.Threading.DispatcherTimer
  $timer.Interval = [TimeSpan]::FromMilliseconds(250)
  $state = @{ Sent = $false }
  $timer.Add_Tick({
    if (-not $state.Sent) {
      if (-not $handle.IsCompleted -and $started.Elapsed.TotalSeconds -lt 60) { return }
      if (-not $handle.IsCompleted) { $result.note = 'winget lookup timed out - switches are from file inspection'; $ps.BeginStop($null, $null) | Out-Null }
      else { try { $ps.EndInvoke($handle) | Out-Null } catch { $result.note = "winget lookup failed: $($_.Exception.Message)" } }
      $known = if ($result.match -and $result.match.Id) { try { Find-KnownApp -WingetId $result.match.Id } catch { $null } } else { $null }
      Send-ToPage $Wv 'installer-winget-result' @{ path = $InstallerPath; match = $result.match; note = [string]$result.note; folder = $result.folder; known = $known }
      $state.Sent = $true
    }
    # A timed-out lookup keeps ticking until its pipeline has stopped, then releases the runspace.
    if ($ps.InvocationStateInfo.State -notin 'NotStarted', 'Running', 'Stopping') { $timer.Stop(); $ps.Dispose(); $rs.Dispose() }
  }.GetNewClosure())
  $timer.Start()
}

# OAuth app used for the GitHub device sign-in. A client ID is public; device flow needs no secret.
$GitHubClientId = ''
$MsGraphClientId = '14d82eec-204b-4c2f-b7e8-296a70dab67e'
# Reading only; writing is added when the user switches it on in Settings (DeviceManagementConfiguration.ReadWrite.All).
$IntuneScopes = 'https://graph.microsoft.com/DeviceManagementConfiguration.Read.All https://graph.microsoft.com/Group.Read.All'
$IntuneAuth = @{}
$AzureAuth = @{}
$EpmCheckScript = @'
# Finds new vendor releases (detect, Linux) and verifies them (verify, Windows): download to the runner,
# Authenticode signer check, SHA-256, winget comparison. Only version, hash and signer leave the runner.
param([ValidateSet('detect', 'verify')][string]$Mode = 'detect')
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
$worker = ([string]$env:WORKER_URL).TrimEnd('/')
$gh = @{ 'User-Agent' = 'appupdater-checks' }
if ($env:GH_TOKEN) { $gh.Authorization = "Bearer $env:GH_TOKEN" }

function Get-WorkerHeaders {
  $aud = ([uri]$worker).GetLeftPart('Authority')
  $tok = (Invoke-RestMethod "$env:ACTIONS_ID_TOKEN_REQUEST_URL&audience=$([uri]::EscapeDataString($aud))" -Headers @{ Authorization = "Bearer $env:ACTIONS_ID_TOKEN_REQUEST_TOKEN" }).value
  @{ Authorization = "Bearer $tok" }
}

function Compare-Version([string]$A, [string]$B) {
  $pa = @([regex]::Matches($A, '\d+') | ForEach-Object { [long]$_.Value })
  $pb = @([regex]::Matches($B, '\d+') | ForEach-Object { [long]$_.Value })
  for ($i = 0; $i -lt [Math]::Max($pa.Count, $pb.Count); $i++) {
    $x = if ($i -lt $pa.Count) { $pa[$i] } else { 0 }
    $y = if ($i -lt $pb.Count) { $pb[$i] } else { 0 }
    if ($x -ne $y) { return [Math]::Sign($x - $y) }
  }
  0
}

function Resolve-Latest($App) {
  $src = $App.source
  switch ($src.type) {
    'github' {
      $rel = Invoke-RestMethod "https://api.github.com/repos/$($src.repo)/releases/latest" -Headers $gh
      $pattern = if ($src.asset) { $src.asset } else { '(?i)\.(exe|msi)$' }
      $assets = @($rel.assets | Where-Object { $_.name -match $pattern })
      $pick = @($assets | Where-Object { $_.name -match '(?i)x64|amd64|win64' }) + $assets | Select-Object -First 1
      if (-not $pick) { throw "No release file matches $pattern in $($rel.tag_name)." }
      $version = if ($src.versionRegex) { [regex]::Match($rel.tag_name, $src.versionRegex).Groups[1].Value } else { [regex]::Match($rel.tag_name, '\d+(\.\d+)*').Value }
      return @{ version = $version; url = $pick.browser_download_url; file = $pick.name }
    }
    'redirect' {
      $client = [Net.Http.HttpClient]::new()
      $client.DefaultRequestHeaders.UserAgent.ParseAdd('Mozilla/5.0 appupdater-checks')
      try {
        $resp = $client.GetAsync([string]$src.url, [Net.Http.HttpCompletionOption]::ResponseHeadersRead).GetAwaiter().GetResult()
        [void]$resp.EnsureSuccessStatusCode()
        $final = $resp.RequestMessage.RequestUri
        if ($final.Scheme -ne 'https') { throw "The link redirects to $($final.Scheme), not https." }
        $file = $resp.Content.Headers.ContentDisposition.FileNameStar, $resp.Content.Headers.ContentDisposition.FileName, [uri]::UnescapeDataString($final.Segments[-1]) | Where-Object { $_ } | Select-Object -First 1
        $file = ([string]$file).Trim('"')
      } finally { $client.Dispose() }
      $rx = if ($src.versionRegex) { $src.versionRegex } else { '(\d+(?:\.\d+)+)' }
      $version = [regex]::Match($file, $rx).Groups[1].Value
      if (-not $version) { throw "No version in the file name $file." }
      return @{ version = $version; url = $final.AbsoluteUri; file = $file }
    }
    'page' {
      $html = (Invoke-WebRequest ([string]$src.url) -UserAgent 'Mozilla/5.0 appupdater-checks').Content
      $version = [regex]::Match($html, [string]$src.versionRegex).Groups[1].Value
      if (-not $version) { throw 'The version pattern found nothing on the page.' }
      $url = ([string]$src.download).Replace('{version}', $version).Replace('{nodots}', $version.Replace('.', ''))
      return @{ version = $version; url = $url; file = [uri]::UnescapeDataString(([uri]$url).Segments[-1]) }
    }
    default { throw "Unknown source type '$($src.type)'." }
  }
}

function Get-WingetCompare($App, [string]$Version, [string]$Sha256) {
  if (-not $App.winget) { return @{ status = 'not-checked' } }
  $path = 'manifests/' + $App.winget.Substring(0, 1).ToLowerInvariant() + '/' + $App.winget.Replace('.', '/')
  try { $listing = Invoke-RestMethod "https://api.github.com/repos/microsoft/winget-pkgs/contents/$path" -Headers $gh }
  catch { if ($_.Exception.Response.StatusCode -eq 404) { return @{ status = 'missing' } }; throw }
  # Invoke-RestMethod passes a JSON array down the pipeline as one object, so it is unrolled first.
  $dirs = @(@($listing) | ForEach-Object { $_ } | Where-Object { $_.type -eq 'dir' -and $_.name -match '^\d' } | ForEach-Object name)
  if (-not $dirs) { return @{ status = 'missing' } }
  $latest = $dirs[0]; foreach ($d in $dirs) { if ((Compare-Version $d $latest) -gt 0) { $latest = $d } }
  $same = $dirs | Where-Object { (Compare-Version $_ $Version) -eq 0 } | Select-Object -First 1
  if ($same) {
    $yaml = Invoke-RestMethod "https://raw.githubusercontent.com/microsoft/winget-pkgs/master/$path/$same/$($App.winget).installer.yaml" -Headers @{ 'User-Agent' = 'appupdater-checks' }
    $hashes = @([regex]::Matches([string]$yaml, '(?im)^\s*InstallerSha256:\s*([0-9a-f]{64})') | ForEach-Object { $_.Groups[1].Value.ToUpperInvariant() })
    $status = if ($hashes -contains $Sha256) { 'match' } else { 'hash-mismatch' }
    return @{ status = $status; version = $same }
  }
  $status = if ((Compare-Version $Version $latest) -gt 0) { 'vendor-newer' } else { 'winget-newer' }
  @{ status = $status; version = $latest }
}

function Test-EpmRelease($App, $Latest, [string]$TempDir) {
  # Downloads one release, checks its signer and winget hash, and deletes it. Shared with the Azure runbook.
  $r = [ordered]@{ id = $App.id; name = $App.name; version = $Latest.version; file = $Latest.file; url = $Latest.url; at = (Get-Date).ToUniversalTime().ToString('o') }
  $tmp = Join-Path $TempDir ([guid]::NewGuid().ToString('n') + [IO.Path]::GetExtension($Latest.file))
  try {
    Invoke-WebRequest $Latest.url -OutFile $tmp -UserAgent 'Mozilla/5.0 appupdater-checks'
    $r.sha256 = (Get-FileHash $tmp -Algorithm SHA256).Hash
    $sig = Get-AuthenticodeSignature $tmp
    $r.signer = if ($sig.SignerCertificate) { $sig.SignerCertificate.GetNameInfo('SimpleName', $false) } else { '' }
    $r.thumbprint = if ($sig.SignerCertificate) { $sig.SignerCertificate.Thumbprint } else { '' }
    $r.signature = [string]$sig.Status
    $r.winget = Get-WingetCompare $App $Latest.version $r.sha256
    $r.status = 'ok'
    if ($sig.Status -eq 'NotSigned') { $r.status = 'blocked'; $r.reason = 'The installer is not signed.' }
    elseif ($sig.Status -ne 'Valid') { $r.status = 'blocked'; $r.reason = "The signature is $($sig.Status): $($sig.StatusMessage)" }
    elseif ($App.publisher -and $r.signer -ne $App.publisher) { $r.status = 'blocked'; $r.reason = "Signed by '$($r.signer)', not the approved publisher '$($App.publisher)'." }
    elseif ($r.winget.status -eq 'hash-mismatch') { $r.status = 'blocked'; $r.reason = "winget lists $($Latest.version) with a different SHA-256. The vendor file may have been replaced." }
  } catch {
    $r.status = 'error'; $r.reason = $_.Exception.Message
  } finally { Remove-Item $tmp -Force -ErrorAction SilentlyContinue }
  $r
}

function Send-Results($Results) {
  if (-not $Results) { return }
  $body = ConvertTo-Json -Depth 6 -Compress -InputObject @{ results = @($Results) }
  if (-not $worker) { $body; return }
  Invoke-RestMethod "$worker/epm/result" -Method Post -Headers (Get-WorkerHeaders) -ContentType 'application/json' -Body $body | Out-Null
}

if ($Mode -eq 'detect') {
  $state = if ($worker) { Invoke-RestMethod "$worker/epm/apps" -Headers (Get-WorkerHeaders) } else { Get-Content apps.json -Raw | ConvertFrom-Json }
  $todo = @(); $failed = @()
  foreach ($app in @($state.apps)) {
    try {
      $latest = Resolve-Latest $app
      $known = if ($state.known) { [string]$state.known.($app.id) } else { '' }
      if (-not $known -or (Compare-Version $latest.version $known) -gt 0) { $todo += @{ app = $app; latest = $latest } }
      Write-Host "$($app.name): vendor $($latest.version), last verified $(if ($known) { $known } else { 'never' })"
    } catch {
      Write-Host "$($app.name): $($_.Exception.Message)"
      $failed += @{ id = $app.id; name = $app.name; status = 'source-error'; reason = $_.Exception.Message; at = (Get-Date).ToUniversalTime().ToString('o') }
    }
  }
  Send-Results $failed
  $json = ConvertTo-Json -Depth 6 -Compress -InputObject @($todo)
  if ($env:GITHUB_OUTPUT) { "todo=$(if ($todo) { $json } else { '' })" | Add-Content $env:GITHUB_OUTPUT } else { $json }
  return
}

$results = foreach ($item in @($env:TODO | ConvertFrom-Json)) {
  $r = Test-EpmRelease $item.app $item.latest $env:RUNNER_TEMP
  Write-Host "$($item.app.name) $($item.latest.version): $($r.status) $($r.reason)"
  $r
}
Send-Results $results
'@
$EpmWorkflow = @'
name: epm-check
on:
  schedule:
    - cron: '17 */6 * * *'
  workflow_dispatch:
permissions:
  contents: read
  id-token: write
concurrency: epm-check
jobs:
  detect:
    runs-on: ubuntu-latest
    timeout-minutes: 10
    outputs:
      todo: ${{ steps.detect.outputs.todo }}
    steps:
      - uses: actions/checkout@v4
      - id: detect
        shell: pwsh
        run: ./check.ps1 -Mode detect
        env:
          WORKER_URL: ${{ vars.WORKER_URL }}
          GH_TOKEN: ${{ github.token }}
  verify:
    needs: detect
    if: needs.detect.outputs.todo != ''
    runs-on: windows-latest
    timeout-minutes: 30
    steps:
      - uses: actions/checkout@v4
      - shell: pwsh
        run: ./check.ps1 -Mode verify
        env:
          WORKER_URL: ${{ vars.WORKER_URL }}
          GH_TOKEN: ${{ github.token }}
          TODO: ${{ needs.detect.outputs.todo }}
'@

function Invoke-GitHubApi {
  param([string]$Token, [string]$Path, [string]$Method = 'GET', $Body)
  $p = @{ Uri = "https://api.github.com$Path"; Method = $Method; TimeoutSec = 30; ErrorAction = 'Stop'; UseBasicParsing = $true
    Headers = @{ Authorization = "Bearer $Token"; Accept = 'application/vnd.github+json'; 'User-Agent' = 'AppUpdater' } }
  if ($null -ne $Body) { $p.ContentType = 'application/json; charset=utf-8'; $p.Body = [Text.Encoding]::UTF8.GetBytes((ConvertTo-Json -Depth 6 -Compress -InputObject $Body)) }
  Invoke-RestMethod @p
}

function Test-HttpNotFound($ErrorRecord) {
  $resp = $ErrorRecord.Exception.Response
  $resp -and [int]$resp.StatusCode -eq 404
}

function Request-GitHubDeviceCode([string]$ClientId) {
  Invoke-RestMethod -Method Post -Uri 'https://github.com/login/device/code' -Headers @{ Accept = 'application/json' } `
    -Body @{ client_id = $ClientId; scope = 'repo workflow' } -TimeoutSec 20 -UseBasicParsing -ErrorAction Stop
}

function Wait-GitHubDeviceToken([string]$ClientId, [string]$DeviceCode, [int]$Interval, [int]$ExpiresIn) {
  $deadline = (Get-Date).AddSeconds($ExpiresIn)
  while ((Get-Date) -lt $deadline) {
    Start-Sleep -Seconds ([Math]::Max($Interval, 5))
    $r = Invoke-RestMethod -Method Post -Uri 'https://github.com/login/oauth/access_token' -Headers @{ Accept = 'application/json' } -TimeoutSec 20 -UseBasicParsing -ErrorAction Stop `
      -Body @{ client_id = $ClientId; device_code = $DeviceCode; grant_type = 'urn:ietf:params:oauth:grant-type:device_code' }
    if ($r.access_token) { return [string]$r.access_token }
    if ($r.error -eq 'slow_down') { $Interval += 5 }
    elseif ($r.error -ne 'authorization_pending') { throw "GitHub sign-in failed: $($r.error_description)" }
  }
  throw 'The sign-in code expired. Start again.'
}

function Initialize-EpmRepo {
  # Creates or reuses the private repo that runs the vendor checks and writes the job into it.
  param([string]$Token, [hashtable]$Files, [string]$Name = 'appupdater-checks')
  $login = (Invoke-GitHubApi -Token $Token -Path '/user').login
  try { $repo = Invoke-GitHubApi -Token $Token -Path "/repos/$login/$Name" }
  catch {
    if (-not (Test-HttpNotFound $_)) { throw }
    $repo = Invoke-GitHubApi -Token $Token -Method Post -Path '/user/repos' -Body @{ name = $Name; private = $true; auto_init = $true; description = 'AppUpdater vendor release checks' }
  }
  if (-not $repo.private) { throw "$($repo.full_name) is public. The checks only run in a private repository." }
  $full = $repo.full_name; $branch = $repo.default_branch
  foreach ($path in $Files.Keys) {
    $body = @{ message = "Update $path"; branch = $branch; content = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes([string]$Files[$path])) }
    try { $body.sha = (Invoke-GitHubApi -Token $Token -Path "/repos/$full/contents/$($path)?ref=$branch").sha } catch { if (-not (Test-HttpNotFound $_)) { throw } }
    Invoke-GitHubApi -Token $Token -Method Put -Path "/repos/$full/contents/$path" -Body $body | Out-Null
  }
  @{ repo = $full; repoId = $repo.id; branch = $branch }
}

function Start-EpmRun([string]$Token, [string]$Repo, [string]$Branch) {
  # A workflow pushed a moment ago can take a few seconds to become dispatchable.
  for ($i = 0; $i -lt 5; $i++) {
    try { Invoke-GitHubApi -Token $Token -Method Post -Path "/repos/$Repo/actions/workflows/epm-check.yml/dispatches" -Body @{ ref = $Branch } | Out-Null; return }
    catch { if ($i -eq 4) { throw }; Start-Sleep -Seconds 3 }
  }
}

# Intune sign-in uses Microsoft's own Graph PowerShell public client, so nothing is registered in the tenant.
# The access token stays in this process for the session and is never saved.
function Request-MsDeviceCode([string]$ClientId, [string]$Scope) {
  Invoke-RestMethod -Method Post -Uri 'https://login.microsoftonline.com/organizations/oauth2/v2.0/devicecode' `
    -Body @{ client_id = $ClientId; scope = $Scope } -TimeoutSec 20 -UseBasicParsing -ErrorAction Stop
}

function Wait-MsDeviceToken([string]$ClientId, [string]$DeviceCode, [int]$Interval, [int]$ExpiresIn) {
  $deadline = (Get-Date).AddSeconds($ExpiresIn)
  while ((Get-Date) -lt $deadline) {
    Start-Sleep -Seconds ([Math]::Max($Interval, 5))
    try {
      $r = Invoke-RestMethod -Method Post -Uri 'https://login.microsoftonline.com/organizations/oauth2/v2.0/token' -TimeoutSec 20 -UseBasicParsing -ErrorAction Stop `
        -Body @{ grant_type = 'urn:ietf:params:oauth:grant-type:device_code'; client_id = $ClientId; device_code = $DeviceCode }
      return @{ token = [string]$r.access_token; expiresIn = [int]$r.expires_in }
    } catch {
      $err = ''; try { $err = [string]($_.ErrorDetails.Message | ConvertFrom-Json).error } catch { }
      if ($err -eq 'slow_down') { $Interval += 5 }
      elseif ($err -ne 'authorization_pending') { throw "Microsoft sign-in failed: $(if ($err) { $err } else { $_.Exception.Message })" }
    }
  }
  throw 'The sign-in code expired. Start again.'
}

function Get-JwtClaims([string]$Token) {
  $part = ($Token -split '\.')[1]
  if (-not $part) { return @{} }
  $part = $part.Replace('-', '+').Replace('_', '/'); $part += '=' * ((4 - $part.Length % 4) % 4)
  [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($part)) | ConvertFrom-Json
}

function Invoke-GraphGet([string]$Token, [string]$Path) {
  # Returns the object, or writes every item of a collection across its pages; callers wrap it in @().
  # Only Graph next-page links are followed.
  $uri = "https://graph.microsoft.com/beta$Path"; $items = [Collections.Generic.List[object]]::new()
  while ($uri) {
    $r = Invoke-RestMethod -Uri $uri -Headers @{ Authorization = "Bearer $Token" } -TimeoutSec 60 -UseBasicParsing -ErrorAction Stop
    if (-not ($r.PSObject.Properties.Name -contains 'value')) { return $r }
    foreach ($v in @($r.value)) { $items.Add($v) }
    $uri = [string]$r.'@odata.nextLink'
    if ($uri -and $uri -notmatch '^https://graph\.microsoft\.com/') { throw 'Graph returned an unexpected next-page link.' }
  }
  $items.ToArray()
}

function ConvertFrom-EpmRuleSettings {
  # Reads the elevation rules out of an EPM elevation rules policy's settings. Fields this code does not know are
  # kept under 'other', so a format change shows up instead of being dropped.
  param([object[]]$Settings)
  $prefix = 'device_vendor_msft_policy_privilegemanagement_elevationrules_{elevationrulename}'
  $known = @{ name = 'name'; filename = 'fileName'; filehash = 'hash'; filepath = 'filePath'; productname = 'product'; internalname = 'internalName'
              ruletype = 'ruleType'; filedescription = 'fileDescription'; description = 'description'; appliesto = 'appliesTo'; fileversion = 'minVersion' }
  foreach ($s in @($Settings)) {
    $inst = $s.settingInstance
    if ([string]$inst.settingDefinitionId -ne $prefix) { continue }
    foreach ($ruleValue in @($inst.groupSettingCollectionValue)) {
      $rule = @{ name = ''; fileName = ''; hash = ''; filePath = ''; product = ''; internalName = ''; ruleType = ''; certificate = $false; other = @{} }
      $queue = [Collections.Generic.Queue[object]]::new()
      # @($null) holds one $null, so absent child lists are filtered out rather than walked.
      foreach ($c in @($ruleValue.children)) { if ($null -ne $c) { $queue.Enqueue($c) } }
      while ($queue.Count) {
        $c = $queue.Dequeue()
        $key = ([string]$c.settingDefinitionId).Replace("${prefix}_", '')
        $value = if ($c.simpleSettingValue) { [string]$c.simpleSettingValue.value }
                 elseif ($c.choiceSettingValue) { ([string]$c.choiceSettingValue.value).Replace("${prefix}_$($key)_", '').Replace("${prefix}_", '') }
                 else { $null }
        $nested = @($c.choiceSettingValue) + @($c.groupSettingCollectionValue) + @($c.choiceSettingCollectionValue)
        foreach ($n in $nested) { if ($null -ne $n) { foreach ($k in @($n.children)) { if ($null -ne $k) { $queue.Enqueue($k) } } } }
        if ($null -eq $value) { continue }
        if ($known.ContainsKey($key)) { $rule[$known[$key]] = $value }
        else {
          if ($key -match 'certificate' -and $value) { $rule.certificate = $true }
          $rule.other[$key] = $value
        }
      }
      $rule.hash = ([string]$rule.hash).ToUpperInvariant()
      $rule
    }
  }
}

function Get-IntuneEpmPolicies([string]$Token) {
  # Every EPM elevation rules policy with its assignments and rules, plus how many elevation settings policies
  # exist: without one, devices do not run EPM at all.
  $filter = [Uri]::EscapeDataString("templateReference/TemplateFamily eq 'endpointSecurityEndpointPrivilegeManagement'")
  $all = @(Invoke-GraphGet -Token $Token -Path "/deviceManagement/configurationPolicies?`$filter=$filter&`$select=id,name,description,lastModifiedDateTime,templateReference")
  $groupNames = @{}
  $rulesPolicies = @($all | Where-Object { ([string]$_.templateReference.templateId) -like 'cff02aad-51b1-498d-83ad-81161a393f56*' })
  $policies = @(foreach ($p in $rulesPolicies) {
    if ([string]$p.id -notmatch '^[0-9a-fA-F-]{36}$') { continue }
    $assignments = @(foreach ($a in @(Invoke-GraphGet -Token $Token -Path "/deviceManagement/configurationPolicies/$($p.id)/assignments")) {
      $t = $a.target; $type = [string]$t.'@odata.type'
      $name = switch -Wildcard ($type) { '*allDevices*' { 'All devices' } '*allLicensedUsers*' { 'All users' } default { '' } }
      $gid = [string]$t.groupId
      if (-not $name -and $gid -match '^[0-9a-fA-F-]{36}$') {
        if (-not $groupNames.ContainsKey($gid)) {
          $groupNames[$gid] = try { [string](Invoke-GraphGet -Token $Token -Path "/groups/$($gid)?`$select=displayName").displayName } catch { $gid }
        }
        $name = $groupNames[$gid]
      }
      @{ name = $name; exclude = $type -like '*exclusion*' }
    })
    @{ id = [string]$p.id; name = [string]$p.name; modified = [string]$p.lastModifiedDateTime; assignments = $assignments
       rules = @(ConvertFrom-EpmRuleSettings @(Invoke-GraphGet -Token $Token -Path "/deviceManagement/configurationPolicies/$($p.id)/settings")) }
  })
  @{ policies = $policies; settingsPolicies = $all.Count - $rulesPolicies.Count }
}

function Invoke-GraphWrite([string]$Token, [string]$Method, [string]$Path, $Body) {
  $p = @{ Uri = "https://graph.microsoft.com/beta$Path"; Method = $Method; Headers = @{ Authorization = "Bearer $Token" }; TimeoutSec = 60; UseBasicParsing = $true; ErrorAction = 'Stop' }
  if ($null -ne $Body) { $p.ContentType = 'application/json; charset=utf-8'; $p.Body = [Text.Encoding]::UTF8.GetBytes((ConvertTo-Json -Depth 30 -Compress -InputObject $Body)) }
  try { Invoke-RestMethod @p }
  catch {
    # Graph puts the reason in the response body; the exception text alone only says "Bad Request".
    $detail = ''; try { $detail = [string](($_.ErrorDetails.Message | ConvertFrom-Json).error.message) } catch { }
    throw "Intune refused $Method ${Path}: $(if ($detail) { $detail } else { $_.Exception.Message })"
  }
}

function New-EpmRuleValue {
  # One elevation rule in the settings-catalog shape Intune stores. Only the first rule of a policy carries
  # template references; later ones carry nulls. RuleType 'self' is user confirmed with a business justification.
  param([Parameter(Mandatory)][string]$Name, [Parameter(Mandatory)][string]$FileName, [Parameter(Mandatory)][string]$Hash,
        [ValidateSet('self', 'automatic')][string]$RuleType = 'self', [string]$Description = '', [switch]$First)
  $p = 'device_vendor_msft_policy_privilegemanagement_elevationrules_{elevationrulename}'
  $ref = { param($inst, $val, [switch]$Choice)
    if (-not $First) { return @{ inst = $null; val = $null } }
    $v = [ordered]@{ settingValueTemplateId = $val }; if (-not $Choice) { $v.useTemplateDefault = $false }
    @{ inst = [ordered]@{ settingInstanceTemplateId = $inst }; val = $v } }
  $simple = { param($key, $value, $inst, $val) $r = & $ref $inst $val
    [ordered]@{ '@odata.type' = '#microsoft.graph.deviceManagementConfigurationSimpleSettingInstance'; settingDefinitionId = "${p}_$key"; settingInstanceTemplateReference = $r.inst
                simpleSettingValue = [ordered]@{ '@odata.type' = '#microsoft.graph.deviceManagementConfigurationStringSettingValue'; value = $value; settingValueTemplateReference = $r.val } } }
  $applies = & $ref '0cde1c42-c701-44b1-94b7-438dd4536128' '2ec26569-c08f-434c-af3d-a50ac4a1ce26'
  $type = & $ref 'bc5a31ac-95b5-4ec6-be1f-50a384bb165f' 'cb2ea689-ebc3-42ea-a7a4-c704bb13e3ad' -Choice
  $typeChildren = if ($RuleType -eq 'self') { @([ordered]@{ '@odata.type' = '#microsoft.graph.deviceManagementConfigurationChoiceSettingCollectionInstance'; settingDefinitionId = "${p}_ruletype_validation"
      choiceSettingCollectionValue = @([ordered]@{ '@odata.type' = '#microsoft.graph.deviceManagementConfigurationChoiceSettingValue'; value = "${p}_ruletype_validation_0"; children = @() }) }) } else { @() }
  [ordered]@{ settingValueTemplateReference = $null; children = @(
    [ordered]@{ '@odata.type' = '#microsoft.graph.deviceManagementConfigurationChoiceSettingInstance'; settingDefinitionId = "${p}_appliesto"; settingInstanceTemplateReference = $applies.inst
                choiceSettingValue = [ordered]@{ value = "${p}_allusers"; settingValueTemplateReference = $applies.val; children = @() } }
    (& $simple 'description' $Description 'b3714f3a-ead8-4682-a16f-ffa264c9d58f' '5e82a1e9-ef4f-43ea-8031-93aace2ad14d')
    (& $simple 'filehash' $Hash.ToUpperInvariant() 'e4436e2c-1584-4fba-8e38-78737cbbbfdf' '1adcc6f7-9fa4-4ce3-8941-2ce22cf5e404')
    [ordered]@{ '@odata.type' = '#microsoft.graph.deviceManagementConfigurationChoiceSettingInstance'; settingDefinitionId = "${p}_ruletype"; settingInstanceTemplateReference = $type.inst
                choiceSettingValue = [ordered]@{ '@odata.type' = '#microsoft.graph.deviceManagementConfigurationChoiceSettingValue'; value = "${p}_$RuleType"; settingValueTemplateReference = $type.val; children = $typeChildren } }
    (& $simple 'name' $Name 'fdabfcf9-afa4-4dbf-a4ef-d5c1549065e1' '03f003e5-43ef-4e7e-bf30-57f00781fdcc')
    (& $simple 'filename' $FileName '0c1ceb2b-bbd4-46d4-9ba5-9ee7abe1f094' 'a165327c-f0e5-4c7d-9af1-d856b02191f7')) }
}

function Get-EpmRuleName($RuleValue) {
  $c = @($RuleValue.children) | Where-Object { [string]$_.settingDefinitionId -like '*_{elevationrulename}_name' } | Select-Object -First 1
  if ($c) { [string]$c.simpleSettingValue.value } else { '' }
}

function Set-IntuneEpmPolicyRules {
  # Adds one rule to an existing elevation rules policy and drops the named older ones, keeping everything else
  # in the policy as Intune returned it. Settings catalog policies are updated by replacing the whole policy.
  param([string]$Token, [string]$PolicyId, $Rule, [string[]]$RemoveNames = @())
  $prefix = 'device_vendor_msft_policy_privilegemanagement_elevationrules_{elevationrulename}'
  $pol = Invoke-GraphGet -Token $Token -Path "/deviceManagement/configurationPolicies/$($PolicyId)?`$expand=settings"
  $ruleCount = 0
  $settings = @(foreach ($s in @($pol.settings)) {
    $inst = $s.settingInstance
    if ([string]$inst.settingDefinitionId -eq $prefix) {
      $kept = @(@($inst.groupSettingCollectionValue) | Where-Object { $null -ne $_ -and (Get-EpmRuleName $_) -notin $RemoveNames })
      $inst.groupSettingCollectionValue = @($kept) + @($Rule)
      $ruleCount = $inst.groupSettingCollectionValue.Count
    }
    [ordered]@{ '@odata.type' = '#microsoft.graph.deviceManagementConfigurationSetting'; settingInstance = $inst }
  })
  if (-not @($settings | Where-Object { [string]$_.settingInstance.settingDefinitionId -eq $prefix }).Count) { throw "$($pol.name) holds no elevation rules list to add to." }
  if ($ruleCount -gt 100) { throw "$($pol.name) would hold $ruleCount rules; Intune allows 100. Remove older versions first." }
  Invoke-GraphWrite -Token $Token -Method Put -Path "/deviceManagement/configurationPolicies/$PolicyId" -Body ([ordered]@{
    name = [string]$pol.name; description = [string]$pol.description; platforms = [string]$pol.platforms; technologies = [string]$pol.technologies
    roleScopeTagIds = @($pol.roleScopeTagIds | Where-Object { $_ }); templateReference = @{ templateId = [string]$pol.templateReference.templateId }; settings = $settings }) | Out-Null
}

function New-IntuneEpmPolicy {
  # Creates an elevation rules policy holding one rule and assigns it to one target.
  param([string]$Token, [string]$Name, $Rule, [string]$Target)
  $prefix = 'device_vendor_msft_policy_privilegemanagement_elevationrules_{elevationrulename}'
  $created = Invoke-GraphWrite -Token $Token -Method Post -Path '/deviceManagement/configurationPolicies' -Body ([ordered]@{
    name = $Name; description = 'Elevation rules added by AppUpdater after each new version is verified.'; platforms = 'windows10'; technologies = 'endpointPrivilegeManagement'
    templateReference = @{ templateId = 'cff02aad-51b1-498d-83ad-81161a393f56_1' }
    settings = @([ordered]@{ '@odata.type' = '#microsoft.graph.deviceManagementConfigurationSetting'; settingInstance = [ordered]@{
      '@odata.type' = '#microsoft.graph.deviceManagementConfigurationGroupSettingCollectionInstance'; settingDefinitionId = $prefix
      settingInstanceTemplateReference = @{ settingInstanceTemplateId = 'ee3d2e5f-6b3d-4cb1-af9b-37b02d3dbae2' }; groupSettingCollectionValue = @($Rule) } }) })
  $id = [string]$created.id
  if ($id -notmatch '^[0-9a-fA-F-]{36}$') { throw 'Intune did not return the new policy.' }
  $targetBody = switch ($Target) {
    'allUsers' { @{ '@odata.type' = '#microsoft.graph.allLicensedUsersAssignmentTarget' } }
    'allDevices' { @{ '@odata.type' = '#microsoft.graph.allDevicesAssignmentTarget' } }
    default { @{ '@odata.type' = '#microsoft.graph.groupAssignmentTarget'; groupId = $Target } }
  }
  Invoke-GraphWrite -Token $Token -Method Post -Path "/deviceManagement/configurationPolicies/$id/assign" -Body @{ assignments = @(@{ target = $targetBody }) } | Out-Null
  $id
}

function Confirm-IntuneEpmRule {
  # Reads the policy back and checks the rule is there exactly as written and the removed ones are gone.
  param([string]$Token, [string]$PolicyId, [string]$Name, [string]$FileName, [string]$Hash, [string]$RuleType, [string[]]$RemoveNames = @())
  $rules = @(ConvertFrom-EpmRuleSettings @(Invoke-GraphGet -Token $Token -Path "/deviceManagement/configurationPolicies/$PolicyId/settings"))
  $found = @($rules | Where-Object { $_.name -eq $Name })
  if ($found.Count -ne 1) { throw "Read back $($found.Count) rules named '$Name' in the policy." }
  $r = $found[0]
  $diff = @(
    if ($r.fileName -ne $FileName) { "file name is '$($r.fileName)'" }
    if ($r.hash -ne $Hash.ToUpperInvariant()) { "hash is '$($r.hash)'" }
    if ($r.ruleType -ne $RuleType) { "rule type is '$($r.ruleType)'" })
  if ($diff.Count) { throw "The rule read back differs: $($diff -join '; ')." }
  $left = @($rules | Where-Object { $_.name -in $RemoveNames } | ForEach-Object name)
  if ($left.Count) { throw "Still in the policy after removal: $($left -join ', ')." }
  $rules.Count
}

# Azure agent for EPM vendor checks: an Automation account runs the same checks as the GitHub job, adds verified
# versions to Intune with its own identity, and keeps apps.json, results.json and runs.json in a storage container.
# AppUpdater keeps only a key limited to that container.
$AzureCliClientId = '1950a258-227b-4e31-a9cf-717495945fc2'
$AzureEpmNames = @{ resourceGroup = 'appupdater-epm'; automation = 'appupdater-epm'; container = 'epm'; runbook = 'epm-check'; schedule = 'every-6-hours' }

function Invoke-Arm {
  param([string]$Token, [string]$Path, [string]$Api, [string]$Method = 'GET', $Body, [string]$ContentType = 'application/json; charset=utf-8')
  $p = @{ Uri = "https://management.azure.com$($Path)?api-version=$Api"; Method = $Method; Headers = @{ Authorization = "Bearer $Token" }; TimeoutSec = 90; UseBasicParsing = $true; ErrorAction = 'Stop' }
  if ($null -ne $Body) {
    $p.ContentType = $ContentType
    $p.Body = if ($Body -is [string]) { [Text.Encoding]::UTF8.GetBytes($Body) } else { [Text.Encoding]::UTF8.GetBytes((ConvertTo-Json -Depth 20 -Compress -InputObject $Body)) }
  }
  try { Invoke-RestMethod @p }
  catch {
    $detail = ''; try { $detail = [string](($_.ErrorDetails.Message | ConvertFrom-Json).error.message) } catch { }
    throw "Azure refused $Method ${Path}: $(if ($detail) { $detail } else { $_.Exception.Message })"
  }
}

function New-EpmAzureRunbook {
  # The runbook is the check functions from the GitHub job plus the Intune rule functions, then the loop below.
  $tokens = $null; $errs = $null
  $ast = [Management.Automation.Language.Parser]::ParseInput($EpmCheckScript, [ref]$tokens, [ref]$errs)
  $checks = @($ast.FindAll({ param($n) $n -is [Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -in @('Compare-Version', 'Resolve-Latest', 'Get-WingetCompare', 'Test-EpmRelease') }, $true) | ForEach-Object { $_.Extent.Text })
  $intune = Get-BuildFunctionSource -Roots @('Get-IntuneEpmPolicies', 'New-EpmRuleValue', 'Set-IntuneEpmPolicyRules', 'Confirm-IntuneEpmRule')
  $main = @'
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
$gh = @{ 'User-Agent' = 'appupdater-checks' }
function Write-AppLog { param([string]$Message, [string]$Level) }
function Get-MiToken([string]$Resource) {
  (Invoke-RestMethod "$($env:IDENTITY_ENDPOINT)?resource=$Resource&api-version=2019-08-01" -Headers @{ 'X-IDENTITY-HEADER' = $env:IDENTITY_HEADER; Metadata = 'True' }).access_token
}
$account = Get-AutomationVariable -Name 'EpmStorageAccount'
$blob = "https://$account.blob.core.windows.net/epm"
$sh = @{ Authorization = "Bearer $(Get-MiToken 'https://storage.azure.com/')"; 'x-ms-version' = '2021-08-06' }
function Read-Blob([string]$Name, $Default) {
  try { Invoke-RestMethod "$blob/$Name" -Headers $sh } catch { if ([int]$_.Exception.Response.StatusCode -eq 404) { $Default } else { throw } }
}
function Write-Blob([string]$Name, $Value) {
  Invoke-RestMethod "$blob/$Name" -Method Put -Headers ($sh + @{ 'x-ms-blob-type' = 'BlockBlob' }) -ContentType 'application/json' -Body (ConvertTo-Json -Depth 10 -Compress -InputObject $Value) | Out-Null
}
$letters = { param($v) ([string]$v).ToLowerInvariant() -replace '[^a-z0-9]', '' }
$state = Read-Blob 'apps.json' ([pscustomobject]@{ apps = @(); known = [pscustomobject]@{} })
$known = @{}; if ($state.known) { $state.known.PSObject.Properties | ForEach-Object { $known[$_.Name] = [string]$_.Value } }
$results = @{}; $prev = Read-Blob 'results.json' $null; if ($prev) { $prev.PSObject.Properties | ForEach-Object { $results[$_.Name] = $_.Value } }
$graph = Get-MiToken 'https://graph.microsoft.com/'
$policies = $null
$run = [ordered]@{ at = (Get-Date).ToUniversalTime().ToString('o'); runner = 'azure'; items = @() }
foreach ($app in @($state.apps)) {
  try { $latest = Resolve-Latest $app }
  catch { $run.items += @{ id = $app.id; name = $app.name; status = 'source-error'; note = $_.Exception.Message }; continue }
  if ($known[$app.id] -and (Compare-Version $latest.version $known[$app.id]) -le 0) {
    $run.items += @{ id = $app.id; name = $app.name; status = 'unchanged'; version = $latest.version; note = "No new version ($($latest.version)); download skipped" }; continue
  }
  $r = Test-EpmRelease $app $latest $env:TEMP
  $note = $r.reason
  if ($r.status -eq 'ok') {
    $known[$app.id] = $r.version
    try {
      if ($null -eq $policies) { $policies = @((Get-IntuneEpmPolicies -Token $graph).policies) }
      $n = & $letters $app.name
      $pol = @($policies | Where-Object { $_.rules | Where-Object { $_.hash -eq $r.sha256 } }) + @($policies | Where-Object { $_.name -eq "EPM · $($app.name)" }) +
             @($policies | Where-Object { $n.Length -ge 3 -and ($_.rules | Where-Object { (& $letters "$($_.fileName) $($_.name) $($_.product)").Contains($n) }) }) | Select-Object -First 1
      if (-not $pol) { $r.intune = @{ status = 'no-policy'; message = 'No policy holds this app yet. Add its first version from AppUpdater.' } }
      elseif (@($pol.rules | Where-Object { $_.hash -eq $r.sha256 }).Count) { $r.intune = @{ status = 'already'; policy = $pol.name; message = "Already in $($pol.name)" } }
      else {
        $name = "$($app.name) $($r.version)"
        $type = if ($app.ruleType -in @('self', 'automatic')) { $app.ruleType } else { 'self' }
        $rule = New-EpmRuleValue -Name $name -FileName $r.file -Hash $r.sha256 -RuleType $type -Description "Signed by $($r.signer). Added by AppUpdater on Azure."
        Set-IntuneEpmPolicyRules -Token $graph -PolicyId $pol.id -Rule $rule
        [void](Confirm-IntuneEpmRule -Token $graph -PolicyId $pol.id -Name $name -FileName $r.file -Hash $r.sha256 -RuleType $type)
        $r.intune = @{ status = 'added'; policy = $pol.name; message = "Added to $($pol.name) and read back" }
      }
    } catch { $r.intune = @{ status = 'failed'; message = $_.Exception.Message } }
    $note = "$($r.version) verified, signed by $($r.signer); $($r.intune.message)"
  }
  $results[$app.id] = $r
  $run.items += @{ id = $app.id; name = $app.name; status = $r.status; version = $r.version; note = $note }
  Write-Output "$($app.name) $($r.version): $($r.status) $note"
}
$state.known = [pscustomobject]$known
Write-Blob 'apps.json' $state
Write-Blob 'results.json' ([pscustomobject]$results)
$runs = @(Read-Blob 'runs.json' @())
Write-Blob 'runs.json' (@([pscustomobject]$run) + @($runs | Select-Object -First 29))
'@
  ($checks -join "`n`n") + "`n`n" + $intune + "`n`n" + $main
}

function Wait-ArmProvisioned {
  param([string]$Token, [string]$Path, [string]$Api, [int]$Seconds = 180)
  $deadline = (Get-Date).AddSeconds($Seconds)
  do {
    $r = Invoke-Arm -Token $Token -Path $Path -Api $Api
    $state = [string]$r.properties.provisioningState
    if ($state -eq 'Succeeded' -or (-not $state -and $r.id)) { return $r }
    if ($state -eq 'Failed') { throw "Azure could not create $Path." }
    Start-Sleep -Seconds 5
  } while ((Get-Date) -lt $deadline)
  throw "Azure is still creating $Path; try again in a few minutes."
}

function New-EpmAzureAgent {
  # Creates (or reuses) the resource group, storage, Automation account, runbook and schedule, and returns what
  # AppUpdater keeps: names, the identity's id, and a key for the storage container only.
  param([string]$Token, [string]$SubscriptionId, [string]$Location, [string]$Runbook)
  $n = $AzureEpmNames
  $sub = "/subscriptions/$SubscriptionId"; $rg = "$sub/resourceGroups/$($n.resourceGroup)"
  Write-Step '1/7' 'Registering the Automation and Storage services on the subscription'
  foreach ($ns in @('Microsoft.Automation', 'Microsoft.Storage')) { Invoke-Arm -Token $Token -Path "$sub/providers/$ns/register" -Api '2021-04-01' -Method Post | Out-Null }
  Write-Step '2/7' "Resource group $($n.resourceGroup) in $Location"
  Invoke-Arm -Token $Token -Path $rg -Api '2021-04-01' -Method Put -Body @{ location = $Location; tags = @{ 'created-by' = 'AppUpdater' } } | Out-Null
  Write-Step '3/7' 'Storage for the watch list and results'
  $existing = @((Invoke-Arm -Token $Token -Path "$rg/providers/Microsoft.Storage/storageAccounts" -Api '2023-01-01').value) | Where-Object { $_.name -like 'auepm*' } | Select-Object -First 1
  $sa = if ($existing) { [string]$existing.name } else { 'auepm' + -join ((1..10) | ForEach-Object { 'abcdefghijklmnopqrstuvwxyz0123456789'[(Get-Random -Maximum 36)] }) }
  $saPath = "$rg/providers/Microsoft.Storage/storageAccounts/$sa"
  if (-not $existing) {
    Invoke-Arm -Token $Token -Path $saPath -Api '2023-01-01' -Method Put -Body @{ location = $Location; kind = 'StorageV2'; sku = @{ name = 'Standard_LRS' }
      properties = @{ allowBlobPublicAccess = $false; minimumTlsVersion = 'TLS1_2'; supportsHttpsTrafficOnly = $true; allowSharedKeyAccess = $true; accessTier = 'Hot' } } | Out-Null
    [void](Wait-ArmProvisioned -Token $Token -Path $saPath -Api '2023-01-01')
  }
  Invoke-Arm -Token $Token -Path "$saPath/blobServices/default/containers/$($n.container)" -Api '2023-01-01' -Method Put -Body @{ properties = @{ publicAccess = 'None' } } | Out-Null
  Write-OK "Storage $sa ready"
  Write-Step '4/7' 'Automation account with its own identity'
  $aa = "$rg/providers/Microsoft.Automation/automationAccounts/$($n.automation)"
  $acct = Invoke-Arm -Token $Token -Path $aa -Api '2023-11-01' -Method Put -Body @{ location = $Location; identity = @{ type = 'SystemAssigned' }; properties = @{ sku = @{ name = 'Basic' }; publicNetworkAccess = $true } }
  $principalId = [string]$acct.identity.principalId
  if (-not $principalId) { $principalId = [string](Wait-ArmProvisioned -Token $Token -Path $aa -Api '2023-11-01').identity.principalId }
  if ($principalId -notmatch '^[0-9a-fA-F-]{36}$') { throw 'Azure did not give the Automation account an identity.' }
  Invoke-Arm -Token $Token -Path "$aa/variables/EpmStorageAccount" -Api '2023-11-01' -Method Put -Body @{ name = 'EpmStorageAccount'; properties = @{ value = (ConvertTo-Json $sa); isEncrypted = $false } } | Out-Null
  Write-Step '5/7' 'The check runbook, every 6 hours'
  Invoke-Arm -Token $Token -Path "$aa/runbooks/$($n.runbook)" -Api '2023-11-01' -Method Put -Body @{ location = $Location; properties = @{ runbookType = 'PowerShell72'; logProgress = $false; logVerbose = $false; description = 'EPM vendor release checks from AppUpdater' } } | Out-Null
  Invoke-Arm -Token $Token -Path "$aa/runbooks/$($n.runbook)/draft/content" -Api '2023-11-01' -Method Put -Body $Runbook -ContentType 'text/powershell' | Out-Null
  Invoke-Arm -Token $Token -Path "$aa/runbooks/$($n.runbook)/publish" -Api '2023-11-01' -Method Post | Out-Null
  Invoke-Arm -Token $Token -Path "$aa/schedules/$($n.schedule)" -Api '2023-11-01' -Method Put -Body @{ name = $n.schedule; properties = @{ startTime = (Get-Date).ToUniversalTime().AddMinutes(30).ToString('o'); frequency = 'Hour'; interval = 6; timeZone = 'UTC' } } | Out-Null
  $linked = @((Invoke-Arm -Token $Token -Path "$aa/jobSchedules" -Api '2023-11-01').value) | Where-Object { $_.properties.runbook.name -eq $n.runbook -and $_.properties.schedule.name -eq $n.schedule }
  if (-not $linked) { Invoke-Arm -Token $Token -Path "$aa/jobSchedules/$([guid]::NewGuid())" -Api '2023-11-01' -Method Put -Body @{ properties = @{ schedule = @{ name = $n.schedule }; runbook = @{ name = $n.runbook } } } | Out-Null }
  Write-OK 'Runbook published and scheduled'
  Write-Step '6/7' 'Letting the identity use the storage'
  $role = @{ properties = @{ roleDefinitionId = "$sub/providers/Microsoft.Authorization/roleDefinitions/ba92f5b4-2d11-453d-a403-e96b0029c9fe"; principalId = $principalId; principalType = 'ServicePrincipal' } }
  # A new identity can take a minute to reach Azure's role service.
  for ($try = 1; ; $try++) {
    try { Invoke-Arm -Token $Token -Path "$saPath/providers/Microsoft.Authorization/roleAssignments/$([guid]::NewGuid())" -Api '2022-04-01' -Method Put -Body $role | Out-Null; break }
    catch { if ($_.Exception.Message -match 'already exists') { break }; if ($try -ge 8) { throw }; Start-Sleep -Seconds 10 }
  }
  Write-Step '7/7' 'A key for AppUpdater, limited to that container'
  $sas = Invoke-Arm -Token $Token -Path "$saPath/ListServiceSas" -Api '2023-01-01' -Method Post -Body @{ canonicalizedResource = "/blob/$sa/$($n.container)"; signedResource = 'c'; signedPermission = 'rwl'
    signedExpiry = (Get-Date).ToUniversalTime().AddYears(1).ToString('yyyy-MM-ddTHH:mm:ssZ'); signedProtocol = 'https' }
  if (-not $sas.serviceSasToken) { throw 'Azure did not return a key for the container.' }
  Write-OK 'Azure pieces created'
  @{ subscriptionId = $SubscriptionId; resourceGroup = $n.resourceGroup; automationAccount = $n.automation; storageAccount = $sa; principalId = $principalId; sas = [string]$sas.serviceSasToken; location = $Location }
}

function Grant-EpmAgentIntune {
  # Gives the Automation account's identity Microsoft Graph DeviceManagementConfiguration.ReadWrite.All, nothing else.
  param([string]$GraphToken, [string]$PrincipalId)
  $graphSp = @(Invoke-GraphGet -Token $GraphToken -Path "/servicePrincipals?`$filter=$([Uri]::EscapeDataString("appId eq '00000003-0000-0000-c000-000000000000'"))&`$select=id,appRoles") | Select-Object -First 1
  $roleId = [string](@($graphSp.appRoles) | Where-Object { $_.value -eq 'DeviceManagementConfiguration.ReadWrite.All' } | Select-Object -First 1).id
  if (-not $roleId) { throw 'Microsoft Graph did not list the Intune configuration permission.' }
  try { Invoke-GraphWrite -Token $GraphToken -Method Post -Path "/servicePrincipals/$PrincipalId/appRoleAssignments" -Body @{ principalId = $PrincipalId; resourceId = [string]$graphSp.id; appRoleId = $roleId } | Out-Null }
  catch { if ($_.Exception.Message -notmatch 'already exists') { throw } }
  Write-OK 'The identity may change Intune device configuration'
}

function Start-EpmAzureRun {
  # Starts the runbook now and waits for it to finish.
  param([string]$Token, [hashtable]$Agent, [int]$Seconds = 900)
  $aa = "/subscriptions/$($Agent.subscriptionId)/resourceGroups/$($Agent.resourceGroup)/providers/Microsoft.Automation/automationAccounts/$($Agent.automationAccount)"
  $id = [guid]::NewGuid().ToString()
  Invoke-Arm -Token $Token -Path "$aa/jobs/$id" -Api '2023-11-01' -Method Put -Body @{ properties = @{ runbook = @{ name = $AzureEpmNames.runbook } } } | Out-Null
  Write-Info 'Waiting for a hosted machine and the run (usually 2 to 5 minutes)'
  $deadline = (Get-Date).AddSeconds($Seconds)
  do {
    Start-Sleep -Seconds 15
    $status = [string](Invoke-Arm -Token $Token -Path "$aa/jobs/$id" -Api '2023-11-01').properties.status
    if ($status -in @('Completed', 'Failed', 'Stopped', 'Suspended')) { break }
  } while ((Get-Date) -lt $deadline)
  if ($status -ne 'Completed') { throw "The test run ended as '$(if ($status) { $status } else { 'still running' })'. Its log is in the Azure portal under the Automation account's Jobs." }
  Write-OK 'Test run completed'
}

function Invoke-EpmAzureBlob {
  # Reads or writes one JSON file in the agent's container with AppUpdater's container key.
  param([string]$Account, [string]$Sas, [string]$Name, $Value, [switch]$Write)
  if ($Account -notmatch '^[a-z0-9]{3,24}$' -or $Name -notmatch '^[a-z]+\.json$') { throw 'Unexpected storage name.' }
  $uri = "https://$Account.blob.core.windows.net/$($AzureEpmNames.container)/$($Name)?$($Sas.TrimStart('?'))"
  $h = @{ 'x-ms-version' = '2021-08-06' }
  if ($Write) {
    $h['x-ms-blob-type'] = 'BlockBlob'
    Invoke-RestMethod -Uri $uri -Method Put -Headers $h -ContentType 'application/json' -Body ([Text.Encoding]::UTF8.GetBytes((ConvertTo-Json -Depth 10 -Compress -InputObject $Value))) -TimeoutSec 30 -UseBasicParsing -ErrorAction Stop | Out-Null
    return
  }
  try { Invoke-RestMethod -Uri $uri -Headers $h -TimeoutSec 30 -UseBasicParsing -ErrorAction Stop }
  catch { if ([int]$_.Exception.Response.StatusCode -eq 404) { $null } else { throw } }
}

function Get-EpmAzureState {
  # The same shape the worker returns, so the EPM screens treat both runners alike.
  param([hashtable]$Agent, [string]$Sas)
  $apps = Invoke-EpmAzureBlob -Account $Agent.storageAccount -Sas $Sas -Name 'apps.json'
  $results = Invoke-EpmAzureBlob -Account $Agent.storageAccount -Sas $Sas -Name 'results.json'
  $runs = @(Invoke-EpmAzureBlob -Account $Agent.storageAccount -Sas $Sas -Name 'runs.json' | ForEach-Object { $_ } | Where-Object { $_ })
  @{ cfg = @{ runner = 'azure'; repo = "Azure · $($Agent.resourceGroup)"; subscriptionId = $Agent.subscriptionId }
     apps = @(if ($apps) { $apps.apps }); results = $(if ($results) { $results } else { @{} }); runs = $runs
     last = $(if ($runs.Count) { @{ at = [string]$runs[0].at } } else { $null }) }
}

function Set-EpmAzureApps {
  param([hashtable]$Agent, [string]$Sas, [object[]]$Apps)
  $current = Invoke-EpmAzureBlob -Account $Agent.storageAccount -Sas $Sas -Name 'apps.json'
  $known = if ($current -and $current.known) { $current.known } else { @{} }
  Invoke-EpmAzureBlob -Account $Agent.storageAccount -Sas $Sas -Name 'apps.json' -Write -Value @{ apps = @($Apps); known = $known }
}

function Get-EpmAzureSas { try { [string][WinCredManager]::Read('AppUpdater-EpmAzureSas') } catch { '' } }

function ConvertTo-PlainHashtable($Value) {
  # Config read back from JSON is a PSCustomObject; background jobs and functions here take hashtables.
  if ($Value -is [hashtable]) { return $Value.Clone() }
  $h = @{}; if ($Value) { $Value.PSObject.Properties | ForEach-Object { $h[$_.Name] = $_.Value } }; $h
}

function Invoke-EpmWorker {
  param([string]$WorkerUrl, [string]$Token, $Body)
  $p = @{ Uri = "$($WorkerUrl.TrimEnd('/'))/epm/state"; Headers = @{ 'X-Auth-Token' = $Token }; TimeoutSec = 30; ErrorAction = 'Stop'; UseBasicParsing = $true }
  if ($null -ne $Body) { $p.Method = 'Put'; $p.ContentType = 'application/json; charset=utf-8'; $p.Body = [Text.Encoding]::UTF8.GetBytes((ConvertTo-Json -Depth 8 -Compress -InputObject $Body)) }
  try { Invoke-RestMethod @p }
  catch {
    if (Test-HttpNotFound $_) { throw 'Your Cloudflare worker is older than release checks. Update it with Re-deploy in section 01.' }
    throw
  }
}

function ConvertTo-EpmApp($App) {
  # The runner downloads whatever these point at, so only well-formed https sources and plain IDs get through.
  $id = [string]$App.id; $src = $App.source
  if ($id -notmatch '^[a-z0-9][a-z0-9-]{0,63}$') { throw "Invalid app id '$id'." }
  $name = ([string]$App.name).Trim()
  if (-not $name -or $name.Length -gt 120) { throw 'Each app needs a name.' }
  $out = [ordered]@{ id = $id; name = $name; publisher = ([string]$App.publisher).Trim() }
  if ($App.winget) { if ([string]$App.winget -notmatch '^[A-Za-z0-9][\w.+-]*\.[\w.+-]+$') { throw "'$($App.winget)' is not a winget ID." }; $out.winget = [string]$App.winget }
  $source = [ordered]@{ type = [string]$src.type }
  switch ($source.type) {
    'github' { if ([string]$src.repo -notmatch '^[\w.-]+/[\w.-]+$') { throw "'$($src.repo)' is not owner/repo." }; $source.repo = [string]$src.repo }
    'redirect' { if (-not (Test-SafeHttpsUrl ([string]$src.url))) { throw 'The download link must be https.' }; $source.url = [string]$src.url }
    'page' {
      if (-not (Test-SafeHttpsUrl ([string]$src.url)) -or -not (Test-SafeHttpsUrl ([string]$src.download))) { throw 'The page and download link must be https.' }
      $source.url = [string]$src.url; $source.download = [string]$src.download
      if (-not $src.versionRegex) { throw 'A version pattern is needed to read the version from a page.' }
    }
    default { throw "Unknown source type '$($source.type)'." }
  }
  foreach ($k in @('asset', 'versionRegex')) {
    if (-not $src.$k) { continue }
    try { [void][regex]::new([string]$src.$k) } catch { throw "The $k pattern is not a valid regular expression." }
    $source[$k] = [string]$src.$k
  }
  $out.source = $source
  $out
}

function Send-ToPage {
  param($Wv, [string]$Type, [hashtable]$Payload)
  $json = (@{ type = $Type; payload = $Payload } | ConvertTo-Json -Depth 8 -Compress)
  try {
    if (-not $Wv.CoreWebView2 -or $Wv.Dispatcher.HasShutdownStarted) { throw 'The application view is unavailable.' }
    $Wv.Dispatcher.Invoke([action]{ $Wv.CoreWebView2.PostWebMessageAsJson($json) })
  } catch { Write-AppLog "Could not deliver UI event '$Type': $($_.Exception.Message)" ERROR }
}

function Get-BuildFunctionSource {
  # The named functions and every function they call, as source for a runspace.
  param([string[]]$Roots = @('Invoke-HeadlessPackageBuild', 'Get-PreflightFindings'))
  $pending = [Collections.Generic.Queue[string]]::new()
  foreach ($root in $Roots) { $pending.Enqueue($root) }
  $seen = @{}
  $definitions = [Collections.Generic.List[string]]::new()
  while ($pending.Count -gt 0) {
    $name = $pending.Dequeue()
    if ($seen.ContainsKey($name)) { continue }
    $seen[$name] = $true
    if ($name -like 'Show-Wpf*' -or $name -in @('Write-Host','Write-AppLog','Write-OK','Write-Warn','Write-Fail','Write-Info','Write-Step')) { continue }
    $fn = Get-Item -LiteralPath "Function:\$name" -ErrorAction SilentlyContinue
    if (-not $fn) { continue }
    $definitions.Add("function $name {`n$($fn.ScriptBlock)`n}")
    foreach ($command in $fn.ScriptBlock.Ast.FindAll({ param($node) $node -is [Management.Automation.Language.CommandAst] }, $true)) {
      $dependency = $command.GetCommandName()
      if ($dependency) { $pending.Enqueue($dependency) }
    }
  }
  if (-not $definitions.Count) { throw 'Build engine functions are unavailable.' }
  return $definitions -join "`n"
}

function Start-PackageBuildJob {
  param($Wv, [hashtable]$Config, [hashtable]$FormData)

  if ($script:ActiveBuild -and -not $script:ActiveBuild.Finished) { throw 'A build is already running. Wait for it to finish before starting another.' }
  if ($script:ActiveTest -and -not $script:ActiveTest.Finished) { throw 'Wait for the local test to finish before rebuilding.' }

  $bq = [System.Collections.Queue]::Synchronized((New-Object System.Collections.Queue))
  $bd = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))

  # Get-PackagingProfiles is not loaded in the child runspace.
  $_profile = @{ OrgName = ''; LogoImagePath = ''; BannerImagePath = '' }
  if ($FormData.ProfileName) {
    $_pp = (Get-PackagingProfiles).Profiles | Where-Object { $_.Name -eq $FormData.ProfileName } | Select-Object -First 1
    if ($_pp) {
      if ($_pp.OrgName) { $_profile.OrgName = $_pp.OrgName }
      $_profile.LogoImagePath   = $_pp.LogoImagePath
      $_profile.BannerImagePath = $_pp.BannerImagePath
    }
  }
  if ($FormData.OverrideOrgName)         { $_profile.OrgName = $FormData.OverrideOrgName }
  if ($FormData.OverrideLogoImagePath)   { $_profile.LogoImagePath = $FormData.OverrideLogoImagePath }
  if ($FormData.OverrideBannerImagePath) { $_profile.BannerImagePath = $FormData.OverrideBannerImagePath }

  # Never run $__CoreSrc whole: its single-instance mutex is held by this process, so it would exit.
  $_buildFnSrc = Get-BuildFunctionSource

  $rs = [runspacefactory]::CreateRunspace()
  $ps = $null
  try {
  $rs.Open()
  $rs.SessionStateProxy.SetVariable('_bq', $bq)
  $rs.SessionStateProxy.SetVariable('_bd', $bd)
  $rs.SessionStateProxy.SetVariable('_cfg', $Config.Clone())
  $_fdCopy = $FormData.Clone()
  # The CISA catalogue is read only when online lookups are on; it is downloaded with the winget catalogue.
  $kevFile = Join-Path $KevCacheDir 'kev.json'
  if (-not $Config.DisableReleaseCheck -and (Test-Path -LiteralPath $kevFile)) { $_fdCopy.KevPath = $kevFile }
  $_fdCopy.NvdLookups = [bool]$Config.NvdLookups -and -not $Config.DisableReleaseCheck
  $rs.SessionStateProxy.SetVariable('_fd', $_fdCopy)
  $rs.SessionStateProxy.SetVariable('_profile', $_profile)
  $_memory = try { (Get-AppMemory)[[string]$FormData.AppID] } catch { $null }
  $rs.SessionStateProxy.SetVariable('_history', @(if ($_memory) { $_memory.builds }))
  $rs.SessionStateProxy.SetVariable('_fnSrc', $_buildFnSrc)
  $rs.SessionStateProxy.SetVariable('ArpMatchFnText', $global:ArpMatchFnText)
  $rs.SessionStateProxy.SetVariable('EventSecretB64', $global:EventSecretB64)
  foreach ($vn in @('XmlFile','IntuneWinUtilPath','IntuneWinUtilURL','TempBase','OutputBase',
                     'PSADTCacheDir','PSADTv3URL','PSADTModOnlyURL',
                     'DriverStoreBase','DriverLibraryFile','InstallPrinterScriptSrc','DetectPrinterScriptSrc','UninstallPrinterScriptSrc')) {
    $rs.SessionStateProxy.SetVariable($vn, (Get-Variable $vn -ValueOnly -Scope Script -ErrorAction SilentlyContinue))
  }

  $ps = [powershell]::Create()
  $ps.Runspace = $rs
  [void]$ps.AddScript({
    # $global: vars are not shared across runspaces.
    $global:_DpapiPrefix = 'DPAPI:'
    $global:_CredMgrSentinel = 'CREDMGR'
    $ErrorActionPreference = 'Stop'
    function Write-AppLog { param([string]$Message,[string]$Level='INFO') if ($_bq.Count -lt 2000) { $_bq.Enqueue("log|[$Level] $Message") } }
    function Write-Host   { param([object]$O,[string]$ForegroundColor='Gray',[switch]$NoNewline) if ($_bq.Count -lt 2000) { $_bq.Enqueue("line|$O") } }
    function Write-OK     { param([string]$M) Write-Host "  [OK]  $M" }
    function Write-Warn   { param([string]$M) Write-Host "  [!!]  $M" }
    function Write-Fail   { param([string]$M) throw $M }
    function Write-Info   { param([string]$M) Write-Host "  [--]  $M" }
    function Write-Step   { param([string]$N,[string]$M) $_bq.Enqueue("step|$N|$M") }
    function Show-WpfMsg  { param([string]$Title='',[string]$Message='',[string]$Type='info',[switch]$Confirm,[string]$Detail,[string]$YesLabel,[string]$NoLabel)
      if ($Type -eq 'error') { throw "$Title`: $Message $Detail" }
      Write-Host "[$Title] $Message"
      if ($Confirm) { return $true }
    }
    function Show-WpfAppForm { param([hashtable]$Defaults=@{},[bool]$HasWorker=$false,[string]$OrgName='',[switch]$AmendMode) return $null }
    function Show-WpfPSADTExport { throw 'PSADT tooling is unavailable. Check the dependency cache and retry.' }

    try {
      Invoke-Expression $_fnSrc
      $installer = @{}
      if ($_fd.InstallerPath -and (Test-Path -LiteralPath $_fd.InstallerPath -PathType Leaf)) {
        $installer.sha256 = (Get-FileHash -LiteralPath $_fd.InstallerPath -Algorithm SHA256).Hash
        try {
          $sig = Get-AuthenticodeSignature -LiteralPath $_fd.InstallerPath
          $installer.status = [string]$sig.Status
          if ($sig.SignerCertificate) { $installer.signer = $sig.SignerCertificate.Subject; $installer.thumbprint = $sig.SignerCertificate.Thumbprint }
        } catch { $installer.status = '' }
      }
      $findings = if ($_fd.PackageKind -ne 'Printer') { @(Get-PreflightFindings -FormData $_fd -History $_history -Installer $installer) } else { @() }
      foreach ($finding in $findings) { Write-Host "  [$($finding.level)] $($finding.message)" }
      if (@($findings | Where-Object { $_.level -eq 'red' }).Count -and -not $_fd.OverrideRed) {
        $_bd.Add(@{ ok = $false; blocked = $true; findings = $findings; message = 'Pre-deploy checks stopped this build.' }) | Out-Null
        return
      }
      $result = Invoke-HeadlessPackageBuild -Config $_cfg -FormData $_fd -Profile $_profile
      $_bd.Add(@{ ok = $true; installer = $installer; findings = $findings; path = $result.OutputDir; paths = $result.OutputDirs; warning = $result.SyncWarning; appId = $_fd.AppID; displayName = $_fd.DisplayName; target = $_fd.SimplePkgTarget; profile = $_fd.ProfileName }) | Out-Null
    } catch {
      $_bd.Add(@{ ok = $false; message = $_.Exception.Message }) | Out-Null
    }
  })
  $handle = $ps.BeginInvoke()
  } catch {
    if ($ps) { $ps.Dispose() }
    $rs.Dispose()
    throw
  }
  $script:ActiveBuild = @{ PowerShell = $ps; Handle = $handle; Started = [Diagnostics.Stopwatch]::StartNew(); Id = [guid]::NewGuid().ToString('N') }
  $job = $script:ActiveBuild
  Write-AppLog "Build $($job.Id) started for $($FormData.AppID)" INFO
  $timer = New-Object System.Windows.Threading.DispatcherTimer
  $timer.Interval = [TimeSpan]::FromMilliseconds(150)
  $timer.Add_Tick({
    for ($i = 0; $i -lt 100 -and $bq.Count -gt 0; $i++) {
      $line = $bq.Dequeue()
      $parts = $line -split '\|', 2
      switch ($parts[0]) {
        'step' { $step = $parts[1] -split '\|', 2; Send-ToPage $Wv 'build-progress' @{ step = $step[0]; label = $step[1] } }
        default { Send-ToPage $Wv 'build-log' @{ line = $parts[1] } }
      }
    }
    if ($job.Started.Elapsed.TotalMinutes -gt 30 -and -not $handle.IsCompleted -and -not $job.StopHandle) {
      $job.StopHandle = $ps.BeginStop($null, $null)
    }
    if ($handle.IsCompleted -and $bq.Count -eq 0) {
      $timer.Stop()
      try {
        $ps.EndInvoke($handle) | Out-Null
        if ($bd.Count -ne 1) { throw 'Build ended without a result. Check the operation log.' }
        $done = $bd[0]
        if ($done.blocked) {
          Send-ToPage $Wv 'preflight-blocked' @{ findings = @($done.findings) }
          Write-AppLog "Build $($job.Id) stopped by pre-deploy checks" WARN
          return
        }
        if (-not $done.ok) { throw $done.message }
        if ($done.appId) { Set-DeployStatus -AppID $done.appId -AppName $done.displayName -Target $done.target -ProfileName $done.profile -OutputDir $done.path }
        try { Save-AppMemoryBuild -FormData $FormData -Installer $done.installer -OutputDir $done.path -Findings @($done.findings) }
        catch { Write-AppLog "Could not record the build in the app memory: $($_.Exception.Message)" WARN }
        $global:LastBuildDir = [string]$done.path
        $files = @(Get-ChildItem -LiteralPath $done.path -File -ErrorAction SilentlyContinue | ForEach-Object Name)
        $epmCsv = Join-Path $done.path 'EPM-rules.csv'
        # @() outside the if: assigning an if statement unrolls a one-row array into a single object.
        $epmRows = @(if ($FormData.SimplePkgTarget -eq 'epm' -and (Test-Path -LiteralPath $epmCsv)) { Import-Csv -LiteralPath $epmCsv | Select-Object FileName, SHA256, Signer, CertificateFile, SuggestedRule })
        Send-ToPage $Wv 'build-done' @{ path = $done.path; paths = $done.paths; warning = $done.warning; findings = @($done.findings); overridden = [bool]$FormData.OverrideRed; files = $files; epm = $epmRows }
        Write-AppLog "Build $($job.Id) succeeded in $([math]::Round($job.Started.Elapsed.TotalSeconds, 2))s" INFO
      } catch {
        Write-AppLog "Build $($job.Id) failed after $([math]::Round($job.Started.Elapsed.TotalSeconds, 2))s: $($_.Exception.Message)" ERROR
        Send-ToPage $Wv 'error' @{ message = $_.Exception.Message }
      } finally {
        $ps.Dispose(); $rs.Dispose()
        $job.Finished = $true
      }
    }
  }.GetNewClosure())
  $timer.Start()
}

$window.Add_Closing({
  param($sender, $eventArgs)
  if (($script:ActiveBuild -and -not $script:ActiveBuild.Finished) -or ($script:ActiveTest -and -not $script:ActiveTest.Finished)) {
    $eventArgs.Cancel = $true
    Send-ToPage $wv 'error' @{ message = 'An operation is still running. Wait for it to finish before closing AppUpdater.' }
  }
})
try { $window.ShowDialog() | Out-Null }
finally { $wv.Dispose() }
